  app.post('/api/pcn/drafts', async (req, res) => {
    if (DATABASE_PROFILE !== 'pcn') {
      res.status(404).json({ error: 'Soạn thảo PCN chỉ khả dụng trong profile PCN.' });
      return;
    }
    if (!requirePcnMutation(req, res)) return;
    const actor = getPcnSessionUser(req)!;
    const formKinds = new Set<PcnDraftFormKind>(['PROPOSAL_FORM', 'DOSSIER_COVER', 'ASSIGNMENT_FORM', 'EVALUATION_PLAN', 'FIELD_INSPECTION', 'SAMPLE_TAKING', 'SAMPLE_CODING', 'SAMPLE_HANDOVER', 'LAB_REQUEST', 'EVALUATION_REPORT', 'CERTIFICATION_RESULT', 'COMMERCIAL', 'CLIENT_PACKAGE']);
    const formKind = String(req.body?.formKind || '').trim().toUpperCase() as PcnDraftFormKind;
    const title = String(req.body?.title || '').trim();
    const templateId = String(req.body?.templateId || '').trim();
    const draftId = String(req.body?.id || '').trim() || `pcn-draft-${randomUUID()}`;
    const sourceProposalId = String(req.body?.sourceProposalId || '').trim();
    const sourceDossierId = String(req.body?.sourceDossierId || '').trim();
    const fieldCodes: string[] = Array.isArray(req.body?.fieldCodes)
      ? [...new Set(req.body.fieldCodes.map((item: unknown) => String(item).trim().toUpperCase()).filter(Boolean))] as string[]
      : [];
    const values = req.body?.values && typeof req.body.values === 'object' && !Array.isArray(req.body.values)
      ? Object.fromEntries(Object.entries(req.body.values).slice(0, 120).map(([key, value]) => [String(key).slice(0, 120), Array.isArray(value) ? value.slice(0, 50).map((item) => String(item).slice(0, 500)) : String(value ?? '').slice(0, 5000)]))
      : {};
    if (!formKinds.has(formKind) || !title || title.length > 240 || !templateId || templateId.length > 200 || draftId.length > 240 || /[\\/]/.test(draftId) || fieldCodes.some((code) => !PCN_CERTIFICATION_FIELD_CODES.includes(code as typeof PCN_CERTIFICATION_FIELD_CODES[number]))) {
      res.status(400).json({ error: 'Thông tin bản soạn thảo PCN không hợp lệ.' });
      return;
    }
    try {
      const result = await withPgTransaction(async (client) => {
        const existingResult = await client.query(
          `SELECT document_id, data FROM app_documents WHERE collection_name = 'pcnDraftWorkspaces' AND document_id = $1 LIMIT 1 FOR UPDATE`,
          [draftId],
        );
        const existing = existingResult.rows[0] ? mapDocumentRow(existingResult.rows[0]) as PcnDraftWorkspace : undefined;
        let sourceProposal: CertificationProposal | undefined;
        let sourceDossier: CertificationDossier | undefined;
        if (sourceDossierId) {
          const sourceDossierResult = await client.query(
            `SELECT document_id, data FROM app_documents WHERE collection_name = 'certificationDossiers' AND document_id = $1 LIMIT 1`,
            [sourceDossierId],
          );
          sourceDossier = sourceDossierResult.rows[0] ? mapDocumentRow(sourceDossierResult.rows[0]) as CertificationDossier : undefined;
        }
        const linkedProposalId = sourceProposalId || sourceDossier?.proposalId || '';
        if (linkedProposalId) {
          const sourceProposalResult = await client.query(
            `SELECT document_id, data FROM app_documents WHERE collection_name = 'certificationProposals' AND document_id = $1 LIMIT 1`,
            [linkedProposalId],
          );
          sourceProposal = sourceProposalResult.rows[0] ? mapDocumentRow(sourceProposalResult.rows[0]) as CertificationProposal : undefined;
        }
        validatePcnDraftSourceSelection({ sourceProposalId, sourceDossierId, proposal: sourceProposal, dossier: sourceDossier });
        const canonicalFieldCodes = sourceDossier?.fieldCodes?.length
          ? [...new Set(sourceDossier.fieldCodes.map((code) => String(code).trim().toUpperCase()))]
          : sourceProposal?.fieldCodes?.length
            ? [...new Set(sourceProposal.fieldCodes.map((code) => String(code).trim().toUpperCase()))]
            : fieldCodes;
        const now = new Date().toISOString();
        const draft: PcnDraftWorkspace = {
          id: draftId,
          title,
          formKind,
          templateId,
          ...(sourceProposalId ? { sourceProposalId } : {}),
          ...(sourceDossierId ? { sourceDossierId } : {}),
          fieldCodes: canonicalFieldCodes,
          values,
          status: 'DRAFT',
          outputAssetIds: [],
          outputs: [],
          createdByUsername: existing?.createdByUsername || actor.username,
          updatedByUsername: actor.username,
          createdAt: existing?.createdAt || now,
          updatedAt: now,
        };
        await client.query(
          `INSERT INTO app_documents (collection_name, document_id, data, updated_at)
           VALUES ('pcnDraftWorkspaces', $1, $2::jsonb, CURRENT_TIMESTAMP)
           ON CONFLICT (collection_name, document_id) DO UPDATE SET data = EXCLUDED.data, updated_at = CURRENT_TIMESTAMP`,
          [draft.id, JSON.stringify(getDocumentPayload(draft))],
        );
        const activityLog = buildActivityLog({ action: existing ? 'UPDATED' : 'CREATED', entityType: 'PCN_DRAFT', entityId: draft.id, entityLabel: draft.title, actorUsername: actor.username, actorName: actor.name, actorRole: actor.systemRole || actor.role, summary: existing ? 'Cập nhật bản soạn thảo PCN' : 'Tạo bản soạn thảo PCN', source: 'UI', createdAt: now, groupId: draft.id });
        const validationError = validateActivityLogPayload(activityLog);
        if (validationError) throw new Error(validationError);
        await client.query(
          `INSERT INTO app_documents (collection_name, document_id, data, updated_at)
           VALUES ('activityLogs', $1, $2::jsonb, CURRENT_TIMESTAMP)
           ON CONFLICT (collection_name, document_id) DO NOTHING`,
          [activityLog.id, JSON.stringify(getDocumentPayload(activityLog))],
        );
        return { draft, activityLog };
      });
      res.status(201).json(result);
    } catch (error: any) {
      console.error('PCN drafting save error:', error);
      res.status(400).json({ error: error?.message || String(error) });
    }
  });

  app.post('/api/pcn/assistant', async (req, res) => {
    if (DATABASE_PROFILE !== 'pcn') {
      res.status(404).json({ error: 'Trợ lý PCN chỉ khả dụng trong profile PCN.' });
      return;
    }
    if (!requirePcnSession(req, res)) return;
    const message = String(req.body?.message || '').trim().slice(0, 2000);
    if (!message) {
      res.status(400).json({ error: 'Hãy nhập câu hỏi cho trợ lý PCN.' });
      return;
    }
    try {
      const [dossiersResult, proposalsResult, requestsResult, resultsResult, lotsResult, routesResult, requirementsResult, documentsResult] = await Promise.all([
        pool.query(`SELECT document_id, data FROM app_documents WHERE collection_name = 'certificationDossiers' ORDER BY updated_at DESC LIMIT 200`),
        pool.query(`SELECT document_id, data FROM app_documents WHERE collection_name = 'certificationProposals' ORDER BY updated_at DESC LIMIT 200`),
        pool.query(`SELECT document_id, data FROM app_documents WHERE collection_name = 'labRequests' ORDER BY updated_at DESC LIMIT 500`),
        pool.query(`SELECT document_id, data FROM app_documents WHERE collection_name = 'returnedResults' ORDER BY updated_at DESC LIMIT 500`),
        pool.query(`SELECT document_id, data FROM app_documents WHERE collection_name = 'pcnSampleLots' ORDER BY updated_at DESC LIMIT 500`),
        pool.query(`SELECT document_id, data FROM app_documents WHERE collection_name = 'pcnSampleRoutes' ORDER BY updated_at DESC LIMIT 1000`),
        pool.query(`SELECT document_id, data FROM app_documents WHERE collection_name = 'pcnDocumentRequirements' AND COALESCE((data->>'active')::boolean, false) = true LIMIT 500`),
        pool.query(`SELECT document_id, data FROM app_documents WHERE collection_name = 'dossierDocuments' ORDER BY updated_at DESC LIMIT 2000`),
      ]);
      const dossiers = dossiersResult.rows.map(mapDocumentRow) as CertificationDossier[];
      const proposals = proposalsResult.rows.map(mapDocumentRow) as CertificationProposal[];
      const activeSnapshot = filterPcnFutureWorkSnapshot({ proposals, dossiers, customers: [] });
      const activeDossierIds = new Set(activeSnapshot.dossiers.map((dossier) => dossier.id));
      const sampleLotRecords = lotsResult.rows.map(mapDocumentRow) as PcnSampleLot[];
      const sampleLots = sampleLotRecords.filter((lot) => activeDossierIds.has(String(lot.dossierId || '')));
      const activeLotIds = new Set(sampleLots.map((lot) => lot.id));
      const sampleRouteRecords = routesResult.rows.map(mapDocumentRow) as PcnSampleRoute[];
      const sampleRoutes = sampleRouteRecords.filter((route) => activeLotIds.has(String(route.sampleLotId || '')));
      const labRequestRecords = requestsResult.rows.map(mapDocumentRow) as OutboundLabRequest[];
      const labRequests = labRequestRecords.filter((request) => activeDossierIds.has(String(request.dossierId || '')));
      const activeRequestIds = new Set(labRequests.map((request) => request.id));
      const returnedResultRecords = resultsResult.rows.map(mapDocumentRow) as ReturnedTestResult[];
      const returnedResults = returnedResultRecords.filter((result) => activeDossierIds.has(String(result.dossierId || '')) || activeRequestIds.has(String(result.labRequestId || '')));
      const requirements = requirementsResult.rows.map(mapDocumentRow) as PcnDocumentRequirement[];
      const documentRecords = documentsResult.rows.map(mapDocumentRow) as PcnDossierDocument[];
      const documents = documentRecords.filter((document) => activeDossierIds.has(String(document.dossierId || '')));
      const context = JSON.stringify(buildPcnAssistantSnapshot({
        dossiers: activeSnapshot.dossiers,
        proposals: activeSnapshot.proposals,
        requirements,
        documents,
        labRequests,
        sampleLots,
        sampleRoutes,
        returnedResults,
      }));
      const ai = await getGeminiClient(req, { timeout: 30000 });
      const response = await generateContentWithRetryAndFallback(ai, {
        contents: [{ role: 'user', parts: [{ text: `Bạn là trợ lý AI vận hành của Phòng Chứng nhận PCN thuộc TVCI. Chỉ sử dụng snapshot PCN dưới đây. Không dùng thuật ngữ lịch thử, không nói thay Phòng Giám định, không bịa dữ liệu và không tự đề nghị mutation. Trả lời tiếng Việt ngắn gọn, nêu rõ mã hồ sơ/PYC nếu có, bước 1-5 liên quan và hành động người dùng cần mở trong card. Nếu snapshot không đủ, nói rõ cần kiểm tra trực tiếp trong hồ sơ.\n\nSnapshot PCN:\n${context}\n\nCâu hỏi người dùng:\n${message}` }] }],
        config: { temperature: 0.2 },
      }, req.headers['x-gemini-model'] as string | undefined || await getPcnStoredGeminiModel(req), { attemptsPerModel: 1 });
      res.json({ response: String(response.text || '').trim() || 'Trợ lý chưa có câu trả lời.' });
    } catch (error: any) {
      console.error('PCN assistant error:', error);
      res.status(503).json({ error: error?.message || 'Trợ lý AI PCN hiện chưa sẵn sàng.' });
    }
  });

  app.post('/api/pcn/drafts/:draftId/generate', async (req, res) => {
    if (DATABASE_PROFILE !== 'pcn') {
      res.status(404).json({ error: 'Soạn thảo PCN chỉ khả dụng trong profile PCN.' });
      return;
    }
    if (!requirePcnMutation(req, res)) return;
    const actor = getPcnSessionUser(req)!;
    const draftId = String(req.params.draftId || '').trim();
    const requestedFormats = Array.isArray(req.body?.formats) && req.body.formats.length > 0 ? req.body.formats : ['DOCX', 'PDF'];
    const formats = [...new Set(requestedFormats.map((format: unknown) => String(format).trim().toUpperCase()))] as PcnGeneratedDocumentFormat[];
    if (!draftId || draftId.length > 240 || formats.length === 0 || formats.some((format) => !['DOCX', 'PDF'].includes(format))) {
      res.status(400).json({ error: 'Bản soạn thảo hoặc định dạng file không hợp lệ.' });
      return;
    }
    const uploadedObjects: Array<{ bucketName: string; objectPath: string }> = [];
    try {
      const result = await withPgTransaction(async (client) => {
        const draftResult = await client.query(`SELECT document_id, data FROM app_documents WHERE collection_name = 'pcnDraftWorkspaces' AND document_id = $1 LIMIT 1 FOR UPDATE`, [draftId]);
        if (!draftResult.rows[0]) throw Object.assign(new Error('Không tìm thấy bản soạn thảo PCN.'), { statusCode: 404 });
        const draft = mapDocumentRow(draftResult.rows[0]) as PcnDraftWorkspace;
        const draftValidation = validatePcnDraftAction(draft.formKind, draft.values, 'GENERATE');
        if (!draftValidation.valid) throw Object.assign(new Error(`Chưa thể tạo file. Còn thiếu: ${draftValidation.missingKeys.join(', ')}`), { statusCode: 400 });
        const template = getPcnOperationalTemplateForKind(draft.formKind as any, draft.fieldCodes);
        if (!template || template.usage === 'REFERENCE_ONLY') throw Object.assign(new Error('Template này chỉ để tham chiếu hoặc chưa có bản sinh vận hành.'), { statusCode: 409 });
        let proposal: CertificationProposal | undefined;
        let dossier: CertificationDossier | undefined;
        if (draft.sourceDossierId) {
          const dossierResult = await client.query(`SELECT document_id, data FROM app_documents WHERE collection_name = 'certificationDossiers' AND document_id = $1 LIMIT 1`, [draft.sourceDossierId]);
          dossier = dossierResult.rows[0] ? mapDocumentRow(dossierResult.rows[0]) as CertificationDossier : undefined;
        }
        const proposalId = draft.sourceProposalId || dossier?.proposalId;
        if (proposalId) {
          const proposalResult = await client.query(`SELECT document_id, data FROM app_documents WHERE collection_name = 'certificationProposals' AND document_id = $1 LIMIT 1`, [proposalId]);
          proposal = proposalResult.rows[0] ? mapDocumentRow(proposalResult.rows[0]) as CertificationProposal : undefined;
        }
        if (!dossier && proposal?.dossierId) {
          const dossierResult = await client.query(`SELECT document_id, data FROM app_documents WHERE collection_name = 'certificationDossiers' AND document_id = $1 LIMIT 1`, [proposal.dossierId]);
          dossier = dossierResult.rows[0] ? mapDocumentRow(dossierResult.rows[0]) as CertificationDossier : undefined;
        }
        validatePcnDraftSourceSelection({ sourceProposalId: draft.sourceProposalId, sourceDossierId: draft.sourceDossierId, proposal, dossier });
        const manualSource = !draft.sourceProposalId && !draft.sourceDossierId
          ? buildPcnDraftManualSource(draft, new Date().toISOString())
          : undefined;
        if (!proposal && manualSource) {
          proposal = manualSource.proposal;
          if (!dossier) dossier = manualSource.dossier;
        }
        if (!proposal) throw Object.assign(new Error('Không đủ nguồn dữ liệu để tạo tài liệu. Hãy chọn số Đề nghị/Hồ sơ hoặc nhập đầy đủ thông tin form.'), { statusCode: 400 });
        if (!dossier) {
          dossier = { id: `draft-source-${draft.id}`, dossierCode: String(draft.values.ma_ho_so || '').trim() || `DRAFT-${draft.id.slice(-8)}`, proposalId: proposal.id, fieldCodes: draft.fieldCodes.length ? draft.fieldCodes : proposal.fieldCodes, method: 'METHOD_1', status: 'INTAKE_REVIEW', labRequestIds: [], returnedResultIds: [] };
        }
        const fieldCodes = dossier.fieldCodes.length ? dossier.fieldCodes : proposal.fieldCodes;
        const [fieldsResult, requirementsResult, documentsResult, attachmentsResult, lotsResult, routesResult, requestsResult] = await Promise.all([
          client.query(`SELECT document_id, data FROM app_documents WHERE collection_name = 'pcnCertificationFields' AND data->>'code' = ANY($1::text[])`, [fieldCodes]),
          client.query(`SELECT document_id, data FROM app_documents WHERE collection_name = 'pcnDocumentRequirements' AND COALESCE((data->>'active')::boolean, false) = true AND data->>'fieldCode' = ANY($1::text[])`, [fieldCodes]),
          client.query(`SELECT document_id, data FROM app_documents WHERE collection_name = 'dossierDocuments' AND data->>'dossierId' = $1`, [dossier.id]),
          client.query(`SELECT document_id, data FROM app_documents WHERE collection_name = 'dossierAttachments' AND data->>'dossierId' = $1`, [dossier.id]),
          client.query(`SELECT document_id, data FROM app_documents WHERE collection_name = 'pcnSampleLots' AND data->>'dossierId' = $1`, [dossier.id]),
          client.query(`SELECT document_id, data FROM app_documents WHERE collection_name = 'pcnSampleRoutes'`),
          client.query(`SELECT document_id, data FROM app_documents WHERE collection_name = 'labRequests' AND data->>'dossierId' = $1`, [dossier.id]),
        ]);
        const context = buildPcnDossierDocumentContext({ dossier, proposal, fields: fieldsResult.rows.map(mapDocumentRow) as PcnCertificationField[], documents: documentsResult.rows.map(mapDocumentRow) as PcnDossierDocument[], documentRequirements: requirementsResult.rows.map(mapDocumentRow) as PcnDocumentRequirement[], attachments: attachmentsResult.rows.map(mapDocumentRow) as PcnDossierAttachment[], sampleLots: lotsResult.rows.map(mapDocumentRow) as PcnSampleLot[], sampleRoutes: routesResult.rows.map(mapDocumentRow) as PcnSampleRoute[], labRequests: requestsResult.rows.map(mapDocumentRow) as OutboundLabRequest[] });
        const contextHash = createHash('sha256').update(JSON.stringify({ contextHash: context.contextHash, draftId: draft.id, formKind: draft.formKind, values: draft.values })).digest('hex');
        const sourceTemplateDocx = renderPcnOperationalTemplateDocx(draft.formKind as any, context, {
          ...draft.values,
          ...(manualSource ? { method_label: String(draft.values.method_label || '') } : {}),
        });
        if (!sourceTemplateDocx) throw Object.assign(new Error('Không thể dựng DOCX từ template PCN đã chọn.'), { statusCode: 409 });
        const storage = getPcnStorageClient();
        const bucketName = getPcnStorageBucket();
        await storage.ensurePrivateBucket(bucketName, PCN_FILE_MAX_BYTES);
        const outputs: PcnDraftOutput[] = [];
        const safeDraftId = sanitizePcnPathSegment(draft.id).toLowerCase().replace(/[^a-z0-9-]+/g, '-').slice(0, 48) || 'draft';
        const safeTitle = sanitizePcnPathSegment(draft.title).replace(/[^a-zA-Z0-9-_]+/g, '-').slice(0, 80) || 'pcn-draft';
        for (const format of formats) {
          const body = format === 'DOCX' ? sourceTemplateDocx : await renderPcnDocxToPdf(sourceTemplateDocx, `${safeTitle}.docx`);
          const sha256 = createHash('sha256').update(body).digest('hex');
          const extension = format.toLowerCase();
          const mimeType = format === 'DOCX' ? 'application/vnd.openxmlformats-officedocument.wordprocessingml.document' : 'application/pdf';
          const outputId = `pcn-draft-output-${safeDraftId}-${contextHash.slice(0, 16)}-${extension}`;
          const assetId = `pcn-file-draft-${safeDraftId}-${contextHash.slice(0, 16)}-${extension}`;
          const objectPath = `pcnDraftWorkspaces/${safeDraftId}/${contextHash}/${extension}`;
          const fileName = `${safeTitle}.${extension}`;
          const assetResult = await client.query(`SELECT id, bucket_name, object_path, source_collection, source_document_id, source_json_path, mime_type, byte_size, sha256 FROM file_assets WHERE id = $1 LIMIT 1`, [assetId]);
          const existingAsset = assetResult.rows[0];
          if (existingAsset && (existingAsset.bucket_name !== bucketName || existingAsset.object_path !== objectPath || existingAsset.source_collection !== 'pcnDraftWorkspaces' || existingAsset.source_document_id !== draft.id || existingAsset.source_json_path !== 'outputs' || existingAsset.mime_type !== mimeType || Number(existingAsset.byte_size) !== body.length || String(existingAsset.sha256).toLowerCase() !== sha256)) throw new Error('Asset bản soạn thảo không khớp metadata provenance.');
          if (!existingAsset) { await storage.uploadObject({ bucketName, objectPath, body, mimeType }); uploadedObjects.push({ bucketName, objectPath }); await client.query(`INSERT INTO file_assets (id, bucket_name, object_path, source_collection, source_document_id, source_json_path, mime_type, byte_size, sha256) VALUES ($1, $2, $3, 'pcnDraftWorkspaces', $4, 'outputs', $5, $6, $7)`, [assetId, bucketName, objectPath, draft.id, mimeType, body.length, sha256]); }
          outputs.push({ id: outputId, format, fileAssetId: assetId, fileName, mimeType, byteSize: body.length, sha256, generatedAt: new Date().toISOString() });
        }
        const now = new Date().toISOString();
        const nextDraft: PcnDraftWorkspace = { ...draft, status: 'GENERATED', outputAssetIds: outputs.map((output) => output.fileAssetId), outputs, updatedByUsername: actor.username, updatedAt: now };
        await client.query(`UPDATE app_documents SET data = $2::jsonb, updated_at = CURRENT_TIMESTAMP WHERE collection_name = 'pcnDraftWorkspaces' AND document_id = $1`, [draft.id, JSON.stringify(getDocumentPayload(nextDraft))]);
        const activityLog = buildActivityLog({ action: 'UPDATED', entityType: 'PCN_DRAFT', entityId: draft.id, entityLabel: draft.title, actorUsername: actor.username, actorName: actor.name, actorRole: actor.systemRole || actor.role, summary: `Sinh ${outputs.map((output) => output.format).join(' + ')} từ bản soạn thảo PCN`, source: 'UI', createdAt: now, groupId: contextHash });
        const validationError = validateActivityLogPayload(activityLog);
        if (validationError) throw new Error(validationError);
        await client.query(`INSERT INTO app_documents (collection_name, document_id, data, updated_at) VALUES ('activityLogs', $1, $2::jsonb, CURRENT_TIMESTAMP) ON CONFLICT (collection_name, document_id) DO NOTHING`, [activityLog.id, JSON.stringify(getDocumentPayload(activityLog))]);
        return { draft: nextDraft, activityLog };
      });
      res.status(201).json(result);
    } catch (error: any) {
      for (const uploaded of uploadedObjects.reverse()) { try { await getPcnStorageClient().deleteObject(uploaded); } catch { /* keep original error */ } }
      console.error('PCN drafting generation error:', error);
      res.status(Number(error?.statusCode) || 500).json({ error: error?.message || String(error) });
    }
  });

  app.post('/api/pcn/documents/generate', async (req, res) => {
    if (DATABASE_PROFILE !== 'pcn') {
      res.status(404).json({ error: 'Sinh tài liệu PCN chỉ khả dụng trong profile PCN.' });
      return;
    }
    if (!getPcnSessionUser(req)) {
      res.status(401).json({ error: 'Phiên PCN không hợp lệ hoặc đã hết hạn.' });
      return;
    }
    const dryRun = req.body?.dryRun === true;
    if (!dryRun && !requirePcnMutation(req, res)) return;
    const dossierId = String(req.body?.dossierId || '').trim();
    const kind = String(req.body?.kind || 'DOSSIER_COVER').trim().toUpperCase() as PcnGeneratedDocumentKind;
    const sampleRouteId = String(req.body?.sampleRouteId || '').trim();
    const labRequestId = String(req.body?.labRequestId || '').trim();
    const expectedContextHash = String(req.body?.expectedContextHash || '').trim();
    const requestedFormats = Array.isArray(req.body?.formats) && req.body.formats.length > 0
      ? req.body.formats
      : ['DOCX', 'PDF'];
    const invalidFormat = requestedFormats.some((format: unknown) => !['DOCX', 'PDF'].includes(String(format).trim().toUpperCase()));
    const formats = Array.from(new Set(requestedFormats.map((format: unknown) => String(format).trim().toUpperCase()))) as PcnGeneratedDocumentFormat[];
    if (!dossierId || !['DOSSIER_COVER', 'PROPOSAL_SUMMARY', 'PROPOSAL_FORM', 'ASSIGNMENT_FORM', 'EVALUATION_PLAN', 'FIELD_INSPECTION', 'SAMPLE_TAKING', 'SAMPLE_CODING', 'EVALUATION_REPORT', 'SAMPLE_HANDOVER', 'SAMPLE_RETURN', 'LAB_REQUEST'].includes(kind) || ((kind === 'SAMPLE_TAKING' || kind === 'SAMPLE_HANDOVER' || kind === 'SAMPLE_RETURN' || kind === 'SAMPLE_CODING') && !sampleRouteId) || (kind === 'LAB_REQUEST' && !labRequestId) || invalidFormat || formats.length === 0 || (expectedContextHash && !/^[a-f0-9]{64}$/i.test(expectedContextHash))) {
      res.status(400).json({ error: 'Thiếu mã hồ sơ hoặc định dạng tài liệu PCN không hợp lệ.' });
      return;
    }

    const uploadedObjects: Array<{ bucketName: string; objectPath: string }> = [];
    try {
      const storage = dryRun ? undefined : getPcnStorageClient();
      const bucketName = dryRun ? '' : getPcnStorageBucket();
      if (storage) await storage.ensurePrivateBucket(bucketName, PCN_FILE_MAX_BYTES);
      const result = await withPgTransaction(async (client) => {
        const dossierResult = await client.query(
          `SELECT document_id, data FROM app_documents
           WHERE collection_name = 'certificationDossiers' AND document_id = $1
           LIMIT 1${dryRun ? '' : ' FOR UPDATE'}`,
          [dossierId],
        );
        if (dossierResult.rows.length === 0) throw new Error('Không tìm thấy hồ sơ cần sinh tài liệu.');
        const dossier = mapDocumentRow(dossierResult.rows[0]) as CertificationDossier;
        if (!dryRun && !canProcessPcnGeneratedDocument(dossier, kind)) {
          throw Object.assign(new Error('Biểu mẫu thuộc bước chưa đến; hãy hoàn tất bước hiện tại trước.'), { statusCode: 409 });
        }
        const proposalId = String(dossier.proposalId || '').trim();
        if (!proposalId) throw new Error('Hồ sơ chưa có Đề nghị liên kết để sinh tài liệu.');

        const proposalResult = await client.query(
          `SELECT document_id, data FROM app_documents
           WHERE collection_name = 'certificationProposals' AND document_id = $1
           LIMIT 1${dryRun ? '' : ' FOR UPDATE'}`,
          [proposalId],
        );
        if (proposalResult.rows.length === 0) throw new Error('Không tìm thấy Đề nghị liên kết với hồ sơ.');
        const proposal = mapDocumentRow(proposalResult.rows[0]) as CertificationProposal;
        const fieldCodes = Array.isArray(dossier.fieldCodes)
          ? dossier.fieldCodes.map((code) => String(code).trim().toUpperCase()).filter(Boolean)
          : [];
        const [fieldsResult, requirementsResult, documentsResult, attachmentsResult, sampleLotsResult, sampleRoutesResult, labRequestsResult] = await Promise.all([
          client.query(
            `SELECT document_id, data FROM app_documents
             WHERE collection_name = 'pcnCertificationFields' AND data->>'code' = ANY($1::text[])`,
            [fieldCodes],
          ),
          client.query(
            `SELECT document_id, data FROM app_documents
             WHERE collection_name = 'pcnDocumentRequirements'
               AND COALESCE((data->>'active')::boolean, false) = true
               AND data->>'fieldCode' = ANY($1::text[])`,
            [fieldCodes],
          ),
          client.query(
            `SELECT document_id, data FROM app_documents
             WHERE collection_name = 'dossierDocuments' AND data->>'dossierId' = $1`,
            [dossier.id],
          ),
          client.query(
            `SELECT document_id, data FROM app_documents
             WHERE collection_name = 'dossierAttachments' AND data->>'dossierId' = $1`,
            [dossier.id],
          ),
          client.query(
            `SELECT document_id, data FROM app_documents
             WHERE collection_name = 'pcnSampleLots' AND data->>'dossierId' = $1`,
            [dossier.id],
          ),
          client.query(
            `SELECT document_id, data FROM app_documents
             WHERE collection_name = 'pcnSampleRoutes'`,
          ),
          client.query(
            `SELECT document_id, data FROM app_documents
             WHERE collection_name = 'labRequests' AND data->>'dossierId' = $1`,
            [dossier.id],
          ),
        ]);
        const fields = fieldsResult.rows.map(mapDocumentRow) as PcnCertificationField[];
        const documentRequirements = requirementsResult.rows.map(mapDocumentRow) as PcnDocumentRequirement[];
        const documents = documentsResult.rows.map(mapDocumentRow) as PcnDossierDocument[];
        const attachments = attachmentsResult.rows.map(mapDocumentRow) as PcnDossierAttachment[];
        const sampleLots = sampleLotsResult.rows.map(mapDocumentRow) as PcnSampleLot[];
        const sampleRoutes = sampleRoutesResult.rows.map(mapDocumentRow) as PcnSampleRoute[];
        const labRequests = labRequestsResult.rows.map(mapDocumentRow) as OutboundLabRequest[];
        const context = buildPcnDossierDocumentContext({
          dossier,
          proposal,
          fields,
          documents,
          documentRequirements,
          attachments,
          sampleLots,
          sampleRoutes,
          labRequests,
          ...(['SAMPLE_TAKING', 'SAMPLE_HANDOVER', 'SAMPLE_RETURN', 'SAMPLE_CODING'].includes(kind) ? { sampleRouteId } : {}),
          ...(kind === 'LAB_REQUEST' ? { labRequestId } : {}),
        });
        const contextConflict = getPcnDocumentContextConflict(expectedContextHash || undefined, context.contextHash);
        if (contextConflict) throw Object.assign(new Error(contextConflict.message), { statusCode: 409, code: contextConflict.code });
        if (dryRun) return { context, documents: [], activityLogs: [] };
        if (!storage) throw new Error('Storage PCN chưa được cấu hình để sinh tài liệu.');
        const existingResult = await client.query(
          `SELECT document_id, data FROM app_documents
           WHERE collection_name = 'pcnGeneratedDocuments'
             AND data->>'dossierId' = $1
             AND data->>'kind' = $3
             AND data->>'contextHash' = $2`,
          [dossier.id, context.contextHash, kind],
        );
        const existingByFormat = new Map<string, PcnGeneratedDocument>(
          existingResult.rows.map((row: any) => [String(row.data?.format || '').toUpperCase(), mapDocumentRow(row) as PcnGeneratedDocument]),
        );
        const generatedDocuments: PcnGeneratedDocument[] = [];
        const createdActivityLogs: ReturnType<typeof buildActivityLog>[] = [];
        const generatedAt = new Date().toISOString();
        let createdAny = false;
        const safeDossierId = sanitizePcnPathSegment(dossier.id).toLowerCase().replace(/[^a-z0-9-]+/g, '-').slice(0, 36) || 'dossier';
        const safeDossierCode = sanitizePcnPathSegment(dossier.dossierCode || dossier.id).toLowerCase();

        for (const format of formats) {
          const existing = existingByFormat.get(format);
          if (existing?.fileAssetId) {
            const existingAssetResult = await client.query(
              `SELECT id, bucket_name, object_path, source_collection, source_document_id, source_json_path, mime_type, byte_size, sha256
               FROM file_assets WHERE id = $1 LIMIT 1`,
              [existing.fileAssetId],
            );
            const existingAsset = existingAssetResult.rows[0];
            if (!existingAsset
              || existingAsset.source_collection !== 'pcnGeneratedDocuments'
              || existingAsset.source_document_id !== existing.id
              || existingAsset.source_json_path !== 'fileAssetId'
              || existingAsset.mime_type !== existing.mimeType
              || Number(existingAsset.byte_size) !== Number(existing.byteSize)
              || String(existingAsset.sha256).toLowerCase() !== String(existing.sha256).toLowerCase()) {
              throw new Error('Asset bản sinh tài liệu không khớp metadata provenance; cần rà soát trước khi tái sử dụng.');
            }
            generatedDocuments.push(existing);
            continue;
          }
          const sourceTemplateDocx = format === 'DOCX' ? renderPcnOperationalTemplateDocx(kind, context) : undefined;
          const body = kind === 'DOSSIER_COVER'
            ? format === 'DOCX' ? sourceTemplateDocx || buildPcnDossierCoverDocx(context) : await buildPcnDossierCoverPdf(context)
            : kind === 'PROPOSAL_SUMMARY'
              ? format === 'DOCX' ? buildPcnProposalSummaryDocx(context) : await buildPcnProposalSummaryPdf(context)
              : kind === 'PROPOSAL_FORM'
              ? format === 'DOCX' ? sourceTemplateDocx || buildPcnProposalFormDocx(context) : await buildPcnProposalFormPdf(context)
              : kind === 'ASSIGNMENT_FORM'
                ? format === 'DOCX' ? sourceTemplateDocx || buildPcnAssignmentFormDocx(context) : await buildPcnAssignmentFormPdf(context)
              : kind === 'EVALUATION_PLAN'
                ? format === 'DOCX' ? sourceTemplateDocx || buildPcnEvaluationPlanDocx(context) : await buildPcnEvaluationPlanPdf(context)
              : kind === 'FIELD_INSPECTION'
                ? format === 'DOCX' ? sourceTemplateDocx || buildPcnFieldInspectionDocx(context) : await buildPcnFieldInspectionPdf(context)
              : kind === 'SAMPLE_TAKING'
                ? format === 'DOCX' ? sourceTemplateDocx || buildPcnSampleTakingDocx(context) : await buildPcnSampleTakingPdf(context)
              : kind === 'SAMPLE_CODING'
                ? format === 'DOCX' ? sourceTemplateDocx || buildPcnSampleCodingDocx(context) : await buildPcnSampleCodingPdf(context)
              : kind === 'EVALUATION_REPORT'
                ? format === 'DOCX' ? sourceTemplateDocx || buildPcnEvaluationReportDocx(context) : await buildPcnEvaluationReportPdf(context)
                : kind === 'SAMPLE_HANDOVER'
                ? format === 'DOCX' ? sourceTemplateDocx || buildPcnSampleHandoverDocx(context) : await buildPcnSampleHandoverPdf(context)
                : kind === 'SAMPLE_RETURN'
                ? format === 'DOCX' ? buildPcnSampleReturnDocx(context) : await buildPcnSampleReturnPdf(context)
                : format === 'DOCX' ? sourceTemplateDocx || buildPcnLabRequestDocx(context) : await buildPcnLabRequestPdf(context);
          const sha256 = createHash('sha256').update(body).digest('hex');
          const extension = format.toLowerCase();
          const mimeType = format === 'DOCX'
            ? 'application/vnd.openxmlformats-officedocument.wordprocessingml.document'
            : 'application/pdf';
          const kindSlug = kind === 'DOSSIER_COVER' ? 'cover' : kind === 'PROPOSAL_SUMMARY' ? 'proposal-summary' : kind === 'PROPOSAL_FORM' ? 'proposal-form' : kind === 'ASSIGNMENT_FORM' ? 'assignment-form' : kind === 'EVALUATION_PLAN' ? 'evaluation-plan' : kind === 'FIELD_INSPECTION' ? 'field-inspection' : kind === 'SAMPLE_TAKING' ? 'sample-taking' : kind === 'SAMPLE_CODING' ? 'sample-coding' : kind === 'EVALUATION_REPORT' ? 'evaluation-report' : kind === 'SAMPLE_HANDOVER' ? 'sample-handover' : kind === 'SAMPLE_RETURN' ? 'sample-return' : 'lab-request';
          const kindFileName = kind === 'DOSSIER_COVER' ? 'bia-muc-luc' : kind === 'PROPOSAL_SUMMARY' ? 'phieu-tom-tat-de-nghi' : kind === 'PROPOSAL_FORM' ? 'de-nghi-chung-nhan' : kind === 'ASSIGNMENT_FORM' ? 'phieu-phan-cong-chung-nhan' : kind === 'EVALUATION_PLAN' ? 'ke-hoach-danh-gia-cnsp' : kind === 'FIELD_INSPECTION' ? 'bien-ban-kiem-tra-hien-truong' : kind === 'SAMPLE_TAKING' ? 'bien-ban-lay-mau' : kind === 'SAMPLE_CODING' ? 'bien-ban-ma-hoa-mau' : kind === 'EVALUATION_REPORT' ? 'bao-cao-danh-gia-ho-so' : kind === 'SAMPLE_HANDOVER' ? 'bien-ban-giao-nhan-mau' : kind === 'SAMPLE_RETURN' ? 'bien-ban-tra-mau' : 'phieu-yeu-cau-thu-nghiem';
          const sourceLot = context.sampleHandover?.lotId
            ? sampleLots.find((lot) => lot.id === context.sampleHandover?.lotId)
            : context.labRequest?.sampleLotId ? sampleLots.find((lot) => lot.id === context.labRequest?.sampleLotId) : undefined;
          const sourceRoute = context.sampleHandover?.routeId
            ? sampleRoutes.find((route) => route.id === context.sampleHandover?.routeId)
            : context.labRequest?.sampleRouteId ? sampleRoutes.find((route) => route.id === context.labRequest?.sampleRouteId) : undefined;
          const sourcePyc = context.sampleHandover?.labRequestId
            ? labRequests.find((request) => request.id === context.sampleHandover?.labRequestId)
            : context.labRequest?.requestId ? labRequests.find((request) => request.id === context.labRequest?.requestId) : undefined;
          const assetId = `pcn-file-generated-${safeDossierId}-${kindSlug}-${extension}-${context.contextHash.slice(0, 16)}`;
          const documentId = `pcn-generated-${safeDossierId}-${kindSlug}-${extension}-${context.contextHash.slice(0, 16)}`;
          const objectPath = `pcnGenerated/${safeDossierId}/${kind}/${context.contextHash}/${extension}`;
          const selectionSuffix = context.sampleHandover
            ? `-${sanitizePcnPathSegment(context.sampleHandover.routeId).toLowerCase().slice(0, 24)}`
            : context.labRequest ? `-${sanitizePcnPathSegment(context.labRequest.pycNumber || context.labRequest.requestId).toLowerCase().slice(0, 24)}` : '';
          const fileName = `${safeDossierCode}-${kindFileName}${selectionSuffix}.${extension}`;
          const sourceUpdatedAt = getPcnDocumentSourceUpdatedAt(dossier.updatedAt, proposal.updatedAt, sourceLot?.updatedAt, sourceRoute?.updatedAt, sourcePyc?.updatedAt, context.labRequest?.updatedAt, context.labRequest?.sampleLotUpdatedAt, context.labRequest?.routeUpdatedAt);
          const assetResult = await client.query(
            `SELECT id, bucket_name, object_path, source_collection, source_document_id, source_json_path, mime_type, byte_size, sha256
             FROM file_assets WHERE id = $1 LIMIT 1`,
            [assetId],
          );
          const existingAsset = assetResult.rows[0];
          if (existingAsset && (
            existingAsset.bucket_name !== bucketName
            || existingAsset.object_path !== objectPath
            || existingAsset.source_collection !== 'pcnGeneratedDocuments'
            || existingAsset.source_document_id !== documentId
            || existingAsset.source_json_path !== 'fileAssetId'
            || existingAsset.mime_type !== mimeType
            || Number(existingAsset.byte_size) !== body.length
            || String(existingAsset.sha256).toLowerCase() !== sha256
          )) {
            throw new Error('Asset bản sinh tài liệu trùng mã nhưng metadata provenance không khớp.');
          }
          if (!existingAsset) {
            await storage.uploadObject({ bucketName, objectPath, body, mimeType });
            uploadedObjects.push({ bucketName, objectPath });
            await client.query(
              `INSERT INTO file_assets (id, bucket_name, object_path, source_collection, source_document_id, source_json_path, mime_type, byte_size, sha256)
               VALUES ($1, $2, $3, 'pcnGeneratedDocuments', $4, 'fileAssetId', $5, $6, $7)`,
              [assetId, bucketName, objectPath, documentId, mimeType, body.length, sha256],
            );
          }
          const generated: PcnGeneratedDocument = {
            id: documentId,
            dossierId: dossier.id,
            kind,
            format,
            ...(context.labRequest?.requestId ? { labRequestId: context.labRequest.requestId } : {}),
            ...(context.sampleHandover?.lotId ? { sampleLotId: context.sampleHandover.lotId } : {}),
            ...(context.sampleHandover?.routeId ? { sampleRouteId: context.sampleHandover.routeId } : {}),
            fileAssetId: assetId,
            fileName,
            mimeType,
            byteSize: body.length,
            sha256,
            contextHash: context.contextHash,
            ...(sourceUpdatedAt ? { sourceUpdatedAt } : {}),
            generatedAt,
            ...(getPcnSessionUser(req)?.username ? { generatedBy: getPcnSessionUser(req)!.username } : {}),
          };
          const write = await client.query(
            `INSERT INTO app_documents (collection_name, document_id, data, updated_at)
             VALUES ('pcnGeneratedDocuments', $1, $2::jsonb, CURRENT_TIMESTAMP)
             ON CONFLICT (collection_name, document_id) DO NOTHING
             RETURNING document_id, data`,
            [generated.id, JSON.stringify(getDocumentPayload(generated))],
          );
          if (write.rows.length > 0) {
            createdAny = true;
            generatedDocuments.push(mapDocumentRow(write.rows[0]) as PcnGeneratedDocument);
          } else {
            const concurrent = await client.query(
              `SELECT document_id, data FROM app_documents
               WHERE collection_name = 'pcnGeneratedDocuments' AND document_id = $1 LIMIT 1`,
              [generated.id],
            );
            generatedDocuments.push((concurrent.rows[0] ? mapDocumentRow(concurrent.rows[0]) : generated) as PcnGeneratedDocument);
          }
        }

        if (createdAny) {
          const user = getPcnSessionUser(req);
          const log = buildActivityLog({
            action: 'CREATED',
            entityType: 'PCN_DOSSIER',
            entityId: dossier.id,
            entityLabel: dossier.dossierCode,
            actorUsername: user?.username,
            actorName: user?.name || 'Người dùng PCN',
            actorRole: user?.role,
            summary: kind === 'DOSSIER_COVER'
              ? 'Sinh bìa và mục lục hồ sơ Word/PDF'
              : kind === 'PROPOSAL_SUMMARY'
                ? 'Sinh phiếu tóm tắt Đề nghị Word/PDF'
                : kind === 'PROPOSAL_FORM'
                ? 'Sinh Đề nghị chứng nhận đầy đủ Word/PDF'
                : kind === 'ASSIGNMENT_FORM'
                ? 'Sinh phiếu phân công chứng nhận Word/PDF'
                : kind === 'EVALUATION_PLAN'
                ? 'Sinh kế hoạch đánh giá CNSP Word/PDF'
                : kind === 'FIELD_INSPECTION'
                ? 'Sinh biên bản kiểm tra tại hiện trường Word/PDF'
                : kind === 'SAMPLE_TAKING'
                ? 'Sinh biên bản lấy mẫu Word/PDF'
                : kind === 'SAMPLE_CODING'
                ? 'Sinh biên bản mã hóa mẫu Word/PDF'
                  : kind === 'EVALUATION_REPORT'
                    ? 'Sinh báo cáo đánh giá hồ sơ PCN Word/PDF'
                  : kind === 'SAMPLE_HANDOVER'
                  ? 'Sinh biên bản giao/nhận mẫu Word/PDF'
                  : kind === 'SAMPLE_RETURN'
                  ? 'Sinh biên bản trả mẫu Word/PDF'
                  : 'Sinh phiếu yêu cầu thử nghiệm PCN Word/PDF',
            source: 'UI',
            groupId: context.contextHash,
            createdAt: generatedAt,
          });
          const validationError = validateActivityLogPayload(log);
          if (validationError) throw new Error(validationError);
          await client.query(
            `INSERT INTO app_documents (collection_name, document_id, data, updated_at)
             VALUES ('activityLogs', $1, $2::jsonb, CURRENT_TIMESTAMP)
             ON CONFLICT (collection_name, document_id) DO NOTHING`,
            [log.id, JSON.stringify(getDocumentPayload(log))],
          );
          createdActivityLogs.push(log);
        }
        return { context, documents: generatedDocuments, activityLogs: createdActivityLogs };
      });
      res.status(result.activityLogs.length > 0 ? 201 : 200).json(result);
    } catch (error: any) {
      for (const uploaded of uploadedObjects.reverse()) {
        try {
          const storage = getPcnStorageClient();
          await storage.deleteObject(uploaded);
        } catch {
          // Keep the original generation error; cleanup is best effort.
        }
      }
      console.error('PCN document generation error:', error);
      const message = String(error?.message || error);
      const normalizedMessage = message.toLowerCase();
      const status = Number(error?.statusCode) || (normalizedMessage.includes('storage is not configured') ? 503 : normalizedMessage.includes('không tìm thấy') || normalizedMessage.includes('chưa có đề nghị') ? 404 : 500);
      res.status(status).json({ error: message });
    }
  });

  app.post('/api/pcn/issuance/:issuanceId/official-documents/generate', async (req, res) => {
    if (DATABASE_PROFILE !== 'pcn') {
      res.status(404).json({ error: 'Sinh tài liệu phát hành PCN chỉ khả dụng trong profile PCN.' });
      return;
    }
    const dryRun = req.body?.dryRun === true;
    if (dryRun ? !requirePcnSession(req, res) : !requirePcnMutation(req, res)) return;
    const actor = getPcnSessionUser(req)!;
    const issuanceId = String(req.params.issuanceId || '').trim();
    const expectedContextHash = typeof req.body?.expectedContextHash === 'string'
      ? req.body.expectedContextHash.trim().toLowerCase()
      : '';
    const requestedKinds = Array.isArray(req.body?.documentKinds) && req.body.documentKinds.length > 0
      ? req.body.documentKinds.map((value: unknown) => String(value).trim().toUpperCase())
      : ['CERTIFICATE', 'DECISION'];
    const requestedFormats = Array.isArray(req.body?.formats) && req.body.formats.length > 0
      ? req.body.formats.map((value: unknown) => String(value).trim().toUpperCase())
      : ['DOCX'];
    const validKinds = requestedKinds.every((value: string) => ['CERTIFICATE', 'DECISION'].includes(value));
    const validFormats = requestedFormats.every((value: string) => ['DOCX', 'PDF'].includes(value));
    const kinds = [...new Set(requestedKinds)] as PcnOfficialDocumentKind[];
    const formats = [...new Set(requestedFormats)] as PcnGeneratedDocumentFormat[];
    if (!issuanceId || !validKinds || !validFormats || kinds.length === 0 || formats.length === 0) {
      res.status(400).json({ error: 'Thiếu mã bộ phát hành, loại tài liệu hoặc định dạng không hợp lệ.' });
      return;
    }
    if (expectedContextHash && !/^[a-f0-9]{64}$/.test(expectedContextHash)) {
      res.status(400).json({ error: 'expectedContextHash không hợp lệ.' });
      return;
    }
    if (!dryRun && !expectedContextHash) {
      res.status(400).json({ error: 'Sinh tài liệu chính thức bắt buộc phải gửi expectedContextHash từ bước kiểm tra dữ liệu.' });
      return;
    }
    const uploadedObjects: Array<{ bucketName: string; objectPath: string }> = [];
    try {
      const storage = dryRun ? null : getPcnStorageClient();
      const bucketName = dryRun ? '' : getPcnStorageBucket();
      if (storage) await storage.ensurePrivateBucket(bucketName, PCN_FILE_MAX_BYTES);
      const lockClause = dryRun ? '' : ' FOR UPDATE';
      const result = await withPgTransaction(async (client) => {
        if (!dryRun) {
          await client.query('SELECT pg_advisory_xact_lock(hashtext($1))', [`pcn-official-generate:${issuanceId}`]);
        }
        const issuanceResult = await client.query(
          `SELECT document_id, data FROM app_documents
           WHERE collection_name = 'issuancePackages' AND document_id = $1
           LIMIT 1${lockClause}`,
          [issuanceId],
        );
        if (issuanceResult.rows.length === 0) throw new Error('Không tìm thấy bộ phát hành PCN.');
        const issuance = mapDocumentRow(issuanceResult.rows[0]) as IssuancePackage;
        if (!['APPROVED', 'ISSUED', 'DELIVERED', 'ARCHIVED'].includes(issuance.status)) {
          throw new Error('Bộ phát hành chưa ở trạng thái cho phép sinh tài liệu chính thức.');
        }
        if (!String(issuance.issuanceNumber || '').trim() || !String(issuance.issuedAt || '').trim()) {
          throw new Error('Bộ phát hành phải có số và ngày cấp trước khi sinh tài liệu chính thức.');
        }

        const dossierResult = await client.query(
          `SELECT document_id, data FROM app_documents
           WHERE collection_name = 'certificationDossiers' AND document_id = $1
           LIMIT 1${lockClause}`,
          [issuance.dossierId],
        );
        if (dossierResult.rows.length === 0) throw new Error('Không tìm thấy hồ sơ liên kết với bộ phát hành.');
        const dossier = mapDocumentRow(dossierResult.rows[0]) as CertificationDossier;
        const proposalId = String(dossier.proposalId || '').trim();
        const proposalResult = await client.query(
          `SELECT document_id, data FROM app_documents
           WHERE collection_name = 'certificationProposals' AND document_id = $1
           LIMIT 1${lockClause}`,
          [proposalId],
        );
        if (proposalResult.rows.length === 0) throw new Error('Không tìm thấy Đề nghị liên kết với hồ sơ.');
        const proposal = mapDocumentRow(proposalResult.rows[0]) as CertificationProposal;
        const fieldCodes = Array.isArray(dossier.fieldCodes) ? dossier.fieldCodes.map((code) => String(code).trim().toUpperCase()).filter(Boolean) : [];
        const [fieldsResult, requirementsResult, documentsResult, attachmentsResult, templateResult] = await Promise.all([
          client.query(`SELECT document_id, data FROM app_documents WHERE collection_name = 'pcnCertificationFields' AND data->>'code' = ANY($1::text[])`, [fieldCodes]),
          client.query(`SELECT document_id, data FROM app_documents WHERE collection_name = 'pcnDocumentRequirements' AND COALESCE((data->>'active')::boolean, false) = true AND data->>'fieldCode' = ANY($1::text[])`, [fieldCodes]),
          client.query(`SELECT document_id, data FROM app_documents WHERE collection_name = 'dossierDocuments' AND data->>'dossierId' = $1`, [dossier.id]),
          client.query(`SELECT document_id, data FROM app_documents WHERE collection_name = 'dossierAttachments' AND data->>'dossierId' = $1`, [dossier.id]),
          client.query(`SELECT document_id, data FROM app_documents WHERE collection_name = 'pcnTemplateDefinitions' AND data->>'fieldCode' = ANY($1::text[])`, [fieldCodes]),
        ]);
        const context = buildPcnDossierDocumentContext({
          dossier,
          proposal,
          fields: fieldsResult.rows.map(mapDocumentRow) as PcnCertificationField[],
          documents: documentsResult.rows.map(mapDocumentRow) as PcnDossierDocument[],
          documentRequirements: requirementsResult.rows.map(mapDocumentRow) as PcnDocumentRequirement[],
          attachments: attachmentsResult.rows.map(mapDocumentRow) as PcnDossierAttachment[],
        });
        const templates = mergePcnTemplateCatalog(templateResult.rows.map((row: any) => ({ ...row.data, id: row.document_id })) as any[]);
        const officialTemplateAssetIds = new Set(
          templates
            .filter((template) => fieldCodes.includes(String(template.fieldCode).trim().toUpperCase()) && kinds.includes(template.documentKind))
            .map((template) => template.fileAssetId)
            .filter((assetId): assetId is string => Boolean(assetId)),
        );
        const officialTemplateAssetResult = await client.query(
          `SELECT id, bucket_name, source_collection, source_document_id, source_json_path, mime_type
           FROM file_assets WHERE id = ANY($1::text[])`,
          [[...officialTemplateAssetIds]],
        );
        const verifiedOfficialTemplateAssetIds = new Set<string>();
        for (const template of templates) {
          const asset = officialTemplateAssetResult.rows.find((row: any) => row.id === template.fileAssetId);
          if (asset
            && String(asset.bucket_name) === getPcnStorageBucket()
            && asset.source_collection === 'pcnTemplateDefinitions'
            && asset.source_document_id === template.id
            && asset.source_json_path === 'fileAssetId'
            && asset.mime_type === 'application/vnd.openxmlformats-officedocument.wordprocessingml.document') {
            verifiedOfficialTemplateAssetIds.add(String(asset.id));
          }
        }
        const pdfReadiness = formats.includes('PDF') ? getPcnPdfRendererReadiness() : undefined;
        const preflightEntries = kinds.map((documentKind) => {
          const template = selectPcnOfficialTemplate(templates, fieldCodes, dossier.method, documentKind);
          if (!template) {
            return {
              documentKind,
              template: undefined,
              data: {},
              ready: false,
              reasons: ['TEMPLATE_MISSING'],
              officialContextHash: '',
            };
          }
          const data = buildPcnOfficialTemplateData({ context, issuance, documentKind });
          const readiness = getPcnOfficialGenerationReadiness(template, data);
          const reasons = [...readiness.reasons] as string[];
          if (!template.fileAssetId || !verifiedOfficialTemplateAssetIds.has(template.fileAssetId)) reasons.push('MISSING_PRIVATE_ASSET');
          if (pdfReadiness && !pdfReadiness.ready) reasons.push('PDF_RENDERER_UNAVAILABLE');
          const officialContextHash = buildPcnOfficialContextHash(context.contextHash, template, data);
          return {
            documentKind,
            template,
            data,
            ready: reasons.length === 0,
            reasons: [...new Set(reasons)],
            officialContextHash,
          };
        });
        const generationContextHash = buildPcnOfficialGenerationContextHash(
          preflightEntries.map((entry) => ({ documentKind: entry.documentKind, contextHash: entry.officialContextHash })),
          formats,
        );
        const preflight = preflightEntries.map((entry) => ({
          documentKind: entry.documentKind,
          ready: entry.ready,
          reasons: entry.reasons,
          ...(entry.template ? { templateId: entry.template.id, templateDisplayName: entry.template.displayName } : {}),
          ...(entry.officialContextHash ? { officialContextHash: entry.officialContextHash } : {}),
        }));
        if (dryRun) {
          return { issuance, documents: [], activityLogs: [], contextHash: generationContextHash, preflight };
        }
        if (!storage) throw new Error('Storage PCN chưa được cấu hình.');
        if (expectedContextHash && expectedContextHash !== generationContextHash) {
          const conflict = Object.assign(new Error('Dữ liệu phát hành đã thay đổi sau bước kiểm tra; vui lòng kiểm tra lại trước khi sinh tài liệu.'), { statusCode: 409 });
          throw conflict;
        }
        const blocked = preflightEntries.find((entry) => !entry.ready);
        if (blocked) {
          const detail = blocked.reasons.join(', ');
          throw new Error(blocked.template
            ? `Template ${blocked.template.displayName} chưa sẵn sàng: ${detail}.`
            : `Chưa có template ${blocked.documentKind} cho lĩnh vực/phương thức của hồ sơ.`);
        }
        const generatedDocuments: PcnOfficialGeneratedDocument[] = [];
        const createdActivityLogs: ReturnType<typeof buildActivityLog>[] = [];
        const generatedAt = new Date().toISOString();
        let createdAny = false;
        for (const documentKind of kinds) {
          const preflightEntry = preflightEntries.find((entry) => entry.documentKind === documentKind);
          if (!preflightEntry?.template) throw new Error(`Chưa có template ${documentKind} cho lĩnh vực/phương thức của hồ sơ.`);
          const template = preflightEntry.template;
          const { data, officialContextHash } = preflightEntry;
          let renderedDocx: Buffer | undefined;
          const loadRenderedDocx = async (): Promise<Buffer> => {
            if (renderedDocx) return renderedDocx;
            if (!storage) throw new Error('Storage PCN chưa được cấu hình.');
            const templateAssetResult = await client.query(
              `SELECT id, bucket_name, object_path, source_collection, source_document_id, source_json_path, mime_type, byte_size, sha256 FROM file_assets WHERE id = $1 LIMIT 1 FOR UPDATE`,
              [template.fileAssetId],
            );
            const templateAsset = templateAssetResult.rows[0];
            if (!templateAsset
              || templateAsset.bucket_name !== bucketName
              || templateAsset.mime_type !== 'application/vnd.openxmlformats-officedocument.wordprocessingml.document'
              || Number(templateAsset.byte_size) !== Number(template.sourceFingerprint.byteSize)
              || String(templateAsset.sha256).toLowerCase() !== String(template.sourceFingerprint.sha256).toLowerCase()
              || templateAsset.source_collection !== 'pcnTemplateDefinitions'
              || templateAsset.source_document_id !== template.id
              || templateAsset.source_json_path !== 'fileAssetId') {
              throw new Error(`Không tìm thấy asset private của template ${template.displayName}.`);
            }
            const downloadedTemplate = await storage.downloadObject({ bucketName: templateAsset.bucket_name, objectPath: templateAsset.object_path });
            const templateSha256 = createHash('sha256').update(downloadedTemplate.body).digest('hex');
            if (downloadedTemplate.body.length !== Number(templateAsset.byte_size)
              || templateSha256 !== String(templateAsset.sha256).toLowerCase()) {
              throw new Error(`Object template ${template.displayName} không khớp byte size/SHA-256 fingerprint.`);
            }
            renderedDocx = renderPcnOfficialDocx(downloadedTemplate.body, data);
            return renderedDocx;
          };
          for (const format of formats) {
            const documentId = buildPcnOfficialDocumentId(issuance.id, template.id, format, officialContextHash);
            const objectPath = `pcnOfficial/${sanitizePcnPathSegment(issuance.id)}/${sanitizePcnPathSegment(template.id)}/${officialContextHash}/${format.toLowerCase()}`;
            const existingResult = await client.query(
              `SELECT document_id, data FROM app_documents WHERE collection_name = 'pcnOfficialGeneratedDocuments' AND document_id = $1 LIMIT 1${lockClause}`,
              [documentId],
            );
            if (existingResult.rows.length > 0) {
              const existing = mapDocumentRow(existingResult.rows[0]) as PcnOfficialGeneratedDocument;
              const existingAssetResult = await client.query(
                `SELECT id, bucket_name, object_path, source_collection, source_document_id, source_json_path, mime_type, byte_size, sha256
                 FROM file_assets WHERE id = $1 LIMIT 1${lockClause}`,
                [existing.fileAssetId],
              );
              const existingAsset = existingAssetResult.rows[0];
              if (!existingAsset
                || existingAsset.bucket_name !== bucketName
                || existingAsset.object_path !== objectPath
                || existingAsset.source_collection !== 'pcnOfficialGeneratedDocuments'
                || existingAsset.source_document_id !== existing.id
                || existingAsset.source_json_path !== 'fileAssetId'
                || existingAsset.mime_type !== existing.mimeType
                || Number(existingAsset.byte_size) !== Number(existing.byteSize)
                || String(existingAsset.sha256).toLowerCase() !== String(existing.sha256).toLowerCase()) {
                throw new Error('Asset tài liệu chính thức không khớp metadata provenance; cần rà soát trước khi tái sử dụng.');
              }
              if (!storage) throw new Error('Storage PCN chưa được cấu hình.');
              const existingDownloaded = await storage.downloadObject({ bucketName: existingAsset.bucket_name, objectPath: existingAsset.object_path });
              const existingSha256 = createHash('sha256').update(existingDownloaded.body).digest('hex');
              if (existingDownloaded.body.length !== Number(existing.byteSize)
                || existingSha256 !== String(existing.sha256).toLowerCase()) {
                throw new Error('Object tài liệu chính thức không khớp byte size/SHA-256 metadata; cần rà soát trước khi tái sử dụng.');
              }
              generatedDocuments.push(existing);
              continue;
            }

            const docxBody = await loadRenderedDocx();
            const body = format === 'DOCX'
              ? docxBody
              : await renderPcnDocxToPdf(docxBody, buildPcnOfficialFileName(dossier.dossierCode, documentKind, 'DOCX'));
            const sha256 = createHash('sha256').update(body).digest('hex');
            const fileAssetId = buildPcnOfficialFileAssetId(sha256, documentId);
            const extension = format.toLowerCase();
            const mimeType = format === 'DOCX'
              ? 'application/vnd.openxmlformats-officedocument.wordprocessingml.document'
              : 'application/pdf';
            const generatedAssetResult = await client.query(`SELECT id, bucket_name, object_path, source_collection, source_document_id, source_json_path, mime_type, byte_size, sha256 FROM file_assets WHERE id = $1 LIMIT 1${lockClause}`, [fileAssetId]);
            const generatedAsset = generatedAssetResult.rows[0];
            if (generatedAsset && (
              generatedAsset.bucket_name !== bucketName
              || generatedAsset.object_path !== objectPath
              || String(generatedAsset.sha256).toLowerCase() !== sha256
              || generatedAsset.source_collection !== 'pcnOfficialGeneratedDocuments'
              || generatedAsset.source_document_id !== documentId
              || generatedAsset.source_json_path !== 'fileAssetId'
              || generatedAsset.mime_type !== mimeType
              || Number(generatedAsset.byte_size) !== body.length
            )) {
              throw new Error('Asset tài liệu chính thức trùng mã nhưng metadata không khớp.');
            }
            if (!generatedAsset) {
              await storage.uploadObject({ bucketName, objectPath, body, mimeType });
              uploadedObjects.push({ bucketName, objectPath });
              await client.query(
                `INSERT INTO file_assets (id, bucket_name, object_path, source_collection, source_document_id, source_json_path, mime_type, byte_size, sha256)
                 VALUES ($1, $2, $3, 'pcnOfficialGeneratedDocuments', $4, 'fileAssetId', $5, $6, $7)
                 ON CONFLICT (id) DO NOTHING`,
                [fileAssetId, bucketName, objectPath, documentId, mimeType, body.length, sha256],
              );
            }
            const persistedGeneratedAssetResult = await client.query(`SELECT id, bucket_name, object_path, source_collection, source_document_id, source_json_path, mime_type, byte_size, sha256 FROM file_assets WHERE id = $1 LIMIT 1${lockClause}`, [fileAssetId]);
            const persistedGeneratedAsset = persistedGeneratedAssetResult.rows[0];
            if (!persistedGeneratedAsset
              || persistedGeneratedAsset.bucket_name !== bucketName
              || persistedGeneratedAsset.object_path !== objectPath
              || String(persistedGeneratedAsset.sha256).toLowerCase() !== sha256
              || persistedGeneratedAsset.source_collection !== 'pcnOfficialGeneratedDocuments'
              || persistedGeneratedAsset.source_document_id !== documentId
              || persistedGeneratedAsset.source_json_path !== 'fileAssetId'
              || persistedGeneratedAsset.mime_type !== mimeType
              || Number(persistedGeneratedAsset.byte_size) !== body.length) {
              throw new Error('Asset tài liệu chính thức sau insert không khớp metadata provenance.');
            }
            const sourceUpdatedAt = getPcnOfficialSourceUpdatedAt(issuance.updatedAt, dossier.updatedAt, proposal.updatedAt);
            const generated: PcnOfficialGeneratedDocument = {
              id: documentId,
              issuanceId: issuance.id,
              dossierId: dossier.id,
              templateId: template.id,
              documentKind,
              format,
              fileAssetId,
              fileName: buildPcnOfficialFileName(dossier.dossierCode, documentKind, format),
              mimeType,
              byteSize: body.length,
              sha256,
              contextHash: officialContextHash,
              ...(sourceUpdatedAt ? { sourceUpdatedAt } : {}),
              generatedAt,
              generatedBy: actor.username,
            };
            const write = await client.query(
              `INSERT INTO app_documents (collection_name, document_id, data, updated_at)
               VALUES ('pcnOfficialGeneratedDocuments', $1, $2::jsonb, CURRENT_TIMESTAMP)
               ON CONFLICT (collection_name, document_id) DO NOTHING
               RETURNING document_id, data`,
              [generated.id, JSON.stringify(getDocumentPayload(generated))],
            );
            const saved = write.rows[0] ? mapDocumentRow(write.rows[0]) as PcnOfficialGeneratedDocument : generated;
            generatedDocuments.push(saved);
            createdAny = true;
          }
        }
        if (createdAny) {
          const now = new Date().toISOString();
          const log = buildActivityLog({
            action: 'CREATED',
            entityType: 'PCN_ISSUANCE',
            entityId: issuance.id,
            entityLabel: issuance.issuanceNumber,
            actorUsername: actor.username,
            actorName: actor.name,
            actorRole: actor.systemRole || actor.role,
            summary: `Sinh tài liệu phát hành chính thức ${formats.join('/')} từ template PCN đã duyệt`,
            source: 'UI',
            groupId: context.contextHash,
            createdAt: now,
          });
          const validationError = validateActivityLogPayload(log);
          if (validationError) throw new Error(validationError);
          await client.query(
            `INSERT INTO app_documents (collection_name, document_id, data, updated_at)
             VALUES ('activityLogs', $1, $2::jsonb, CURRENT_TIMESTAMP)`,
            [log.id, JSON.stringify(getDocumentPayload(log))],
          );
          createdActivityLogs.push(log);
        }
        return { issuance, documents: generatedDocuments, activityLogs: createdActivityLogs, contextHash: generationContextHash, preflight };
      });
      res.status(result.activityLogs.length > 0 ? 201 : 200).json(result);
    } catch (error: any) {
      for (const uploaded of uploadedObjects.reverse()) {
        await getPcnStorageClient().deleteObject(uploaded).catch(() => undefined);
      }
      console.error('PCN official document generation error:', error);
      const message = String(error?.message || error);
      const normalizedMessage = message.toLowerCase();
      const status = Number(error?.statusCode) || (normalizedMessage.includes('storage is not configured')
        || normalizedMessage.includes('chưa sẵn sàng')
        || normalizedMessage.includes('renderer pdf')
        ? 503
        : normalizedMessage.includes('không tìm thấy')
          ? 404
          : 409);
      res.status(status).json({ error: message });
    }
  });


  app.post('/api/pcn/templates/:templateId/review', async (req, res) => {
    if (!requirePcnAdmin(req, res)) return;
    const templateId = decodeURIComponent(String(req.params.templateId || '')).trim();
    const action = String(req.body?.action || '').trim().toUpperCase() as PcnTemplateReviewAction;
    const reason = String(req.body?.reason || '').trim().slice(0, 500);
    if (!templateId || !['APPROVE', 'REQUEST_ANNOTATION', 'RETIRE'].includes(action)) {
      res.status(400).json({ error: 'Thiếu mã template hoặc thao tác review không hợp lệ.' });
      return;
    }
    if (action === 'REQUEST_ANNOTATION' && !reason) {
      res.status(400).json({ error: 'Yêu cầu chỉnh sửa template phải có lý do.' });
      return;
    }
    try {
      const actor = getPcnSessionUser(req)!;
      const result = await withPgTransaction(async (client) => {
        const existingResult = await client.query(
          `SELECT document_id, data FROM app_documents
           WHERE collection_name = 'pcnTemplateDefinitions' AND document_id = $1
           LIMIT 1 FOR UPDATE`,
          [templateId],
        );
        if (existingResult.rows.length === 0) throw new Error('Không tìm thấy template PCN đã import để review.');
        const existing = { ...(existingResult.rows[0].data || {}), id: existingResult.rows[0].document_id } as PcnTemplateDefinition;
        const runtimeExisting = toPcnTemplateRuntimeProjection(existing);
        if (action === 'APPROVE') {
          const approvalProbe = { ...runtimeExisting, status: 'APPROVED' as const };
          const readiness = getPcnTemplateReadiness(approvalProbe, { availablePlaceholderKeys: existing.placeholderKeys });
          if (!readiness.ready) throw new Error(`Template chưa đủ điều kiện phê duyệt: ${readiness.reasons.join(', ')}.`);
          const assetResult = await client.query(
            `SELECT id, bucket_name, source_collection, source_document_id, source_json_path, mime_type, byte_size, sha256
             FROM file_assets WHERE id = $1 LIMIT 1`,
            [existing.fileAssetId],
          );
          const asset = assetResult.rows[0];
          const expectedMimeType = existing.format === 'DOC'
            ? 'application/msword'
            : 'application/vnd.openxmlformats-officedocument.wordprocessingml.document';
          const expectedByteSize = Number(runtimeExisting.sourceFingerprint?.byteSize);
          if (!asset
            || String(asset.bucket_name) !== getPcnStorageBucket()
            || asset.source_collection !== 'pcnTemplateDefinitions'
            || asset.source_document_id !== existing.id
            || asset.source_json_path !== 'fileAssetId'
            || asset.mime_type !== expectedMimeType
            || (Number.isFinite(expectedByteSize) && expectedByteSize > 0 && Number(asset.byte_size) !== expectedByteSize)
            || String(asset.sha256 || '').toLowerCase() !== String(runtimeExisting.sourceFingerprint.sha256 || '').toLowerCase()) {
            throw new Error('Asset private của template chưa tồn tại hoặc không khớp fingerprint.');
          }
        }
        const next = reviewPcnTemplateDefinition(runtimeExisting, action, { now: new Date().toISOString(), approverUsername: actor.username });
        const changes = diffActivityFields(runtimeExisting, next, ['status', 'approvedAt', 'approvedByUsername']);
        if (changes.length === 0) return { template: runtimeExisting, activityLog: undefined };
        await client.query(
          `UPDATE app_documents SET data = $2::jsonb, updated_at = CURRENT_TIMESTAMP
           WHERE collection_name = 'pcnTemplateDefinitions' AND document_id = $1`,
          [existing.id, JSON.stringify(getDocumentPayload(next))],
        );
        const log = buildActivityLog({
          action: 'CONFIGURED',
          entityType: 'PCN_TEMPLATE',
          entityId: next.id,
          entityLabel: next.displayName,
          actorUsername: actor.username,
          actorName: actor.name,
          actorRole: actor.systemRole || actor.role,
          summary: `${action === 'APPROVE' ? 'Phê duyệt' : action === 'RETIRE' ? 'Ngừng sử dụng' : 'Yêu cầu chú thích'} template ${next.displayName}${reason ? `: ${reason}` : ''}`,
          changes,
          source: 'UI',
        });
        const validationError = validateActivityLogPayload(log);
        if (validationError) throw new Error(validationError);
        await client.query(
          `INSERT INTO app_documents (collection_name, document_id, data, updated_at)
           VALUES ('activityLogs', $1, $2::jsonb, CURRENT_TIMESTAMP)`,
          [log.id, JSON.stringify(getDocumentPayload(log))],
        );
        return { template: next, activityLog: log };
      });
      res.json({ ...result, template: toPcnTemplateRuntimeProjection(result.template) });
    } catch (error: any) {
      console.error('PCN template review error:', error);
      const message = String(error?.message || error);
      const normalizedMessage = message.toLowerCase();
      const status = normalizedMessage.includes('không tìm thấy') ? 404 : 409;
      res.status(status).json({ error: message });
    }
  });

  app.post('/api/pcn/templates/:templateId/annotate', async (req, res) => {
    if (!requirePcnAdmin(req, res)) return;
    const templateId = decodeURIComponent(String(req.params.templateId || '')).trim();
    const rawMappings = req.body?.mappings;
    if (!templateId || !Array.isArray(rawMappings) || rawMappings.length === 0 || rawMappings.length > 50) {
      res.status(400).json({ error: 'Thiếu mã template hoặc danh sách mapping chú thích không hợp lệ.' });
      return;
    }
    const mappings = rawMappings.map((item: any) => ({
      key: String(item?.key || ''),
      sourceText: String(item?.sourceText || ''),
      ...(item?.occurrence === undefined ? {} : { occurrence: Number(item.occurrence) }),
    })) as PcnTemplateAnnotationMapping[];
    const uploadedObjects: Array<{ bucketName: string; objectPath: string }> = [];
    try {
      const actor = getPcnSessionUser(req)!;
      const storage = getPcnStorageClient();
      const bucketName = getPcnStorageBucket();
      await storage.ensurePrivateBucket(bucketName, PCN_FILE_MAX_BYTES);
      const result = await withPgTransaction(async (client) => {
        // Serialize retries for the deterministic annotated asset and the
        // template pointer update. The row lock below protects one template;
        // this advisory lock also covers concurrent retries that derive the
        // same asset id before either transaction has committed it.
        await client.query('SELECT pg_advisory_xact_lock(hashtext($1))', [`pcn-template-asset:${templateId}`]);
        const existingResult = await client.query(
          `SELECT document_id, data FROM app_documents
           WHERE collection_name = 'pcnTemplateDefinitions' AND document_id = $1
           LIMIT 1 FOR UPDATE`,
          [templateId],
        );
        if (existingResult.rows.length === 0) throw new Error('Không tìm thấy template PCN đã import để chú thích.');
        const existing = { ...(existingResult.rows[0].data || {}), id: existingResult.rows[0].document_id } as PcnTemplateDefinition;
        const runtimeExisting = toPcnTemplateRuntimeProjection(existing);
        if (runtimeExisting.format !== 'DOCX') throw new Error('Chỉ template DOCX mới có thể chú thích tự động; DOC legacy chỉ lưu tham chiếu.');
        if (runtimeExisting.status !== 'NEEDS_ANNOTATION') throw new Error('Template phải ở trạng thái NEEDS_ANNOTATION trước khi chú thích.');
        if (!runtimeExisting.fileAssetId || runtimeExisting.storageScope !== 'PCN_PRIVATE') throw new Error('Template chưa có asset private để chú thích.');

        const assetResult = await client.query(
          `SELECT id, bucket_name, object_path, source_collection, source_document_id, source_json_path, mime_type, byte_size, sha256
           FROM file_assets WHERE id = $1 LIMIT 1`,
          [existing.fileAssetId],
        );
        const sourceAsset = assetResult.rows[0];
        if (!sourceAsset
          || sourceAsset.source_collection !== 'pcnTemplateDefinitions'
          || sourceAsset.source_document_id !== existing.id
          || sourceAsset.source_json_path !== 'fileAssetId'
          || !String(sourceAsset.mime_type || '').toLowerCase().includes('wordprocessingml')) {
          throw new Error('Asset private của template không hợp lệ hoặc không còn khớp metadata.');
        }
        const source = await storage.downloadObject({ bucketName: sourceAsset.bucket_name, objectPath: sourceAsset.object_path });
        const annotated = annotatePcnDocxTemplate(source.body, mappings);
        const annotatedSha256 = createHash('sha256').update(annotated.bytes).digest('hex');
        const annotatedAssetId = buildPcnTemplateAssetId(annotatedSha256);
        const annotatedObjectPath = `pcnTemplates/${sanitizePcnPathSegment(existing.fieldCode)}/${sanitizePcnPathSegment(existing.id)}/${annotatedSha256}/annotated.docx`;
        const existingAnnotatedAssetResult = await client.query(
          `SELECT id, bucket_name, object_path, source_collection, source_document_id, source_json_path, mime_type, byte_size, sha256
           FROM file_assets WHERE id = $1 LIMIT 1`,
          [annotatedAssetId],
        );
        const existingAnnotatedAsset = existingAnnotatedAssetResult.rows[0];
        if (existingAnnotatedAsset && (
          String(existingAnnotatedAsset.sha256 || '').toLowerCase() !== annotatedSha256
          || existingAnnotatedAsset.source_collection !== 'pcnTemplateDefinitions'
          || existingAnnotatedAsset.source_document_id !== existing.id
          || existingAnnotatedAsset.source_json_path !== 'fileAssetId'
        )) {
          throw new Error('Asset DOCX chú thích trùng mã nhưng metadata không khớp.');
        }
        if (!existingAnnotatedAsset) {
          await storage.uploadObject({ bucketName, objectPath: annotatedObjectPath, body: annotated.bytes, mimeType: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document' });
          uploadedObjects.push({ bucketName, objectPath: annotatedObjectPath });
          await client.query(
            `INSERT INTO file_assets (id, bucket_name, object_path, source_collection, source_document_id, source_json_path, mime_type, byte_size, sha256)
             VALUES ($1, $2, $3, 'pcnTemplateDefinitions', $4, 'fileAssetId', $5, $6, $7)`,
            [annotatedAssetId, bucketName, annotatedObjectPath, existing.id, 'application/vnd.openxmlformats-officedocument.wordprocessingml.document', annotated.bytes.length, annotatedSha256],
          );
        }

        const now = new Date().toISOString();
        const sourceOriginalFingerprint = runtimeExisting.sourceOriginalFingerprint || runtimeExisting.sourceFingerprint;
        const next: PcnTemplateDefinition = {
          ...runtimeExisting,
          status: 'NEEDS_ANNOTATION',
          approvedAt: undefined,
          placeholderKeys: annotated.placeholderKeys,
          requiredPlaceholderKeys: getPcnTemplateRequiredPlaceholderKeys(runtimeExisting),
          sourceOriginalFingerprint,
          sourceFingerprint: { ...runtimeExisting.sourceFingerprint, byteSize: annotated.bytes.length, sha256: annotatedSha256 },
          fileAssetId: annotatedAssetId,
          storageScope: 'PCN_PRIVATE',
          annotation: {
            sourceAssetId: existing.fileAssetId,
            sourceSha256: String(sourceAsset.sha256 || runtimeExisting.sourceFingerprint.sha256 || '').toLowerCase(),
            appliedAt: now,
            appliedBy: actor.username,
            mappings: annotated.appliedMappings,
          },
        };
        const sameAnnotation = existing.fileAssetId === next.fileAssetId
          && JSON.stringify(existing.placeholderKeys || []) === JSON.stringify(next.placeholderKeys)
          && JSON.stringify(existing.annotation?.mappings || []) === JSON.stringify(next.annotation?.mappings || []);
        if (sameAnnotation) return { template: runtimeExisting, activityLog: undefined };

        await client.query(
          `UPDATE app_documents SET data = $2::jsonb, updated_at = CURRENT_TIMESTAMP
           WHERE collection_name = 'pcnTemplateDefinitions' AND document_id = $1`,
          [existing.id, JSON.stringify(getDocumentPayload(next))],
        );
        const log = buildActivityLog({
          action: 'CONFIGURED',
          entityType: 'PCN_TEMPLATE',
          entityId: next.id,
          entityLabel: next.displayName,
          actorUsername: actor.username,
          actorName: actor.name,
          actorRole: actor.systemRole || actor.role,
          summary: `Chú thích DOCX template ${next.displayName}`,
          changes: diffActivityFields(runtimeExisting, next, ['status', 'approvedAt', 'placeholderKeys', 'requiredPlaceholderKeys', 'sourceFingerprint', 'sourceOriginalFingerprint', 'fileAssetId', 'annotation']),
          source: 'UI',
        });
        const validationError = validateActivityLogPayload(log);
        if (validationError) throw new Error(validationError);
        await client.query(
          `INSERT INTO app_documents (collection_name, document_id, data, updated_at)
           VALUES ('activityLogs', $1, $2::jsonb, CURRENT_TIMESTAMP)`,
          [log.id, JSON.stringify(getDocumentPayload(log))],
        );
        return { template: next, activityLog: log };
      });
      res.json({ ...result, template: toPcnTemplateRuntimeProjection(result.template) });
    } catch (error: any) {
      for (const uploaded of uploadedObjects.reverse()) {
        await getPcnStorageClient().deleteObject(uploaded).catch(() => undefined);
      }
      console.error('PCN template annotation error:', error);
      const message = String(error?.message || error);
      const normalizedMessage = message.toLowerCase();
      const status = normalizedMessage.includes('không tìm thấy') ? 404 : normalizedMessage.includes('không hợp lệ') || normalizedMessage.includes('không trống') || normalizedMessage.includes('không duy nhất') || normalizedMessage.includes('placeholder') || normalizedMessage.includes('doc legacy') ? 400 : 409;
      res.status(status).json({ error: message });
    }
  });

  app.get('/api/pcn/document-requirements', async (req, res) => {
    if (DATABASE_PROFILE !== 'pcn') {
      res.status(404).json({ error: 'PCN document requirements chỉ khả dụng trong profile PCN.' });
      return;
    }
    const fieldCodes = String(req.query.fieldCodes || '')
      .split(',')
      .map((code) => code.trim().toUpperCase())
      .filter(Boolean);
    try {
      const result = await pool.query(
        `SELECT document_id, data FROM app_documents
         WHERE collection_name = 'pcnDocumentRequirements'
           AND COALESCE((data->>'active')::boolean, false) = true
           AND ($1::text[] = '{}' OR data->>'fieldCode' = ANY($1::text[]))
         ORDER BY COALESCE((data->>'sortOrder')::int, 0), document_id`,
        [fieldCodes],
      );
      res.json({ items: result.rows.map(mapDocumentRow) });
    } catch (error: any) {
      console.error('PCN document requirement read error:', error);
      res.status(500).json({ error: error?.message || String(error) });
    }
  });

  app.get('/api/pcn/dossiers/:dossierId/package', async (req, res) => {
    if (DATABASE_PROFILE !== 'pcn') {
      res.status(404).json({ error: 'Gói hồ sơ PCN chỉ khả dụng trong profile PCN.' });
      return;
    }
    if (!requirePcnSession(req, res)) return;
    const dossierId = String(req.params.dossierId || '').trim();
    if (!dossierId) {
      res.status(400).json({ error: 'Thiếu mã hồ sơ PCN.' });
      return;
    }

    type PackageCandidate = PcnDossierPackagePointer & {
      expectedProvenance: Array<{ sourceCollection: string; sourceDocumentId: string; sourceJsonPath: string }>;
    };

    try {
      const dossierResult = await pool.query(
        `SELECT document_id, data FROM app_documents
         WHERE collection_name = 'certificationDossiers' AND document_id = $1
         LIMIT 1`,
        [dossierId],
      );
      if (dossierResult.rows.length === 0) {
        res.status(404).json({ error: 'Không tìm thấy hồ sơ PCN.' });
        return;
      }
      const dossier = mapDocumentRow(dossierResult.rows[0]) as CertificationDossier;
      const [documentsResult, attachmentsResult, generatedResult, officialResult, resultsResult, issuanceResult] = await Promise.all([
        pool.query(
          `SELECT document_id, data FROM app_documents
           WHERE collection_name = 'dossierDocuments' AND data->>'dossierId' = $1
           ORDER BY document_id`,
          [dossier.id],
        ),
        pool.query(
          `SELECT document_id, data FROM app_documents
           WHERE collection_name = 'dossierAttachments' AND data->>'dossierId' = $1
           ORDER BY document_id`,
          [dossier.id],
        ),
        pool.query(
          `SELECT document_id, data FROM app_documents
           WHERE collection_name = 'pcnGeneratedDocuments' AND data->>'dossierId' = $1
           ORDER BY document_id`,
          [dossier.id],
        ),
        pool.query(
          `SELECT document_id, data FROM app_documents
           WHERE collection_name = 'pcnOfficialGeneratedDocuments' AND data->>'dossierId' = $1
           ORDER BY document_id`,
          [dossier.id],
        ),
        pool.query(
          `SELECT document_id, data FROM app_documents
           WHERE collection_name = 'returnedResults' AND data->>'dossierId' = $1
           ORDER BY document_id`,
          [dossier.id],
        ),
        pool.query(
          `SELECT document_id, data FROM app_documents
           WHERE collection_name = 'issuancePackages' AND data->>'dossierId' = $1
           ORDER BY document_id`,
          [dossier.id],
        ),
      ]);

      const candidates: PackageCandidate[] = [];
      const addCandidate = (candidate: Omit<PackageCandidate, 'expectedProvenance'>, expectedProvenance: PackageCandidate['expectedProvenance']) => {
        if (!String(candidate.assetId || '').trim()) return;
        candidates.push({ ...candidate, expectedProvenance });
      };

      for (const document of documentsResult.rows.map(mapDocumentRow) as PcnDossierDocument[]) {
        const versions = Array.isArray(document.versions) ? document.versions : [];
        versions.forEach((version: any, index: number) => {
          const assetId = String(version?.assetId || '').trim();
          if (!assetId) return;
          addCandidate({
            assetId,
            sourceCollection: 'dossierDocuments',
            sourceDocumentId: document.id,
            sourceJsonPath: document.requirementId,
            fileName: `v${index + 1}-${String(version?.fileName || `${assetId}.bin`)}`,
            mimeType: version?.mimeType,
            byteSize: Number(version?.byteSize || 0),
            sha256: version?.sha256,
            category: 'CHECKLIST',
          }, [{ sourceCollection: 'dossierDocuments', sourceDocumentId: document.id, sourceJsonPath: document.requirementId }]);
        });
      }

      for (const attachment of attachmentsResult.rows.map(mapDocumentRow) as PcnDossierAttachment[]) {
        addCandidate({
          assetId: attachment.assetId,
          sourceCollection: 'dossierAttachments',
          sourceDocumentId: attachment.id,
          sourceJsonPath: attachment.requirementId || 'fileAssetId',
          fileName: attachment.fileName,
          mimeType: attachment.mimeType,
          byteSize: attachment.byteSize,
          sha256: attachment.sha256,
          category: 'ATTACHMENTS',
        }, [
          { sourceCollection: 'dossierAttachments', sourceDocumentId: attachment.id, sourceJsonPath: attachment.requirementId || 'fileAssetId' },
          { sourceCollection: 'dossierAttachments', sourceDocumentId: dossier.id, sourceJsonPath: `attachments.${attachment.kind}` },
        ]);
      }

      for (const generated of generatedResult.rows.map(mapDocumentRow) as PcnGeneratedDocument[]) {
        addCandidate({
          assetId: generated.fileAssetId,
          sourceCollection: 'pcnGeneratedDocuments',
          sourceDocumentId: generated.id,
          sourceJsonPath: 'fileAssetId',
          fileName: generated.fileName,
          mimeType: generated.mimeType,
          byteSize: generated.byteSize,
          sha256: generated.sha256,
          category: 'GENERATED',
          kind: generated.kind,
          format: generated.format,
          contextHash: generated.contextHash,
          sourceUpdatedAt: generated.sourceUpdatedAt,
        }, [{ sourceCollection: 'pcnGeneratedDocuments', sourceDocumentId: generated.id, sourceJsonPath: 'fileAssetId' }]);
      }

      for (const generated of officialResult.rows.map(mapDocumentRow) as PcnOfficialGeneratedDocument[]) {
        addCandidate({
          assetId: generated.fileAssetId,
          sourceCollection: 'pcnOfficialGeneratedDocuments',
          sourceDocumentId: generated.id,
          sourceJsonPath: 'fileAssetId',
          fileName: generated.fileName,
          mimeType: generated.mimeType,
          byteSize: generated.byteSize,
          sha256: generated.sha256,
          category: 'OFFICIAL',
          kind: generated.documentKind,
          format: generated.format,
          contextHash: generated.contextHash,
          sourceUpdatedAt: generated.sourceUpdatedAt,
        }, [{ sourceCollection: 'pcnOfficialGeneratedDocuments', sourceDocumentId: generated.id, sourceJsonPath: 'fileAssetId' }]);
      }

      for (const result of resultsResult.rows.map(mapDocumentRow) as ReturnedTestResult[]) {
        if (!result.fileAssetId) continue;
        addCandidate({
          assetId: result.fileAssetId,
          sourceCollection: 'returnedResults',
          sourceDocumentId: result.id,
          sourceJsonPath: 'fileAssetId',
          fileName: result.reportNumber ? `${result.reportNumber}.pdf` : undefined,
          category: 'RESULT',
        }, [{ sourceCollection: 'returnedResults', sourceDocumentId: result.id, sourceJsonPath: 'fileAssetId' }]);
      }

      for (const issuance of issuanceResult.rows.map(mapDocumentRow) as IssuancePackage[]) {
        for (const assetId of Array.isArray(issuance.fileAssetIds) ? issuance.fileAssetIds : []) {
          addCandidate({
            assetId: String(assetId),
            sourceCollection: 'issuancePackages',
            sourceDocumentId: issuance.id,
            sourceJsonPath: 'fileAssetIds',
            category: 'ISSUANCE',
          }, [{ sourceCollection: 'issuancePackages', sourceDocumentId: issuance.id, sourceJsonPath: 'fileAssetIds' }]);
        }
      }

      const assetIds = [...new Set(candidates.map((candidate) => String(candidate.assetId).trim()).filter(Boolean))];
      const assetResult = assetIds.length > 0
        ? await pool.query(
          `SELECT id, bucket_name, object_path, source_collection, source_document_id, source_json_path, mime_type, byte_size, sha256
           FROM file_assets WHERE id = ANY($1::text[])`,
          [assetIds],
        )
        : { rows: [] as any[] };
      const assetsById = new Map(assetResult.rows.map((asset: any) => [String(asset.id), asset]));
      const verifiedPointers: PcnDossierPackagePointer[] = [];

      for (const candidate of candidates) {
        const asset = assetsById.get(String(candidate.assetId));
        if (!asset) throw Object.assign(new Error(`Không tìm thấy file asset ${candidate.assetId} của hồ sơ.`), { statusCode: 409 });
        const actualProvenance = {
          sourceCollection: String(asset.source_collection || ''),
          sourceDocumentId: String(asset.source_document_id || ''),
          sourceJsonPath: String(asset.source_json_path || ''),
        };
        if (!candidate.expectedProvenance.some((expected) => expected.sourceCollection === actualProvenance.sourceCollection
          && expected.sourceDocumentId === actualProvenance.sourceDocumentId
          && expected.sourceJsonPath === actualProvenance.sourceJsonPath)) {
          throw Object.assign(new Error(`Provenance file asset ${candidate.assetId} không khớp pointer của hồ sơ.`), { statusCode: 409 });
        }
        verifiedPointers.push({
          ...candidate,
          ...actualProvenance,
          fileName: candidate.fileName || String(asset.object_path || '').split('/').pop() || `${candidate.assetId}.bin`,
          mimeType: String(asset.mime_type || candidate.mimeType || 'application/octet-stream'),
          byteSize: Number(asset.byte_size || 0),
          sha256: String(asset.sha256 || '').trim().toLowerCase(),
        });
      }

      const manifestEntries = buildPcnDossierPackageManifest({ dossierCode: dossier.dossierCode || dossier.id, pointers: verifiedPointers });
      const packageFiles: Array<{ archivePath: string; body: Buffer }> = [];
      if (manifestEntries.length > 0) {
        const storage = getPcnStorageClient();
        for (const entry of manifestEntries) {
          const asset = assetsById.get(entry.assetId);
          if (!asset || !String(asset.bucket_name || '').trim() || !String(asset.object_path || '').trim()) {
            throw Object.assign(new Error(`File asset ${entry.assetId} thiếu vị trí Storage.`), { statusCode: 409 });
          }
          const downloaded = await storage.downloadObject({ bucketName: String(asset.bucket_name), objectPath: String(asset.object_path) });
          const actualByteSize = downloaded.body.byteLength;
          const actualSha256 = createHash('sha256').update(downloaded.body).digest('hex');
          if (actualByteSize !== entry.byteSize || actualSha256 !== entry.sha256) {
            throw Object.assign(new Error(`File asset ${entry.assetId} không khớp byte size/SHA-256 với metadata.`), { statusCode: 409 });
          }
          packageFiles.push({ archivePath: entry.archivePath, body: downloaded.body });
        }
      }

      const generatedAt = new Date().toISOString();
      const archive = new AdmZip();
      archive.addFile('manifest.json', Buffer.from(JSON.stringify({
        format: 'PCN_DOSSIER_PACKAGE_V1',
        generatedAt,
        dossier: {
          id: dossier.id,
          dossierCode: dossier.dossierCode,
          status: dossier.status,
          fieldCodes: dossier.fieldCodes,
        },
        entries: manifestEntries.map(({ assetId, archivePath, fileName, sourceCollection, sourceDocumentId, sourceJsonPath, mimeType, byteSize, sha256, kind, format, contextHash, sourceUpdatedAt }) => ({
          assetId,
          archivePath,
          fileName,
          sourceCollection,
          sourceDocumentId,
          sourceJsonPath,
          mimeType,
          byteSize,
          sha256,
          ...(kind ? { kind } : {}),
          ...(format ? { format } : {}),
          ...(contextHash ? { contextHash } : {}),
          ...(sourceUpdatedAt ? { sourceUpdatedAt } : {}),
        })),
      }, null, 2), 'utf8'));
      for (const file of packageFiles) archive.addFile(file.archivePath, file.body);

      const body = archive.toBuffer();
      const downloadName = buildPcnDossierPackageDownloadName(dossier.dossierCode || dossier.id);
      res.setHeader('Content-Type', 'application/zip');
      res.setHeader('Content-Length', body.byteLength);
      res.setHeader('Content-Disposition', `attachment; filename="${downloadName}"`);
      res.send(body);
    } catch (error: any) {
      console.error('PCN dossier package error:', error);
      const message = String(error?.message || error);
      const status = Number(error?.statusCode) || (message.toLowerCase().includes('storage is not configured') ? 503 : 500);
      res.status(status).json({ error: message });
    }
  });

  app.get('/api/pcn/dossiers/:dossierId/documents', async (req, res) => {
    if (!requirePcnSession(req, res)) return;
    const dossierId = String(req.params.dossierId || '').trim();
    if (!dossierId) {
      res.status(400).json({ error: 'Thiếu mã hồ sơ PCN.' });
      return;
    }
    try {
      const result = await pool.query(
        `SELECT document_id, data FROM app_documents
         WHERE collection_name = 'dossierDocuments'
           AND data->>'dossierId' = $1
         ORDER BY COALESCE((data->>'updatedAt')::timestamptz, updated_at) DESC, document_id`,
        [dossierId],
      );
      res.json({ items: result.rows.map(mapDocumentRow) });
    } catch (error: any) {
      console.error('PCN dossier document read error:', error);
      res.status(500).json({ error: error?.message || String(error) });
    }
  });

  app.post('/api/pcn/dossiers/:dossierId/documents', async (req, res) => {
    if (!requirePcnMutation(req, res)) return;
    const dossierId = String(req.params.dossierId || '').trim();
    const requirementId = String(req.body?.requirementId || '').trim();
    const assetId = String(req.body?.assetId || '').trim();
    const fileName = String(req.body?.fileName || '').trim();
    if (!dossierId || !requirementId || !/^pcn-file-[a-z0-9-]+$/.test(assetId) || !fileName) {
      res.status(400).json({ error: 'Thiếu metadata phiên tài liệu PCN.' });
      return;
    }
    if (fileName.length > 255 || /[\\/]/.test(fileName)) {
      res.status(400).json({ error: 'Tên file tài liệu PCN không hợp lệ.' });
      return;
    }
    const actor = getPcnSessionUser(req)!;
    try {
      const document = await withPgTransaction(async (client) => {
        const dossierExists = await client.query(
          `SELECT document_id, data FROM app_documents
           WHERE collection_name = 'certificationDossiers' AND document_id = $1
           LIMIT 1 FOR UPDATE`,
          [dossierId],
        );
        if (dossierExists.rows.length === 0) throw new Error('Không tìm thấy hồ sơ PCN.');
        const dossier = mapDocumentRow(dossierExists.rows[0]) as CertificationDossier;
        if (isPcnDossierPostApprovalLocked(dossier.status)) {
          throw Object.assign(new Error('Hồ sơ đã duyệt/phát hành; phải thu hồi có lý do trước khi tải phiên tài liệu mới.'), { statusCode: 409 });
        }
        assertPcnDossierOperator(dossier, actor);
        const dossierFieldCodes = Array.isArray(dossier.fieldCodes)
          ? dossier.fieldCodes.map((code: unknown) => String(code).trim().toUpperCase()).filter(Boolean)
          : [];
        const requirement = await client.query(
          `SELECT document_id, data FROM app_documents
           WHERE collection_name = 'pcnDocumentRequirements' AND document_id = $1
           LIMIT 1`,
          [requirementId],
        );
        const requirementDefinition = requirement.rows[0] ? mapDocumentRow(requirement.rows[0]) as PcnDocumentRequirement : undefined;
        const requirementData: Partial<PcnDocumentRequirement> = requirementDefinition || {};
        const requirementFieldCode = String(requirementData.fieldCode || '').trim().toUpperCase();
        if (requirement.rows.length === 0 || requirementData.active === false || !requirementFieldCode || !dossierFieldCodes.includes(requirementFieldCode)) {
          throw new Error('Loại tài liệu không thuộc Lĩnh vực của hồ sơ PCN.');
        }
        if (!canProcessPcnDossierRequirement(dossier, requirementDefinition!)) {
          throw Object.assign(new Error('Tài liệu thuộc bước chưa đến; hãy hoàn tất bước hiện tại trước.'), { statusCode: 409 });
        }
        const documentId = buildPcnDossierDocumentId(dossierId, requirementId);
        const asset = await client.query(
          `SELECT id, source_collection, source_document_id, source_json_path, mime_type, byte_size, sha256
          FROM file_assets WHERE id = $1 FOR UPDATE`,
          [assetId],
        );
        const assetRow = asset.rows[0];
        if (!assetRow
          || assetRow.source_collection !== 'dossierDocuments'
          || assetRow.source_document_id !== documentId
          || assetRow.source_json_path !== requirementId) {
          throw new Error('File asset không thuộc hồ sơ PCN.');
        }
        const existing = await client.query(
          `SELECT document_id, data FROM app_documents
           WHERE collection_name = 'dossierDocuments' AND document_id = $1 FOR UPDATE`,
          [documentId],
        );
        const previous = existing.rows[0]?.data || {};
        const previousVersions = Array.isArray(previous.versions) ? previous.versions : [];
        const attachmentId = `pcn-attachment-upload-${assetId}`;
        const existingAttachmentResult = await client.query(
          `SELECT document_id, data FROM app_documents
           WHERE collection_name = 'dossierAttachments' AND document_id = $1
           LIMIT 1 FOR UPDATE`,
          [attachmentId],
        );
        const existingAttachment = existingAttachmentResult.rows[0]
          ? mapDocumentRow(existingAttachmentResult.rows[0]) as PcnDossierAttachment
          : undefined;
        const hasVersion = previousVersions.some((version: any) => String(version?.assetId || '') === assetId);
        if (hasVersion && existingAttachment) {
          return {
            document: mapDocumentRow(existing.rows[0]),
            dossier,
            attachment: existingAttachment,
            idempotent: true as const,
          };
        }
        const now = new Date().toISOString();
        let persistedDocument: PcnDossierDocument;
        if (hasVersion) {
          persistedDocument = mapDocumentRow(existing.rows[0]) as PcnDossierDocument;
        } else {
          const version = {
            assetId,
            fileName: fileName.slice(0, 255),
            mimeType: assetRow.mime_type || undefined,
            byteSize: Number(assetRow.byte_size || 0),
            sha256: assetRow.sha256,
            uploadedAt: now,
            ...(getPcnSessionUser(req)?.username ? { uploadedBy: getPcnSessionUser(req)!.username } : {}),
          };
          const next = {
            ...previous,
            dossierId,
            requirementId,
            fieldCode: requirementFieldCode,
            currentVersionId: assetId,
            versions: [...previousVersions, version],
            status: 'PRESENT',
            createdAt: previous.createdAt || now,
            updatedAt: now,
          };
          const write = await client.query(
            `INSERT INTO app_documents (collection_name, document_id, data, updated_at)
             VALUES ('dossierDocuments', $1, $2::jsonb, CURRENT_TIMESTAMP)
             ON CONFLICT (collection_name, document_id)
             DO UPDATE SET data = EXCLUDED.data, updated_at = CURRENT_TIMESTAMP
             RETURNING document_id, data`,
            [documentId, JSON.stringify(getDocumentPayload(next))],
          );
          persistedDocument = mapDocumentRow(write.rows[0]) as PcnDossierDocument;
        }
        const attachment = existingAttachment || buildPcnUploadedDossierAttachment({
          dossierId,
          requirement: requirementDefinition!,
          assetId,
          fileName,
          mimeType: assetRow.mime_type,
          byteSize: Number(assetRow.byte_size || 0),
          sha256: assetRow.sha256,
          uploadedAt: now,
          uploadedBy: getPcnSessionUser(req)?.username,
        });
        if (!existingAttachment) {
          await client.query(
            `INSERT INTO app_documents (collection_name, document_id, data, updated_at)
             VALUES ('dossierAttachments', $1, $2::jsonb, CURRENT_TIMESTAMP)`,
            [attachment.id, JSON.stringify(getDocumentPayload(attachment))],
          );
        }
        const workflowRework = await applyPcnDossierDocumentRework(client, dossier, requirementDefinition!, actor, now);
        const currentStageIndex = getPcnWorkflowStageIndex(getPcnWorkflowStage(dossier.status)?.key || 'INTAKE');
        const requirementStageIndex = getPcnRequirementWorkflowStageIndex(requirementDefinition!);
        const needsDownstreamReview = dossier.status === 'WAITING_APPROVAL'
          && requirementStageIndex >= 0
          && requirementStageIndex < currentStageIndex;
        const reopenStatus = getPcnRequirementReopenStatus(requirementDefinition!) || 'TECHNICAL_REVIEW';
        let nextApprovalSteps: PcnApprovalStep[] | undefined;
        if (needsDownstreamReview) {
          const approvalResult = await client.query(
            `SELECT document_id, data FROM app_documents
             WHERE collection_name = 'approvalSteps' AND data->>'dossierId' = $1
             ORDER BY COALESCE((data->>'sequence')::int, 999), document_id
             FOR UPDATE`,
            [dossier.id],
          );
          const allSteps = approvalResult.rows.map((row: any) => mapDocumentRow(row)) as PcnApprovalStep[];
          const effectiveStepIds = new Set(getPcnEffectiveApprovalSteps(allSteps).map((step) => step.id));
          nextApprovalSteps = allSteps.map((step) => effectiveStepIds.has(step.id)
            ? { ...step, status: 'PENDING' as const, actedAt: undefined }
            : step);
          for (const step of nextApprovalSteps) {
            await client.query(
              `UPDATE app_documents SET data = $2::jsonb, updated_at = CURRENT_TIMESTAMP
               WHERE collection_name = 'approvalSteps' AND document_id = $1`,
              [step.id, JSON.stringify(getDocumentPayload(step))],
            );
          }
          const issuanceResult = await client.query(
            `SELECT document_id, data FROM app_documents
             WHERE collection_name = 'issuancePackages' AND data->>'dossierId' = $1
             LIMIT 1 FOR UPDATE`,
            [dossier.id],
          );
          if (issuanceResult.rows.length > 0) {
            const issuance = mapDocumentRow(issuanceResult.rows[0]) as IssuancePackage;
            const nextIssuance: IssuancePackage = { ...issuance, status: 'RETURNED', updatedAt: now };
            await client.query(
              `UPDATE app_documents SET data = $2::jsonb, updated_at = CURRENT_TIMESTAMP
               WHERE collection_name = 'issuancePackages' AND document_id = $1`,
              [nextIssuance.id, JSON.stringify(getDocumentPayload(nextIssuance))],
            );
          }
        }
        const nextDossier: CertificationDossier = {
          ...workflowRework.dossier,
          ...(needsDownstreamReview ? { status: reopenStatus } : {}),
          updatedAt: now,
        };
        await client.query(
          `UPDATE app_documents SET data = $2::jsonb, updated_at = CURRENT_TIMESTAMP
           WHERE collection_name = 'certificationDossiers' AND document_id = $1`,
          [dossier.id, JSON.stringify(getDocumentPayload(nextDossier))],
        );
        const user = getPcnSessionUser(req);
        const log = buildActivityLog({
          action: 'UPDATED',
          entityType: 'PCN_DOSSIER',
          entityId: dossierId,
          entityLabel: dossier.dossierCode || dossierId,
          actorUsername: user?.username,
          actorName: user?.name || 'Người dùng PCN',
          actorRole: user?.systemRole || user?.role,
          summary: needsDownstreamReview
            ? `Tải phiên tài liệu ${fileName.slice(0, 120)} và mở lại ${getPcnWorkflowStage(reopenStatus)?.title || 'bước bị ảnh hưởng'} để rà soát`
            : workflowRework.reopenedNodeId
              ? `Tải phiên tài liệu ${fileName.slice(0, 120)} và mở lại node ${workflowRework.reopenedNodeId} theo vòng xử lý mới`
            : hasVersion
              ? `Bổ sung provenance cho phiên tài liệu ${fileName.slice(0, 120)} trong hồ sơ`
              : `Tải phiên tài liệu ${fileName.slice(0, 120)} vào hồ sơ`,
          source: 'UI',
          groupId: dossier.id,
          changes: diffActivityFields(dossier, nextDossier, ['updatedAt']),
          createdAt: now,
        });
        const validationError = validateActivityLogPayload(log);
        if (validationError) throw new Error(validationError);
        await client.query(
          `INSERT INTO app_documents (collection_name, document_id, data, updated_at)
           VALUES ('activityLogs', $1, $2::jsonb, CURRENT_TIMESTAMP)
           ON CONFLICT (collection_name, document_id) DO NOTHING`,
          [log.id, JSON.stringify(getDocumentPayload(log))],
        );
        return {
          document: persistedDocument,
          attachment,
          dossier: nextDossier,
          ...(workflowRework.workflowTasks ? { workflowTasks: workflowRework.workflowTasks } : {}),
          ...(nextApprovalSteps ? { approvalSteps: nextApprovalSteps } : {}),
          activityLog: log,
          idempotent: false as const,
        };
      });
      res.status(document.idempotent ? 200 : 201).json(document);
    } catch (error: any) {
      console.error('PCN dossier document write error:', error);
      const message = String(error?.message || error);
      const normalizedMessage = message.toLowerCase();
      const statusCode = Number(error?.statusCode)
        || (normalizedMessage.includes('không tìm thấy') || normalizedMessage.includes('không thuộc') ? 404 : 400);
      res.status(statusCode).json({ error: message });
    }
  });

  app.post('/api/pcn/dossiers/:dossierId/documents/:requirementId/waive', async (req, res) => {
    if (!requirePcnMutation(req, res)) return;
    const dossierId = String(req.params.dossierId || '').trim();
    const requirementId = String(req.params.requirementId || '').trim();
    const reason = String(req.body?.reason || '').trim();
    if (!isSafePcnSampleKey(dossierId) || !isSafePcnSampleKey(requirementId) || !reason || reason.length > 1000) {
      res.status(400).json({ error: 'Lý do bỏ qua tài liệu phải có từ 1 đến 1000 ký tự.' });
      return;
    }
    const actor = getPcnSessionUser(req)! as PcnUserAccount;
    try {
      const result = await withPgTransaction(async (client) => {
        const dossierResult = await client.query(`SELECT document_id, data FROM app_documents WHERE collection_name = 'certificationDossiers' AND document_id = $1 LIMIT 1 FOR UPDATE`, [dossierId]);
        if (!dossierResult.rows[0]) throw Object.assign(new Error('Không tìm thấy hồ sơ PCN.'), { statusCode: 404 });
        const dossier = mapDocumentRow(dossierResult.rows[0]) as CertificationDossier;
        if (isPcnDossierPostApprovalLocked(dossier.status)) throw Object.assign(new Error('Hồ sơ đã duyệt/phát hành; phải thu hồi có lý do trước khi bỏ qua tài liệu.'), { statusCode: 409 });
        await assertPcnDossierNodeOperator(client, dossier, requirementId, actor);
        const requirementResult = await client.query(`SELECT document_id, data FROM app_documents WHERE collection_name = 'pcnDocumentRequirements' AND document_id = $1 LIMIT 1`, [requirementId]);
        const requirement = requirementResult.rows[0] ? mapDocumentRow(requirementResult.rows[0]) as PcnDocumentRequirement : undefined;
        const fieldCodes = Array.isArray(dossier.fieldCodes) ? dossier.fieldCodes.map((code: unknown) => String(code).trim().toUpperCase()) : [];
        if (!requirement || requirement.active !== true || !fieldCodes.includes(String(requirement.fieldCode || '').trim().toUpperCase())) throw Object.assign(new Error('Loại tài liệu không thuộc Lĩnh vực của hồ sơ PCN.'), { statusCode: 404 });
        if (!canProcessPcnDossierRequirement(dossier, requirement)) throw Object.assign(new Error('Tài liệu thuộc bước chưa đến; hãy hoàn tất bước hiện tại trước.'), { statusCode: 409 });
        const documentId = buildPcnDossierDocumentId(dossierId, requirementId);
        const documentResult = await client.query(`SELECT document_id, data FROM app_documents WHERE collection_name = 'dossierDocuments' AND document_id = $1 LIMIT 1 FOR UPDATE`, [documentId]);
        const document = documentResult.rows[0] ? mapDocumentRow(documentResult.rows[0]) as PcnDossierDocument : undefined;
        if (document?.status === 'PRESENT' && document.currentVersionId) throw Object.assign(new Error('Không thể bỏ qua khi tài liệu hiện tại đang có; hãy xóa phiên hiện tại trước.'), { statusCode: 409 });
        const now = new Date().toISOString();
        const nextWaiver = { requirementId, reason, decidedAt: now, decidedBy: actor.username };
        const dossierWithWaiver: CertificationDossier = { ...dossier, documentWaivers: { ...(dossier.documentWaivers || {}), [requirementId]: nextWaiver }, updatedAt: now };
        const workflowRework = await applyPcnDossierDocumentRework(client, dossierWithWaiver, requirement, actor, now);
        for (const nextTask of workflowRework.workflowTasks || []) {
          await client.query(`UPDATE app_documents SET data = $2::jsonb, updated_at = CURRENT_TIMESTAMP WHERE collection_name = 'pcnDossierWorkflowTasks' AND document_id = $1`, [nextTask.id, JSON.stringify(getDocumentPayload(nextTask))]);
        }
        const nextDossier: CertificationDossier = { ...workflowRework.dossier, documentWaivers: dossierWithWaiver.documentWaivers, updatedAt: now };
        await client.query(`UPDATE app_documents SET data = $2::jsonb, updated_at = CURRENT_TIMESTAMP WHERE collection_name = 'certificationDossiers' AND document_id = $1`, [dossierId, JSON.stringify(getDocumentPayload(nextDossier))]);
        const activityLog = buildActivityLog({ action: 'UPDATED', entityType: 'PCN_DOSSIER', entityId: dossierId, entityLabel: dossier.dossierCode || dossierId, actorUsername: actor.username, actorName: actor.name || 'Người dùng PCN', actorRole: actor.systemRole || actor.role, summary: `Đánh dấu bỏ qua tài liệu ${requirement.name} và ghi lý do`, source: 'UI', groupId: dossierId, changes: diffActivityFields(dossier, nextDossier, ['documentWaivers', 'updatedAt']), createdAt: now });
        const validationError = validateActivityLogPayload(activityLog);
        if (validationError) throw new Error(validationError);
        await client.query(`INSERT INTO app_documents (collection_name, document_id, data, updated_at) VALUES ('activityLogs', $1, $2::jsonb, CURRENT_TIMESTAMP) ON CONFLICT (collection_name, document_id) DO NOTHING`, [activityLog.id, JSON.stringify(getDocumentPayload(activityLog))]);
        return { ...(document ? { document } : {}), dossier: nextDossier, ...(workflowRework.workflowTasks ? { workflowTasks: workflowRework.workflowTasks } : {}), activityLog };
      });
      res.json(result);
    } catch (error: any) {
      const message = String(error?.message || error);
      res.status(Number(error?.statusCode) || (message.toLowerCase().includes('không tìm thấy') ? 404 : 400)).json({ error: message });
    }
  });

  app.post('/api/pcn/dossiers/:dossierId/documents/:requirementId/remove-current', async (req, res) => {
    if (!requirePcnMutation(req, res)) return;
    const dossierId = String(req.params.dossierId || '').trim();
    const requirementId = String(req.params.requirementId || '').trim();
    if (!isSafePcnSampleKey(dossierId) || !isSafePcnSampleKey(requirementId)) { res.status(400).json({ error: 'Mã hồ sơ hoặc requirement không hợp lệ.' }); return; }
    const actor = getPcnSessionUser(req)! as PcnUserAccount;
    try {
      const result = await withPgTransaction(async (client) => {
        const dossierResult = await client.query(`SELECT document_id, data FROM app_documents WHERE collection_name = 'certificationDossiers' AND document_id = $1 LIMIT 1 FOR UPDATE`, [dossierId]);
        if (!dossierResult.rows[0]) throw Object.assign(new Error('Không tìm thấy hồ sơ PCN.'), { statusCode: 404 });
        const dossier = mapDocumentRow(dossierResult.rows[0]) as CertificationDossier;
        if (isPcnDossierPostApprovalLocked(dossier.status)) throw Object.assign(new Error('Hồ sơ đã duyệt/phát hành; phải thu hồi có lý do trước khi xóa phiên tài liệu.'), { statusCode: 409 });
        await assertPcnDossierNodeOperator(client, dossier, requirementId, actor);
        const requirementResult = await client.query(`SELECT document_id, data FROM app_documents WHERE collection_name = 'pcnDocumentRequirements' AND document_id = $1 LIMIT 1`, [requirementId]);
        const requirement = requirementResult.rows[0] ? mapDocumentRow(requirementResult.rows[0]) as PcnDocumentRequirement : undefined;
        const fieldCodes = Array.isArray(dossier.fieldCodes) ? dossier.fieldCodes.map((code: unknown) => String(code).trim().toUpperCase()) : [];
        if (!requirement || requirement.active !== true || !fieldCodes.includes(String(requirement.fieldCode || '').trim().toUpperCase())) throw Object.assign(new Error('Loại tài liệu không thuộc Lĩnh vực của hồ sơ PCN.'), { statusCode: 404 });
        const documentId = buildPcnDossierDocumentId(dossierId, requirementId);
        const documentResult = await client.query(`SELECT document_id, data FROM app_documents WHERE collection_name = 'dossierDocuments' AND document_id = $1 LIMIT 1 FOR UPDATE`, [documentId]);
        if (!documentResult.rows[0]) throw Object.assign(new Error('Không tìm thấy checklist tài liệu của hồ sơ.'), { statusCode: 404 });
        const document = mapDocumentRow(documentResult.rows[0]) as PcnDossierDocument;
        const now = new Date().toISOString();
        const nextDocument: PcnDossierDocument = { ...document, currentVersionId: undefined, status: 'MISSING', updatedAt: now };
        await client.query(`UPDATE app_documents SET data = $2::jsonb, updated_at = CURRENT_TIMESTAMP WHERE collection_name = 'dossierDocuments' AND document_id = $1`, [documentId, JSON.stringify(getDocumentPayload(nextDocument))]);
        const nextWaivers = { ...(dossier.documentWaivers || {}) };
        delete nextWaivers[requirementId];
        const workflowRework = await applyPcnDossierDocumentRework(client, { ...dossier, documentWaivers: nextWaivers }, requirement, actor, now);
        const nextDossier: CertificationDossier = { ...workflowRework.dossier, documentWaivers: nextWaivers, updatedAt: now };
        await client.query(`UPDATE app_documents SET data = $2::jsonb, updated_at = CURRENT_TIMESTAMP WHERE collection_name = 'certificationDossiers' AND document_id = $1`, [dossierId, JSON.stringify(getDocumentPayload(nextDossier))]);
        const activityLog = buildActivityLog({ action: 'UPDATED', entityType: 'PCN_DOSSIER', entityId: dossierId, entityLabel: dossier.dossierCode || dossierId, actorUsername: actor.username, actorName: actor.name || 'Người dùng PCN', actorRole: actor.systemRole || actor.role, summary: `Gỡ phiên tài liệu hiện tại ${requirement.name}; giữ nguyên lịch sử phiên`, source: 'UI', groupId: dossierId, changes: diffActivityFields(document, nextDocument, ['currentVersionId', 'status', 'updatedAt']) .concat(diffActivityFields(dossier, nextDossier, ['documentWaivers', 'updatedAt'])), createdAt: now });
        const validationError = validateActivityLogPayload(activityLog);
        if (validationError) throw new Error(validationError);
        await client.query(`INSERT INTO app_documents (collection_name, document_id, data, updated_at) VALUES ('activityLogs', $1, $2::jsonb, CURRENT_TIMESTAMP) ON CONFLICT (collection_name, document_id) DO NOTHING`, [activityLog.id, JSON.stringify(getDocumentPayload(activityLog))]);
        return { document: nextDocument, dossier: nextDossier, ...(workflowRework.workflowTasks ? { workflowTasks: workflowRework.workflowTasks } : {}), activityLog };
      });
      res.json(result);
    } catch (error: any) {
      const message = String(error?.message || error);
      res.status(Number(error?.statusCode) || (message.toLowerCase().includes('không tìm thấy') ? 404 : 400)).json({ error: message });
    }
  });

  app.post('/api/pcn/dossiers/:dossierId/node-work/:nodeId/generate-and-attach', async (req, res) => {
    if (!requirePcnMutation(req, res)) return;
    const actor = getPcnSessionUser(req)! as PcnUserAccount;
    const dossierId = String(req.params.dossierId || '').trim();
    const nodeId = String(req.params.nodeId || '').trim();
    const requirementId = String(req.body?.requirementId || '').trim();
    const requestedKind = String(req.body?.kind || '').trim().toUpperCase();
    if (!isSafePcnSampleKey(dossierId) || !isSafePcnSampleKey(nodeId) || !isSafePcnSampleKey(requirementId)) {
      res.status(400).json({ error: 'Mã hồ sơ, node hoặc requirement không hợp lệ.' });
      return;
    }

    const uploadedObjects: Array<{ bucketName: string; objectPath: string }> = [];
    try {
      const storage = getPcnStorageClient();
      const bucketName = getPcnStorageBucket();
      await storage.ensurePrivateBucket(bucketName, PCN_FILE_MAX_BYTES);
      const result = await withPgTransaction(async (client) => {
        const dossierResult = await client.query(`SELECT document_id, data FROM app_documents WHERE collection_name = 'certificationDossiers' AND document_id = $1 LIMIT 1 FOR UPDATE`, [dossierId]);
        if (!dossierResult.rows[0]) throw Object.assign(new Error('Không tìm thấy hồ sơ PCN.'), { statusCode: 404 });
        const dossier = mapDocumentRow(dossierResult.rows[0]) as CertificationDossier;
        if (isPcnDossierPostApprovalLocked(dossier.status)) throw Object.assign(new Error('Hồ sơ đã duyệt/phát hành; phải thu hồi có lý do trước khi sinh tài liệu.'), { statusCode: 409 });
        if (!dossier.workflowSnapshot) throw Object.assign(new Error('Hồ sơ chưa có snapshot lưu trình để xử lý theo node.'), { statusCode: 409 });
        const node = dossier.workflowSnapshot.nodes.find((candidate) => candidate.id === nodeId && candidate.active !== false);
        if (!node || !node.requirementIds.includes(requirementId)) throw Object.assign(new Error('Requirement không thuộc node đang chọn.'), { statusCode: 400 });
        const taskResult = await client.query(`SELECT document_id, data FROM app_documents WHERE collection_name = 'pcnDossierWorkflowTasks' AND data->>'dossierId' = $1 AND data->>'nodeId' = $2 LIMIT 1 FOR UPDATE`, [dossierId, nodeId]);
        const task = taskResult.rows[0] ? mapDocumentRow(taskResult.rows[0]) as PcnDossierWorkflowTask : undefined;
        if (!task || !['READY', 'IN_PROGRESS', 'WAITING', 'RETURNED', 'COMPLETED'].includes(task.status)) throw Object.assign(new Error('Node chưa sẵn sàng để sinh tài liệu.'), { statusCode: 409 });
        await assertPcnDossierNodeOperator(client, dossier, requirementId, actor);

        const requirementResult = await client.query(`SELECT document_id, data FROM app_documents WHERE collection_name = 'pcnDocumentRequirements' AND document_id = $1 LIMIT 1`, [requirementId]);
        const requirement = requirementResult.rows[0] ? mapDocumentRow(requirementResult.rows[0]) as PcnDocumentRequirement : undefined;
        const fieldCodes = Array.isArray(dossier.fieldCodes) ? dossier.fieldCodes.map((code: unknown) => String(code).trim().toUpperCase()).filter(Boolean) : [];
        if (!requirement || requirement.active !== true || !fieldCodes.includes(String(requirement.fieldCode || '').trim().toUpperCase())) throw Object.assign(new Error('Loại tài liệu không thuộc Lĩnh vực của hồ sơ PCN.'), { statusCode: 400 });
        if (!canProcessPcnDossierRequirement(dossier, requirement)) throw Object.assign(new Error('Tài liệu thuộc bước chưa đến; hãy hoàn tất bước hiện tại trước.'), { statusCode: 409 });
        const kind = getPcnNodeDocumentGenerationKind(requirement.code);
        if (!kind || (requestedKind && requestedKind !== kind)) throw Object.assign(new Error('Requirement này chưa có biểu mẫu sinh tự động tương ứng.'), { statusCode: 400 });

        const documentId = buildPcnDossierDocumentId(dossierId, requirementId);
        const existingDocumentResult = await client.query(`SELECT document_id, data FROM app_documents WHERE collection_name = 'dossierDocuments' AND document_id = $1 LIMIT 1 FOR UPDATE`, [documentId]);
        const previous = existingDocumentResult.rows[0]?.data || {};

        const proposalId = String(dossier.proposalId || '').trim();
        const proposalResult = await client.query(`SELECT document_id, data FROM app_documents WHERE collection_name = 'certificationProposals' AND document_id = $1 LIMIT 1`, [proposalId]);
        if (!proposalResult.rows[0]) throw Object.assign(new Error('Không tìm thấy Đề nghị liên kết với hồ sơ.'), { statusCode: 404 });
        const proposal = mapDocumentRow(proposalResult.rows[0]) as CertificationProposal;
        const [fieldsResult, requirementsResult, documentsResult, attachmentsResult, lotsResult, routesResult, requestsResult] = await Promise.all([
          client.query(`SELECT document_id, data FROM app_documents WHERE collection_name = 'pcnCertificationFields' AND data->>'code' = ANY($1::text[])`, [fieldCodes]),
          client.query(`SELECT document_id, data FROM app_documents WHERE collection_name = 'pcnDocumentRequirements' AND COALESCE((data->>'active')::boolean, false) = true AND data->>'fieldCode' = ANY($1::text[])`, [fieldCodes]),
          client.query(`SELECT document_id, data FROM app_documents WHERE collection_name = 'dossierDocuments' AND data->>'dossierId' = $1`, [dossier.id]),
          client.query(`SELECT document_id, data FROM app_documents WHERE collection_name = 'dossierAttachments' AND data->>'dossierId' = $1`, [dossier.id]),
          client.query(`SELECT document_id, data FROM app_documents WHERE collection_name = 'pcnSampleLots' AND data->>'dossierId' = $1`, [dossier.id]),
          client.query(`SELECT document_id, data FROM app_documents WHERE collection_name = 'pcnSampleRoutes'`),
          client.query(`SELECT document_id, data FROM app_documents WHERE collection_name = 'labRequests' AND data->>'dossierId' = $1`, [dossier.id]),
        ]);
        const fields = fieldsResult.rows.map(mapDocumentRow) as PcnCertificationField[];
        const requirements = requirementsResult.rows.map(mapDocumentRow) as PcnDocumentRequirement[];
        const documents = documentsResult.rows.map(mapDocumentRow) as PcnDossierDocument[];
        const attachments = attachmentsResult.rows.map(mapDocumentRow) as PcnDossierAttachment[];
        const sampleLots = lotsResult.rows.map(mapDocumentRow) as PcnSampleLot[];
        const sampleRoutes = routesResult.rows.map(mapDocumentRow) as PcnSampleRoute[];
        const labRequests = requestsResult.rows.map(mapDocumentRow) as OutboundLabRequest[];
        const dossierRoute = sampleRoutes.find((route) => sampleLots.some((lot) => lot.id === route.sampleLotId));
        const dossierRequest = labRequests.find((request) => request.fieldCode === requirement.fieldCode) || labRequests[0];
        if (['SAMPLE_CODING', 'SAMPLE_HANDOVER', 'SAMPLE_RETURN'].includes(kind) && !dossierRoute) throw Object.assign(new Error('Chưa có tuyến mẫu thuộc hồ sơ để sinh tài liệu.'), { statusCode: 409 });
        if (kind === 'LAB_REQUEST' && !dossierRequest) throw Object.assign(new Error('Chưa có PYC thuộc hồ sơ để sinh tài liệu.'), { statusCode: 409 });
        const context = buildPcnDossierDocumentContext({
          dossier,
          proposal,
          fields,
          documents,
          documentRequirements: requirements,
          attachments,
          sampleLots,
          sampleRoutes,
          labRequests,
          ...(kind === 'SAMPLE_CODING' || kind === 'SAMPLE_HANDOVER' || kind === 'SAMPLE_RETURN' ? { sampleRouteId: dossierRoute?.id } : {}),
          ...(kind === 'LAB_REQUEST' ? { labRequestId: dossierRequest?.id } : {}),
        });
        const body = renderPcnNodeGeneratedDocx(kind, context);
        const sha256 = createHash('sha256').update(body).digest('hex');
        const safeDossierId = sanitizePcnPathSegment(dossier.id).toLowerCase().replace(/[^a-z0-9-]+/g, '-').slice(0, 36) || 'dossier';
        const safeNodeId = sanitizePcnPathSegment(nodeId).toLowerCase().slice(0, 40) || 'node';
        const kindSlug = kind.toLowerCase().replace(/_/g, '-');
        const generatedId = `pcn-generated-node-${safeDossierId}-${safeNodeId}-${sha256.slice(0, 16)}`;
        const generatedAssetId = `pcn-file-generated-${safeDossierId}-${safeNodeId}-${kindSlug}-${sha256.slice(0, 16)}`;
        const generatedObjectPath = `pcnGenerated/${safeDossierId}/node-work/${safeNodeId}/${sha256}/docx`;
        const fileName = `${sanitizePcnPathSegment(dossier.dossierCode || dossier.id)}-${kindSlug}.docx`;
        const existingAssetResult = await client.query(`SELECT id, bucket_name, object_path, source_collection, source_document_id, source_json_path, mime_type, byte_size, sha256 FROM file_assets WHERE id = $1 LIMIT 1 FOR UPDATE`, [generatedAssetId]);
        const existingAsset = existingAssetResult.rows[0];
        if (existingAsset && (existingAsset.bucket_name !== bucketName || existingAsset.object_path !== generatedObjectPath || existingAsset.source_collection !== 'pcnGeneratedDocuments' || existingAsset.source_document_id !== generatedId || existingAsset.source_json_path !== 'fileAssetId' || existingAsset.mime_type !== 'application/vnd.openxmlformats-officedocument.wordprocessingml.document' || Number(existingAsset.byte_size) !== body.length || String(existingAsset.sha256).toLowerCase() !== sha256)) throw new Error('Asset bản sinh node trùng mã nhưng metadata provenance không khớp.');
        if (!existingAsset) {
          await storage.uploadObject({ bucketName, objectPath: generatedObjectPath, body, mimeType: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document' });
          uploadedObjects.push({ bucketName, objectPath: generatedObjectPath });
          await client.query(`INSERT INTO file_assets (id, bucket_name, object_path, source_collection, source_document_id, source_json_path, mime_type, byte_size, sha256) VALUES ($1, $2, $3, 'pcnGeneratedDocuments', $4, 'fileAssetId', $5, $6, $7)`, [generatedAssetId, bucketName, generatedObjectPath, generatedId, 'application/vnd.openxmlformats-officedocument.wordprocessingml.document', body.length, sha256]);
        }
        const now = new Date().toISOString();
        const generated: PcnGeneratedDocument = { id: generatedId, dossierId: dossier.id, kind, format: 'DOCX', ...(dossierRoute?.id ? { sampleRouteId: dossierRoute.id } : {}), ...(dossierRequest?.id ? { labRequestId: dossierRequest.id } : {}), fileAssetId: generatedAssetId, fileName, mimeType: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document', byteSize: body.length, sha256, contextHash: context.contextHash, generatedAt: now, ...(actor.username ? { generatedBy: actor.username } : {}) };
        const generatedWrite = await client.query(`INSERT INTO app_documents (collection_name, document_id, data, updated_at) VALUES ('pcnGeneratedDocuments', $1, $2::jsonb, CURRENT_TIMESTAMP) ON CONFLICT (collection_name, document_id) DO NOTHING RETURNING document_id, data`, [generatedId, JSON.stringify(getDocumentPayload(generated))]);
        const persistedGenerated = generatedWrite.rows[0] ? mapDocumentRow(generatedWrite.rows[0]) as PcnGeneratedDocument : generated;

        const dossierAssetId = `pcn-file-confirm-${createHash('sha256').update(`${dossierId}\u0000${generatedId}\u0000${requirementId}\u0000${sha256}`).digest('hex').slice(0, 32)}`;
        const dossierObjectPath = `pcnFiles/dossierDocuments/${sanitizePcnPathSegment(documentId)}/${sanitizePcnPathSegment(requirementId)}/${dossierAssetId}-${sha256}-${sanitizePcnPathSegment(fileName)}`;
        const previousVersions = Array.isArray(previous.versions) ? previous.versions : [];
        const existingDossierAssetResult = await client.query(`SELECT id, bucket_name, object_path, source_collection, source_document_id, source_json_path, mime_type, byte_size, sha256 FROM file_assets WHERE id = $1 LIMIT 1 FOR UPDATE`, [dossierAssetId]);
        const existingDossierAsset = existingDossierAssetResult.rows[0];
        if (previous.currentVersionId) {
          const currentVersion = previousVersions.find((version: any) => version?.assetId === previous.currentVersionId);
          if (!currentVersion?.note?.includes(generatedId)) throw Object.assign(new Error('Tài liệu hiện tại đã tồn tại; hãy dùng thao tác thay phiên bản.'), { statusCode: 409 });
          const existingAttachmentResult = await client.query(`SELECT document_id, data FROM app_documents WHERE collection_name = 'dossierAttachments' AND document_id = $1 LIMIT 1 FOR UPDATE`, [`pcn-attachment-generated-${dossierAssetId}`]);
          if (!existingDossierAsset || !existingAttachmentResult.rows[0]) throw new Error('Checklist tự gắn đã có phiên nhưng thiếu provenance; cần rà soát trước khi retry.');
          const existingAsset = existingDossierAsset;
          return {
            generated: persistedGenerated,
            document: mapDocumentRow(existingDocumentResult.rows[0]) as PcnDossierDocument,
            attachment: mapDocumentRow(existingAttachmentResult.rows[0]) as PcnDossierAttachment,
            dossier,
            asset: { id: existingAsset.id, bucketName: existingAsset.bucket_name, objectPath: existingAsset.object_path, sourceCollection: existingAsset.source_collection, sourceDocumentId: existingAsset.source_document_id, sourceJsonPath: existingAsset.source_json_path, mimeType: existingAsset.mime_type, byteSize: Number(existingAsset.byte_size || 0), sha256: existingAsset.sha256 },
            idempotent: true as const,
          };
        }
        if (existingDossierAsset && (existingDossierAsset.bucket_name !== bucketName || existingDossierAsset.object_path !== dossierObjectPath || existingDossierAsset.source_collection !== 'dossierDocuments' || existingDossierAsset.source_document_id !== documentId || existingDossierAsset.source_json_path !== requirementId || existingDossierAsset.mime_type !== generated.mimeType || Number(existingDossierAsset.byte_size) !== body.length || String(existingDossierAsset.sha256).toLowerCase() !== sha256)) throw new Error('Asset checklist tự gắn trùng mã nhưng metadata provenance không khớp.');
        if (!existingDossierAsset) {
          await storage.uploadObject({ bucketName, objectPath: dossierObjectPath, body, mimeType: generated.mimeType });
          uploadedObjects.push({ bucketName, objectPath: dossierObjectPath });
          await client.query(`INSERT INTO file_assets (id, bucket_name, object_path, source_collection, source_document_id, source_json_path, mime_type, byte_size, sha256) VALUES ($1, $2, $3, 'dossierDocuments', $4, $5, $6, $7, $8)`, [dossierAssetId, bucketName, dossierObjectPath, documentId, requirementId, generated.mimeType, body.length, sha256]);
        }
        const nextDocument: PcnDossierDocument = { ...previous, id: documentId, dossierId, requirementId, fieldCode: requirement.fieldCode, currentVersionId: dossierAssetId, versions: [...previousVersions, { assetId: dossierAssetId, fileName, mimeType: generated.mimeType, byteSize: body.length, sha256, uploadedAt: now, uploadedBy: actor.username, note: `Tự sinh và gắn từ node ${nodeId} (${generatedId}).` }], status: 'PRESENT', createdAt: previous.createdAt || now, updatedAt: now };
        await client.query(`INSERT INTO app_documents (collection_name, document_id, data, updated_at) VALUES ('dossierDocuments', $1, $2::jsonb, CURRENT_TIMESTAMP) ON CONFLICT (collection_name, document_id) DO UPDATE SET data = EXCLUDED.data, updated_at = CURRENT_TIMESTAMP`, [documentId, JSON.stringify(getDocumentPayload(nextDocument))]);
        const attachment = buildPcnGeneratedDossierAttachment({ dossierId, requirement, generated: persistedGenerated, assetId: dossierAssetId });
        await client.query(`INSERT INTO app_documents (collection_name, document_id, data, updated_at) VALUES ('dossierAttachments', $1, $2::jsonb, CURRENT_TIMESTAMP) ON CONFLICT (collection_name, document_id) DO NOTHING`, [attachment.id, JSON.stringify(getDocumentPayload(attachment))]);
        const workflowRework = await applyPcnDossierDocumentRework(client, dossier, requirement, actor, now);
        const nextDossier: CertificationDossier = { ...workflowRework.dossier, updatedAt: now };
        await client.query(`UPDATE app_documents SET data = $2::jsonb, updated_at = CURRENT_TIMESTAMP WHERE collection_name = 'certificationDossiers' AND document_id = $1`, [dossierId, JSON.stringify(getDocumentPayload(nextDossier))]);
        const activityLog = buildActivityLog({ action: 'CREATED', entityType: 'PCN_DOSSIER', entityId: dossierId, entityLabel: dossier.dossierCode || dossierId, actorUsername: actor.username, actorName: actor.name || 'Người dùng PCN', actorRole: actor.systemRole || actor.role, summary: `Tự sinh và gắn ${fileName} vào node ${nodeId}`, source: 'USER_REVIEW', groupId: generatedId, changes: diffActivityFields(dossier, nextDossier, ['updatedAt', 'status']), createdAt: now });
        const validationError = validateActivityLogPayload(activityLog);
        if (validationError) throw new Error(validationError);
        await client.query(`INSERT INTO app_documents (collection_name, document_id, data, updated_at) VALUES ('activityLogs', $1, $2::jsonb, CURRENT_TIMESTAMP) ON CONFLICT (collection_name, document_id) DO NOTHING`, [activityLog.id, JSON.stringify(getDocumentPayload(activityLog))]);
        const asset = existingDossierAsset || { id: dossierAssetId, bucket_name: bucketName, object_path: dossierObjectPath, source_collection: 'dossierDocuments', source_document_id: documentId, source_json_path: requirementId, mime_type: generated.mimeType, byte_size: body.length, sha256 };
        return { generated: persistedGenerated, document: nextDocument, attachment, dossier: nextDossier, asset: { id: asset.id, bucketName: asset.bucket_name, objectPath: asset.object_path, sourceCollection: asset.source_collection, sourceDocumentId: asset.source_document_id, sourceJsonPath: asset.source_json_path, mimeType: asset.mime_type, byteSize: Number(asset.byte_size || 0), sha256: asset.sha256 }, ...(workflowRework.workflowTasks ? { workflowTasks: workflowRework.workflowTasks } : {}), activityLog, idempotent: false as const };
      });
      res.status(result.idempotent ? 200 : 201).json(result);
    } catch (error: any) {
      for (const uploaded of uploadedObjects.reverse()) {
        try { await getPcnStorageClient().deleteObject(uploaded); } catch { /* preserve original error */ }
      }
      const message = String(error?.message || error);
      res.status(Number(error?.statusCode) || (message.toLowerCase().includes('không tìm thấy') ? 404 : 400)).json({ error: message });
    }
  });

  app.post('/api/pcn/dossiers/:dossierId/documents/confirm-generated', async (req, res) => {
    if (!requirePcnMutation(req, res)) return;
    const actor = getPcnSessionUser(req)!;
    const dossierId = String(req.params.dossierId || '').trim();
    const generatedDocumentId = String(req.body?.generatedDocumentId || '').trim();
    const requirementId = String(req.body?.requirementId || '').trim();
    if (!dossierId || !generatedDocumentId || !requirementId || generatedDocumentId.length > 240 || requirementId.length > 200 || /[\\/]/.test(generatedDocumentId) || /[\\/]/.test(requirementId)) {
      res.status(400).json({ error: 'Thiếu metadata xác nhận bản sinh vào checklist.' });
      return;
    }

    const uploadedObjects: Array<{ bucketName: string; objectPath: string }> = [];
    try {
      const storage = getPcnStorageClient();
      const bucketName = getPcnStorageBucket();
      await storage.ensurePrivateBucket(bucketName, PCN_FILE_MAX_BYTES);
      const result = await withPgTransaction(async (client) => {
        const dossierResult = await client.query(
          `SELECT document_id, data FROM app_documents
           WHERE collection_name = 'certificationDossiers' AND document_id = $1
           LIMIT 1 FOR UPDATE`,
          [dossierId],
        );
        if (dossierResult.rows.length === 0) throw new Error('Không tìm thấy hồ sơ PCN.');
        const dossier = mapDocumentRow(dossierResult.rows[0]) as CertificationDossier;
        if (isPcnDossierPostApprovalLocked(dossier.status)) {
          throw Object.assign(new Error('Hồ sơ đã duyệt/phát hành; phải thu hồi có lý do trước khi xác nhận tài liệu.'), { statusCode: 409 });
        }
        assertPcnDossierOperator(dossier, actor);
        const dossierFieldCodes = Array.isArray(dossier.fieldCodes)
          ? dossier.fieldCodes.map((code: unknown) => String(code).trim().toUpperCase()).filter(Boolean)
          : [];

        const requirementResult = await client.query(
          `SELECT document_id, data FROM app_documents
           WHERE collection_name = 'pcnDocumentRequirements' AND document_id = $1
           LIMIT 1`,
          [requirementId],
        );
        const requirement = requirementResult.rows[0]
          ? mapDocumentRow(requirementResult.rows[0]) as PcnDocumentRequirement
          : undefined;
        const requirementCode = String(requirement?.code || '').trim().toUpperCase();
        const requirementFieldCode = String(requirement?.fieldCode || '').trim().toUpperCase();
        if (!requirement || requirement.active !== true || !requirementCode || !dossierFieldCodes.includes(requirementFieldCode)) {
          throw new Error('Loại tài liệu không thuộc Lĩnh vực của hồ sơ PCN.');
        }
        if (!canProcessPcnDossierRequirement(dossier, requirement)) {
          throw Object.assign(new Error('Tài liệu thuộc bước chưa đến; hãy hoàn tất bước hiện tại trước.'), { statusCode: 409 });
        }

        const generatedResult = await client.query(
          `SELECT document_id, data FROM app_documents
           WHERE collection_name = 'pcnGeneratedDocuments'
             AND document_id = $1
             AND data->>'dossierId' = $2
           LIMIT 1 FOR UPDATE`,
          [generatedDocumentId, dossierId],
        );
        if (generatedResult.rows.length === 0) throw new Error('Không tìm thấy bản sinh thuộc hồ sơ PCN.');
        const generated = mapDocumentRow(generatedResult.rows[0]) as PcnGeneratedDocument;
        const expectedRequirementCode = getPcnGeneratedDocumentRequirementCode(generated.kind);
        if (!expectedRequirementCode || requirementCode !== expectedRequirementCode) {
          throw new Error('Bản sinh không có ánh xạ 1-1 với mã tài liệu checklist đã chọn.');
        }
        if (generated.dossierId !== dossier.id || !String(generated.fileAssetId || '').trim() || !generated.fileName || !generated.sha256 || !/^[a-f0-9]{64}$/i.test(generated.sha256)) {
          throw new Error('Metadata bản sinh không hợp lệ hoặc không thuộc hồ sơ PCN.');
        }
        const expectedMimeType = generated.format === 'PDF'
          ? 'application/pdf'
          : 'application/vnd.openxmlformats-officedocument.wordprocessingml.document';
        if (!['DOCX', 'PDF'].includes(generated.format) || generated.mimeType !== expectedMimeType || !Number.isFinite(Number(generated.byteSize)) || Number(generated.byteSize) <= 0) {
          throw new Error('Metadata định dạng bản sinh không hợp lệ.');
        }

        const generatedAssetResult = await client.query(
          `SELECT id, bucket_name, object_path, source_collection, source_document_id, source_json_path, mime_type, byte_size, sha256
           FROM file_assets WHERE id = $1 LIMIT 1 FOR UPDATE`,
          [generated.fileAssetId],
        );
        const generatedAsset = generatedAssetResult.rows[0];
        if (!generatedAsset
          || generatedAsset.bucket_name !== bucketName
          || generatedAsset.source_collection !== 'pcnGeneratedDocuments'
          || generatedAsset.source_document_id !== generated.id
          || generatedAsset.source_json_path !== 'fileAssetId'
          || generatedAsset.mime_type !== generated.mimeType
          || Number(generatedAsset.byte_size) !== Number(generated.byteSize)
          || String(generatedAsset.sha256).toLowerCase() !== String(generated.sha256).toLowerCase()) {
          throw new Error('Asset bản sinh không khớp metadata provenance; không thể xác nhận vào checklist.');
        }

        const documentId = buildPcnDossierDocumentId(dossierId, requirementId);
        const existingDocumentResult = await client.query(
          `SELECT document_id, data FROM app_documents
           WHERE collection_name = 'dossierDocuments' AND document_id = $1
           LIMIT 1 FOR UPDATE`,
          [documentId],
        );
        const previous = existingDocumentResult.rows[0]?.data || {};
        const previousVersions = Array.isArray(previous.versions) ? previous.versions : [];
        const confirmationNote = `Xác nhận từ bản sinh ${generated.id}.`;
        const confirmationFingerprint = createHash('sha256')
          .update(`${dossierId}\u0000${generated.id}\u0000${requirementId}\u0000${generated.sha256}`)
          .digest('hex');
        const assetId = `pcn-file-confirm-${confirmationFingerprint.slice(0, 32)}`;
        const safeFileName = sanitizePcnPathSegment(generated.fileName);
        const objectPath = `pcnFiles/dossierDocuments/${sanitizePcnPathSegment(documentId)}/${sanitizePcnPathSegment(requirementId)}/${assetId}-${generated.sha256}-${safeFileName}`;
        const assetResult = await client.query(
          `SELECT id, bucket_name, object_path, source_collection, source_document_id, source_json_path, mime_type, byte_size, sha256
           FROM file_assets WHERE id = $1 LIMIT 1 FOR UPDATE`,
          [assetId],
        );
        const existingAsset = assetResult.rows[0];
        if (existingAsset && (
          existingAsset.bucket_name !== bucketName
          || existingAsset.object_path !== objectPath
          || existingAsset.source_collection !== 'dossierDocuments'
          || existingAsset.source_document_id !== documentId
          || existingAsset.source_json_path !== requirementId
          || existingAsset.mime_type !== generated.mimeType
          || Number(existingAsset.byte_size) !== Number(generated.byteSize)
          || String(existingAsset.sha256).toLowerCase() !== String(generated.sha256).toLowerCase()
        )) {
          throw new Error('Asset checklist xác nhận trùng mã nhưng metadata provenance không khớp.');
        }

        const attachmentId = `pcn-attachment-generated-${assetId}`;
        const existingAttachmentResult = await client.query(
          `SELECT document_id, data FROM app_documents
           WHERE collection_name = 'dossierAttachments' AND document_id = $1
           LIMIT 1 FOR UPDATE`,
          [attachmentId],
        );
        const existingAttachment = existingAttachmentResult.rows[0]
          ? mapDocumentRow(existingAttachmentResult.rows[0]) as PcnDossierAttachment
          : undefined;
        const hasVersion = previousVersions.some((version: any) => String(version?.assetId || '') === assetId || String(version?.note || '') === confirmationNote);
        if (hasVersion && existingAttachment && existingAsset) {
          return {
            document: mapDocumentRow(existingDocumentResult.rows[0]),
            asset: {
              id: existingAsset.id,
              bucketName: existingAsset.bucket_name,
              objectPath: existingAsset.object_path,
              sourceCollection: existingAsset.source_collection,
              sourceDocumentId: existingAsset.source_document_id,
              sourceJsonPath: existingAsset.source_json_path,
              mimeType: existingAsset.mime_type,
              byteSize: Number(existingAsset.byte_size || 0),
              sha256: existingAsset.sha256,
            },
            dossier,
            attachment: existingAttachment,
            idempotent: true as const,
          };
        }

        let asset = existingAsset;
        if (!asset) {
          const downloaded = await storage.downloadObject({ bucketName: generatedAsset.bucket_name, objectPath: generatedAsset.object_path });
          const downloadedSha256 = createHash('sha256').update(downloaded.body).digest('hex');
          if (downloaded.body.length !== Number(generated.byteSize) || downloadedSha256.toLowerCase() !== String(generated.sha256).toLowerCase()) {
            throw new Error('Bytes bản sinh trong Storage không khớp SHA-256 hoặc byte size đã ghi.');
          }
          await storage.uploadObject({ bucketName, objectPath, body: downloaded.body, mimeType: generated.mimeType });
          uploadedObjects.push({ bucketName, objectPath });
          await client.query(
            `INSERT INTO file_assets (id, bucket_name, object_path, source_collection, source_document_id, source_json_path, mime_type, byte_size, sha256)
             VALUES ($1, $2, $3, 'dossierDocuments', $4, $5, $6, $7, $8)`,
            [assetId, bucketName, objectPath, documentId, requirementId, generated.mimeType, downloaded.body.length, downloadedSha256],
          );
          asset = {
            id: assetId,
            bucket_name: bucketName,
            object_path: objectPath,
            source_collection: 'dossierDocuments',
            source_document_id: documentId,
            source_json_path: requirementId,
            mime_type: generated.mimeType,
            byte_size: downloaded.body.length,
            sha256: downloadedSha256,
          };
        }

        const now = new Date().toISOString();
        let persistedDocument: PcnDossierDocument;
        if (hasVersion && existingDocumentResult.rows.length > 0) {
          persistedDocument = mapDocumentRow(existingDocumentResult.rows[0]) as PcnDossierDocument;
        } else {
          const version = {
            assetId,
            fileName: generated.fileName.slice(0, 255),
            mimeType: generated.mimeType,
            byteSize: Number(generated.byteSize),
            sha256: generated.sha256,
            uploadedAt: now,
            ...(getPcnSessionUser(req)?.username ? { uploadedBy: getPcnSessionUser(req)!.username } : {}),
            note: confirmationNote,
          };
          const next = {
            ...previous,
            dossierId,
            requirementId,
            fieldCode: requirementFieldCode,
            currentVersionId: assetId,
            versions: [...previousVersions, version],
            status: 'PRESENT',
            createdAt: previous.createdAt || now,
            updatedAt: now,
          };
          const write = await client.query(
            `INSERT INTO app_documents (collection_name, document_id, data, updated_at)
             VALUES ('dossierDocuments', $1, $2::jsonb, CURRENT_TIMESTAMP)
             ON CONFLICT (collection_name, document_id)
             DO UPDATE SET data = EXCLUDED.data, updated_at = CURRENT_TIMESTAMP
             RETURNING document_id, data`,
            [documentId, JSON.stringify(getDocumentPayload(next))],
          );
          persistedDocument = mapDocumentRow(write.rows[0]) as PcnDossierDocument;
        }

        const generatedAttachment = existingAttachment || buildPcnGeneratedDossierAttachment({ dossierId, requirement, generated, assetId });
        if (!existingAttachment) {
          await client.query(
            `INSERT INTO app_documents (collection_name, document_id, data, updated_at)
             VALUES ('dossierAttachments', $1, $2::jsonb, CURRENT_TIMESTAMP)`,
            [generatedAttachment.id, JSON.stringify(getDocumentPayload(generatedAttachment))],
          );
        }
        const workflowRework = await applyPcnDossierDocumentRework(client, dossier, requirement!, actor, now);

        const currentStageIndex = getPcnWorkflowStageIndex(getPcnWorkflowStage(dossier.status)?.key || 'INTAKE');
        const requirementStageIndex = getPcnRequirementWorkflowStageIndex(requirement!);
        const needsDownstreamReview = dossier.status === 'WAITING_APPROVAL'
          && requirementStageIndex >= 0
          && requirementStageIndex < currentStageIndex;
        const reopenStatus = getPcnRequirementReopenStatus(requirement!) || 'TECHNICAL_REVIEW';
        let nextApprovalSteps: PcnApprovalStep[] | undefined;
        if (needsDownstreamReview) {
          const approvalResult = await client.query(
            `SELECT document_id, data FROM app_documents
             WHERE collection_name = 'approvalSteps' AND data->>'dossierId' = $1
             ORDER BY COALESCE((data->>'sequence')::int, 999), document_id
             FOR UPDATE`,
            [dossier.id],
          );
          const allSteps = approvalResult.rows.map((row: any) => mapDocumentRow(row)) as PcnApprovalStep[];
          const effectiveStepIds = new Set(getPcnEffectiveApprovalSteps(allSteps).map((step) => step.id));
          nextApprovalSteps = allSteps.map((step) => effectiveStepIds.has(step.id)
            ? { ...step, status: 'PENDING' as const, actedAt: undefined }
            : step);
          for (const step of nextApprovalSteps) {
            await client.query(
              `UPDATE app_documents SET data = $2::jsonb, updated_at = CURRENT_TIMESTAMP
               WHERE collection_name = 'approvalSteps' AND document_id = $1`,
              [step.id, JSON.stringify(getDocumentPayload(step))],
            );
          }
          const issuanceResult = await client.query(
            `SELECT document_id, data FROM app_documents
             WHERE collection_name = 'issuancePackages' AND data->>'dossierId' = $1
             LIMIT 1 FOR UPDATE`,
            [dossier.id],
          );
          if (issuanceResult.rows[0]) {
            const issuance = mapDocumentRow(issuanceResult.rows[0]) as IssuancePackage;
            const nextIssuance: IssuancePackage = { ...issuance, status: 'RETURNED', updatedAt: now };
            await client.query(
              `UPDATE app_documents SET data = $2::jsonb, updated_at = CURRENT_TIMESTAMP
               WHERE collection_name = 'issuancePackages' AND document_id = $1`,
              [nextIssuance.id, JSON.stringify(getDocumentPayload(nextIssuance))],
            );
          }
        }
        const nextDossier: CertificationDossier = {
          ...workflowRework.dossier,
          ...(needsDownstreamReview ? { status: reopenStatus } : {}),
          updatedAt: now,
        };
        await client.query(
          `UPDATE app_documents SET data = $2::jsonb, updated_at = CURRENT_TIMESTAMP
           WHERE collection_name = 'certificationDossiers' AND document_id = $1`,
          [dossier.id, JSON.stringify(getDocumentPayload(nextDossier))],
        );
        const user = getPcnSessionUser(req);
        const log = buildActivityLog({
          action: 'UPDATED',
          entityType: 'PCN_DOSSIER',
          entityId: dossierId,
          entityLabel: dossier.dossierCode || dossierId,
          actorUsername: user?.username,
          actorName: user?.name || 'Người dùng PCN',
          actorRole: user?.systemRole || user?.role,
          summary: needsDownstreamReview
            ? `Xác nhận bản sinh ${generated.fileName.slice(0, 120)} và mở lại ${getPcnWorkflowStage(reopenStatus)?.title || 'bước bị ảnh hưởng'} để rà soát`
            : workflowRework.reopenedNodeId
              ? `Xác nhận bản sinh ${generated.fileName.slice(0, 120)} và mở lại node ${workflowRework.reopenedNodeId} theo vòng xử lý mới`
            : `Xác nhận bản sinh ${generated.fileName.slice(0, 120)} vào checklist ${requirement.name}`,
          source: 'USER_REVIEW',
          groupId: dossier.id,
          changes: diffActivityFields(dossier, nextDossier, ['updatedAt']),
          createdAt: now,
        });
        const validationError = validateActivityLogPayload(log);
        if (validationError) throw new Error(validationError);
        await client.query(
          `INSERT INTO app_documents (collection_name, document_id, data, updated_at)
           VALUES ('activityLogs', $1, $2::jsonb, CURRENT_TIMESTAMP)
           ON CONFLICT (collection_name, document_id) DO NOTHING`,
          [log.id, JSON.stringify(getDocumentPayload(log))],
        );
        return {
          document: persistedDocument,
          asset: {
            id: asset.id,
            bucketName: asset.bucket_name,
            objectPath: asset.object_path,
            sourceCollection: asset.source_collection,
            sourceDocumentId: asset.source_document_id,
            sourceJsonPath: asset.source_json_path,
            mimeType: asset.mime_type,
            byteSize: Number(asset.byte_size || 0),
            sha256: asset.sha256,
          },
          dossier: nextDossier,
          attachment: generatedAttachment,
          ...(nextApprovalSteps ? { approvalSteps: nextApprovalSteps } : {}),
          ...(workflowRework.workflowTasks ? { workflowTasks: workflowRework.workflowTasks } : {}),
          activityLog: log,
          idempotent: false as const,
        };
      });
      res.status(result.idempotent ? 200 : 201).json(result);
    } catch (error: any) {
      for (const uploaded of uploadedObjects.reverse()) {
        try {
          const storage = getPcnStorageClient();
          await storage.deleteObject(uploaded);
        } catch {
          // Keep the original confirmation error; cleanup is best effort.
        }
      }
      console.error('PCN generated document confirmation error:', error);
      const message = String(error?.message || error);
      const normalizedMessage = message.toLowerCase();
      const status = Number(error?.statusCode)
        || (normalizedMessage.includes('storage is not configured') ? 503
          : normalizedMessage.includes('không tìm thấy') ? 404
            : normalizedMessage.includes('không thuộc') || normalizedMessage.includes('không khớp') || normalizedMessage.includes('không hợp lệ') || normalizedMessage.includes('không thể xác nhận') || normalizedMessage.includes('ánh xạ') ? 400
              : 500);
      res.status(status).json({ error: message });
    }
  });

  app.post("/api/auth/kqtn-session", async (req, res) => {
    const inputUsername = String(req.body?.username || '').trim().toLowerCase();
    const username = inputUsername.replace(/^@/, '').split('@')[0];
    const password = String(req.body?.password || '').trim();
    if (!username || !password) {
      res.status(400).json({ error: "Thiếu tên đăng nhập hoặc mật khẩu." });
      return;
    }
    try {
      const result = await pool.query(
        `SELECT document_id, data FROM app_documents
         WHERE collection_name = 'systemUsers'
           AND (
             lower(document_id) = lower($1)
             OR split_part(lower(COALESCE(data->>'username', data->>'Tên đăng nhập', data->>'email', data->>'Email', '')), '@', 1) = lower($1)
           )
         LIMIT 1`,
        [username],
      );
      const userData = result.rows[0]?.data;
      if (!userData) {
        res.status(401).json({ error: "Tài khoản hoặc mật khẩu không chính xác." });
        return;
      }
      const storedPassword = String(userData.password || userData['Mật khẩu'] || '').trim();
      const preferenceKeys = Array.from(new Set([
        username,
        result.rows[0]?.document_id,
        userData.username,
        userData['Tên đăng nhập'],
        userData.email,
        userData['Email'],
      ].map(value => String(value || '').trim().toLowerCase().replace(/^@/, '').split('@')[0]).filter(Boolean)));
      const preferenceResult = await pool.query(
        `SELECT data FROM app_documents
         WHERE collection_name = 'userPreferences'
           AND lower(document_id) = ANY($1::text[])
         LIMIT 1`,
        [preferenceKeys],
      );
      const customPasswordValue = String(preferenceResult.rows[0]?.data?.customPassword || '').trim();
      const customPassword = customPasswordValue && customPasswordValue !== 'Abc123456'
        ? customPasswordValue
        : '';
      const passwordMatches = password === (customPassword || storedPassword || 'Abc123456') ||
        (password === 'Abc123456' && !storedPassword);
      if (!passwordMatches) {
        res.status(401).json({ error: "Tài khoản hoặc mật khẩu không chính xác." });
        return;
      }
      setKqtnSessionCookie(res, createKqtnSessionToken(username));
      res.json({ authenticated: true, username, role: normalizeSystemUserRole(userData) });
    } catch (error: any) {
      console.error("KQTN session login error:", error);
      res.status(500).json({ error: error?.message || String(error) });
    }
  });

  app.delete("/api/auth/kqtn-session", (_req, res) => {
    setKqtnSessionCookie(res, '', 0);
    res.status(204).end();
  });

  const apiKey = process.env.GEMINI_API_KEY || process.env.API_KEY;
  const getGeminiClient = async (req: express.Request, options: { timeout?: number; personalOnly?: boolean } = {}) => {
    const requestApiKey = options.personalOnly ? undefined : req.headers['x-gemini-api-key'];
    const personalApiKey = await getPcnStoredGeminiApiKey(req);
    const resolvedApiKey = options.personalOnly
      ? personalApiKey
      : resolveGeminiApiKey(
        apiKey,
        typeof requestApiKey === 'string' && requestApiKey.trim() ? requestApiKey : personalApiKey,
      );
    if (!resolvedApiKey) {
      throw new Error(GEMINI_API_KEY_MISSING_MESSAGE);
    }
    return new GoogleGenAI({
      apiKey: resolvedApiKey,
      httpOptions: {
        headers: {
          'User-Agent': 'aistudio-build',
        },
        ...(options.timeout !== undefined ? { timeout: options.timeout } : {}),
      }
    });
  };

  type ServerOcrCandidate = OcrCandidate & { source?: 'paddle' | 'text-layer'; pages?: ServerOcrCandidate[] };

  const requestPaddleOcr = async (
    fileBuffer: Buffer,
    fileName: string,
    mimeType: string,
    page: number,
  ): Promise<ServerOcrCandidate> => {
    const request = buildPcnPaddleOcrRequest(getKqtnOcrServiceUrl(), { fileName, mimeType, page, dpi: 150 });
    const formData = new FormData();
    formData.append('file', new Blob([new Uint8Array(fileBuffer)], { type: mimeType }), fileName);
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), KQTN_OCR_TIMEOUT_MS);
    try {
      const response = await fetch(request.url, { method: request.method, body: formData, signal: controller.signal });
      const payload = await response.json().catch(() => ({}));
      if (!response.ok) {
        throw Object.assign(new Error(payload.detail || payload.error || `PaddleOCR request failed (${response.status}).`), { statusCode: 503 });
      }
      const text = getPcnOcrText(payload).replace(/\u0000/g, '').trim();
      const confidenceValue = Number(payload.confidence ?? payload.score ?? payload.meanConfidence);
      return {
        text,
        confidence: Number.isFinite(confidenceValue) ? confidenceValue : text ? 0.82 : 0,
        source: 'paddle',
      };
    } finally {
      clearTimeout(timeout);
    }
  };

  const collectPaddleOcr = async (fileBuffer: Buffer, fileName: string, mimeType: string, pageNumber?: number): Promise<ServerOcrCandidate> => {
    const extension = fileName.toLowerCase().split('.').pop() || '';
    const isDocx = extension === 'docx' || mimeType.includes('wordprocessingml.document');
    if (isDocx) {
      const docxResult = await mammoth.extractRawText({ buffer: fileBuffer });
      if (docxResult.value.trim()) return { text: docxResult.value.trim(), confidence: 0.95, source: 'text-layer' };
      const embeddedImages = extractPcnDocxEmbeddedImages(fileBuffer);
      const pages: ServerOcrCandidate[] = [];
      for (const image of embeddedImages) pages.push(await requestPaddleOcr(image.bytes, image.fileName, image.mimeType, 1));
      return {
        text: pages.map((page) => page.text).filter(Boolean).join('\n\n'),
        confidence: pages.length > 0 ? pages.reduce((sum, page) => sum + page.confidence, 0) / pages.length : 0,
        source: 'paddle',
        pages,
      };
    }

    const isPdf = extension === 'pdf' || mimeType === 'application/pdf';
    if (!isPdf) return requestPaddleOcr(fileBuffer, fileName, mimeType || 'image/jpeg', 1);

    const pdf = await PDFDocument.load(fileBuffer, { ignoreEncryption: true });
    const firstPage = Math.max(1, Math.floor(Number(pageNumber) || 1));
    const lastPage = pageNumber ? firstPage : Math.min(pdf.getPageCount(), 40);
    const pages: ServerOcrCandidate[] = [];
    for (let page = firstPage; page <= lastPage; page += 1) pages.push(await requestPaddleOcr(fileBuffer, fileName, 'application/pdf', page));
    return {
      text: pages.map((page) => page.text).filter(Boolean).join('\n\n'),
      confidence: pages.length > 0 ? pages.reduce((sum, page) => sum + page.confidence, 0) / pages.length : 0,
      source: 'paddle',
      pages,
    };
  };

  const getPersonalGeminiClient = (req: express.Request, timeout = KQTN_OCR_TIMEOUT_MS) => getGeminiClient(req, { timeout, personalOnly: true });
  const getPersonalGeminiModel = (req: express.Request) => getPcnStoredGeminiModel(req);

  const getOcrErrorStatus = (error: any): number => {
    if (error?.message === GEMINI_API_KEY_MISSING_MESSAGE) return 503;
    if (Number(error?.statusCode) === 503 || error?.name === 'AbortError') return 503;
    return Number(error?.statusCode) || 500;
  };

  const approvalAssistantFields = new Set(['QC4', 'QC9']);
  const approvalAssistantDossierStatus = new Set(['TECHNICAL_REVIEW', 'WAITING_APPROVAL']);

  const readApprovalAssistantRows = async (collectionName: string, condition = '', params: unknown[] = []) => {
    const result = await pool.query(
      `SELECT document_id, data FROM app_documents WHERE collection_name = $1 ${condition} ORDER BY updated_at DESC, document_id ASC`,
      [collectionName, ...params],
    );
    return result.rows.map(mapDocumentRow);
  };

  const assertApprovalAssistantField = (value: unknown): PcnCertificationFieldCode => {
    const fieldCode = String(value || '').trim().toUpperCase();
    if (!approvalAssistantFields.has(fieldCode)) throw Object.assign(new Error('Trợ lý kiểm duyệt v1 chỉ hỗ trợ Lĩnh vực QC4 hoặc QC9.'), { statusCode: 400 });
    return fieldCode;
  };

  const normalizeApprovalAssistantRequirements = (rows: unknown[]): PcnDocumentRequirement[] => mergePcnDocumentRequirements(rows as PcnDocumentRequirement[]);

  const canUseApprovalAssistant = (req: express.Request, fieldCode: PcnCertificationFieldCode): boolean => {
    const actor = getPcnSessionUser(req);
    if (!actor) return false;
    const role = actor.systemRole || actor.role;
    return role === 'admin' || (Array.isArray(actor.fieldCodes) && actor.fieldCodes.map((code) => String(code).toUpperCase()).includes(fieldCode));
  };

  const loadApprovalAssistantInput = async (dossierId: string, fieldCode: PcnCertificationFieldCode): Promise<PcnApprovalReviewInput> => {
    const dossierResult = await pool.query(
      `SELECT document_id, data FROM app_documents
       WHERE collection_name = 'certificationDossiers' AND document_id = $1 LIMIT 1`,
      [dossierId],
    );
    const dossier = dossierResult.rows[0] ? mapDocumentRow(dossierResult.rows[0]) as CertificationDossier : undefined;
    if (!dossier) throw Object.assign(new Error('Không tìm thấy hồ sơ PCN.'), { statusCode: 404 });

    const lotIds = Array.isArray(dossier.sampleLotIds) ? dossier.sampleLotIds.map(String).filter(Boolean) : [];
    const [proposalResult, requirementsResult, documentsResult, requestsResult, lotsResult, itemsResult, routesResult, resultsResult] = await Promise.all([
      pool.query(`SELECT document_id, data FROM app_documents WHERE collection_name = 'certificationProposals' AND document_id = $1 LIMIT 1`, [dossier.proposalId]),
      pool.query(`SELECT document_id, data FROM app_documents WHERE collection_name = 'pcnDocumentRequirements' AND COALESCE((data->>'active')::boolean, false) = true ORDER BY COALESCE((data->>'sortOrder')::int, 0), document_id`),
      pool.query(`SELECT document_id, data FROM app_documents WHERE collection_name = 'dossierDocuments' AND data->>'dossierId' = $1 ORDER BY document_id`, [dossier.id]),
      pool.query(`SELECT document_id, data FROM app_documents WHERE collection_name = 'labRequests' AND data->>'dossierId' = $1 ORDER BY document_id`, [dossier.id]),
      pool.query(`SELECT document_id, data FROM app_documents WHERE collection_name = 'pcnSampleLots' AND data->>'dossierId' = $1 ORDER BY document_id`, [dossier.id]),
      pool.query(`SELECT document_id, data FROM app_documents WHERE collection_name = 'pcnSampleItems' AND data->>'sampleLotId' = ANY($1::text[]) ORDER BY document_id`, [lotIds]),
      pool.query(`SELECT document_id, data FROM app_documents WHERE collection_name = 'pcnSampleRoutes' AND data->>'sampleLotId' = ANY($1::text[]) ORDER BY document_id`, [lotIds]),
      pool.query(`SELECT document_id, data FROM app_documents WHERE collection_name = 'returnedResults' AND data->>'dossierId' = $1 ORDER BY document_id`, [dossier.id]),
    ]);

    return {
      fieldCode,
      dossier,
      ...(proposalResult.rows[0] ? { proposal: mapDocumentRow(proposalResult.rows[0]) as CertificationProposal } : {}),
      requirements: normalizeApprovalAssistantRequirements(requirementsResult.rows.map(mapDocumentRow)),
      documents: documentsResult.rows.map(mapDocumentRow) as PcnDossierDocument[],
      labRequests: requestsResult.rows.map(mapDocumentRow) as OutboundLabRequest[],
      sampleLots: lotsResult.rows.map(mapDocumentRow) as PcnSampleLot[],
      sampleItems: itemsResult.rows.map(mapDocumentRow) as PcnSampleItem[],
      sampleRoutes: routesResult.rows.map(mapDocumentRow) as PcnSampleRoute[],
      returnedResults: resultsResult.rows.map(mapDocumentRow) as ReturnedTestResult[],
    };
  };

  type ApprovalAssistantAssetReference = {
    assetId: string;
    fileName: string;
    sourceCollection: 'dossierDocuments' | 'returnedResults';
    sourceDocumentId: string;
    sourceJsonPath: string;
    tab: PcnApprovalReviewEvidence['tab'];
  };

  const getCurrentApprovalAssistantAssets = (input: PcnApprovalReviewInput): ApprovalAssistantAssetReference[] => {
    const references: ApprovalAssistantAssetReference[] = [];
    for (const document of input.documents) {
      if (document.status !== 'PRESENT') continue;
      const versions = Array.isArray(document.versions) ? document.versions : [];
      const current = versions.find((version) => version.assetId === document.currentVersionId) || versions.at(-1);
      if (current?.assetId) references.push({
        assetId: current.assetId,
        fileName: current.fileName || `${current.assetId}.bin`,
        sourceCollection: 'dossierDocuments',
        sourceDocumentId: document.id,
        sourceJsonPath: document.requirementId,
        tab: 'documents',
      });
    }
    for (const result of input.returnedResults) {
      if (result.fileAssetId) references.push({
        assetId: result.fileAssetId,
        fileName: result.reportNumber ? `${result.reportNumber}.pdf` : `${result.fileAssetId}.pdf`,
        sourceCollection: 'returnedResults',
        sourceDocumentId: result.id,
        sourceJsonPath: 'fileAssetId',
        tab: 'results',
      });
    }
    return [...new Map(references.map((reference) => [reference.assetId, reference])).values()];
  };

  const fetchApprovalAssistantPaddlePage = async (reference: ApprovalAssistantAssetReference, bytes: Buffer, mimeType: string, page: number): Promise<PcnApprovalReviewTextEvidence> => {
    const request = buildPcnPaddleOcrRequest(getKqtnOcrServiceUrl(), { fileName: reference.fileName, mimeType, page, dpi: 150 });
    const formData = new FormData();
    formData.append('file', new Blob([new Uint8Array(bytes)], { type: mimeType }), reference.fileName);
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), KQTN_OCR_TIMEOUT_MS);
    try {
      const response = await fetch(request.url, { method: request.method, body: formData, signal: controller.signal });
      const payload = await response.json().catch(() => ({}));
      if (!response.ok) throw new PcnPaddleOcrUnavailableError('PADDLE_OCR_UNAVAILABLE', `PaddleOCR không sẵn sàng cho ${reference.fileName}, trang ${page} (HTTP ${response.status}).`);
      const normalized = normalizePcnPaddleOcrPage(payload, { assetId: reference.assetId, fileName: reference.fileName, page });
      return { ...normalized, tab: reference.tab };
    } catch (error: any) {
      if (error instanceof PcnPaddleOcrUnavailableError) throw error;
      throw new PcnPaddleOcrUnavailableError('PADDLE_OCR_UNAVAILABLE', `Dừng phiên trợ lý AI: không thể đọc ${reference.fileName}, trang ${page} bằng PaddleOCR.`);
    } finally {
      clearTimeout(timeout);
    }
  };

  const fetchApprovalAssistantGeminiPage = async (req: express.Request, reference: ApprovalAssistantAssetReference, bytes: Buffer, mimeType: string, page: number): Promise<PcnApprovalReviewTextEvidence> => {
    const ai = await getPersonalGeminiClient(req);
    const response = await generateContentWithRetryAndFallback(ai, {
      contents: {
        parts: [
          { inlineData: { mimeType: mimeType || 'application/pdf', data: bytes.toString('base64') } },
          { text: `Đọc riêng trang ${page} của tài liệu ${reference.fileName}. Chỉ chép lại chữ nhìn thấy, không suy đoán. Trả JSON có trường text chứa toàn bộ nội dung đọc được theo dòng.` },
        ],
      },
      config: { responseMimeType: 'application/json', responseSchema: { type: Type.OBJECT, properties: { text: { type: Type.STRING } } } },
    }, await getPersonalGeminiModel(req));
    const raw = String(response.text || '').replace(/```json|```/g, '').trim();
    const text = String(JSON.parse(raw)?.text || '').replace(/\u0000/g, '').trim();
    if (!text) throw Object.assign(new Error(`Gemini không đọc được ${reference.fileName}, trang ${page}.`), { statusCode: 422 });
    return { assetId: reference.assetId, fileName: reference.fileName, text, page, confidence: 0.78, tab: reference.tab };
  };

  const fetchApprovalAssistantOcrPage = async (req: express.Request, reference: ApprovalAssistantAssetReference, bytes: Buffer, mimeType: string, page: number): Promise<PcnApprovalReviewTextEvidence> => {
    try {
      return await fetchApprovalAssistantPaddlePage(reference, bytes, mimeType, page);
    } catch (error) {
      if (!(error instanceof PcnPaddleOcrUnavailableError)) throw error;
      return fetchApprovalAssistantGeminiPage(req, reference, bytes, mimeType, page);
    }
  };

  const extractApprovalAssistantTexts = async (req: express.Request, input: PcnApprovalReviewInput): Promise<{ documentTexts: PcnApprovalReviewTextEvidence[]; unreadableFiles: PcnApprovalReviewUnreadableFile[] }> => {
    const references = getCurrentApprovalAssistantAssets(input);
    if (references.length === 0) return { documentTexts: [], unreadableFiles: [] };
    const assetResult = await pool.query(
      `SELECT id, bucket_name, object_path, source_collection, source_document_id, source_json_path, mime_type
       FROM file_assets WHERE id = ANY($1::text[])`,
      [references.map((reference) => reference.assetId)],
    );
    const assetById = new Map(assetResult.rows.map((asset: any) => [String(asset.id), asset]));
    const storage = getPcnStorageClient();
    const evidence: PcnApprovalReviewTextEvidence[] = [];
    const unreadableFiles: PcnApprovalReviewUnreadableFile[] = [];
    for (const reference of references) {
      const asset = assetById.get(reference.assetId);
      if (!asset) throw new PcnPaddleOcrUnavailableError('PADDLE_OCR_UNAVAILABLE', `Không tìm thấy private asset ${reference.assetId} để đọc hồ sơ.`);
      if (String(asset.bucket_name) !== getPcnStorageBucket()
        || String(asset.source_collection) !== reference.sourceCollection
        || String(asset.source_document_id) !== reference.sourceDocumentId
        || String(asset.source_json_path) !== reference.sourceJsonPath) {
        throw new PcnPaddleOcrUnavailableError('PADDLE_OCR_UNAVAILABLE', `Private asset ${reference.assetId} không trỏ đúng về hồ sơ đang kiểm duyệt.`);
      }
      const downloaded = await storage.downloadObject({ bucketName: String(asset.bucket_name), objectPath: String(asset.object_path) });
      const mimeType = String(asset.mime_type || downloaded.contentType || 'application/octet-stream').toLowerCase();
      const extension = reference.fileName.toLowerCase().split('.').pop() || '';
      const isDocx = extension === 'docx' || mimeType.includes('wordprocessingml.document');
      const isPdf = extension === 'pdf' || mimeType.includes('pdf');
      const isImage = mimeType.startsWith('image/') || /^(png|jpe?g|webp|tiff?)$/.test(extension);
      if (isDocx) {
        const docxResult = await mammoth.extractRawText({ buffer: downloaded.body });
        const text = String(docxResult.value || '').trim();
        if (text) {
          evidence.push({ assetId: reference.assetId, fileName: reference.fileName, text, confidence: 0.95, tab: reference.tab });
          continue;
        }
        const embeddedImages = extractPcnDocxEmbeddedImages(downloaded.body);
        if (embeddedImages.length === 0) {
          evidence.push(await fetchApprovalAssistantOcrPage(req, reference, downloaded.body, mimeType, 1));
          continue;
        }
        const evidenceBeforeDocx = evidence.length;
        for (const [index, image] of embeddedImages.entries()) {
          const imageReference = { ...reference, fileName: `${reference.fileName} · ${image.fileName}` };
          try {
            evidence.push(await fetchApprovalAssistantOcrPage(req, imageReference, image.bytes, image.mimeType, index + 1));
          } catch (error) {
            if (error instanceof PcnPaddleOcrUnavailableError && (error.code === 'PADDLE_OCR_EMPTY' || error.code === 'PADDLE_OCR_LOW_CONFIDENCE')) continue;
            throw error;
          }
        }
        if (evidence.length === evidenceBeforeDocx) throw new PcnPaddleOcrUnavailableError('PADDLE_OCR_EMPTY', `PaddleOCR và Gemini không đọc được ảnh nhúng trong ${reference.fileName}.`);
        continue;
      }
      if (isPdf) {
        let pdf: PDFDocument;
        try { pdf = await PDFDocument.load(downloaded.body, { ignoreEncryption: true }); } catch {
          throw new PcnPaddleOcrUnavailableError('PADDLE_OCR_UNAVAILABLE', `Không mở được PDF ${reference.fileName} để chạy PaddleOCR.`);
        }
        const pageCount = pdf.getPageCount();
        if (pageCount < 1) throw new PcnPaddleOcrUnavailableError('PADDLE_OCR_EMPTY', `PDF ${reference.fileName} không có trang để đọc.`);
        for (let page = 1; page <= pageCount; page += 1) evidence.push(await fetchApprovalAssistantOcrPage(req, reference, downloaded.body, 'application/pdf', page));
        continue;
      }
      if (isImage) {
        evidence.push(await fetchApprovalAssistantOcrPage(req, reference, downloaded.body, mimeType, 1));
        continue;
      }
      if (extension === 'doc' || mimeType.includes('application/msword')) {
        unreadableFiles.push({
          assetId: reference.assetId,
          fileName: reference.fileName,
          reason: 'Định dạng Word cũ .doc chưa có bộ chuyển đổi an toàn trong phiên này.',
          tab: reference.tab,
        });
        continue;
      }
      throw new PcnPaddleOcrUnavailableError('PADDLE_OCR_UNAVAILABLE', `Định dạng ${reference.fileName} chưa được hỗ trợ trong phiên kiểm duyệt.`);
    }
    return { documentTexts: evidence, unreadableFiles };
  };

  const semanticReviewCriterion = async (req: express.Request, criterion: PcnApprovalCriterionResult, texts: PcnApprovalReviewTextEvidence[]): Promise<PcnApprovalCriterionResult> => {
    if (texts.length === 0 || ['ENTRY_GATE', 'COMPLETENESS', 'SAMPLE_PYC', 'LAB_RESULTS'].includes(criterion.id)) return criterion;
    try {
      const ai = await getPersonalGeminiClient(req, 30000);
      const context = texts.map((entry) => `[${entry.assetId}|${entry.fileName}${entry.page ? `|trang ${entry.page}` : ''}]\n${entry.text.slice(0, 6000)}`).join('\n\n').slice(0, 24000);
      const response = await generateContentWithRetryAndFallback(ai, {
        contents: [{ role: 'user', parts: [{ text: `Bạn là lớp phân tích ngữ nghĩa hỗ trợ kiểm duyệt hồ sơ PCN. Chỉ kiểm tra tiêu chí "${criterion.title}" từ các trích đoạn có mã bằng chứng bên dưới. Không quyết định phê duyệt, không đề xuất chuyển trạng thái, không bịa thông tin. Chỉ trả JSON: {"hasIssue": boolean, "severity": "ATTENTION" hoặc "CRITICAL", "message": string, "assetIds": string[]}. Nếu không đủ căn cứ, hasIssue=false. assetIds chỉ được chọn từ mã đã cung cấp.\n\n${context}` }] }],
        config: { responseMimeType: 'application/json', temperature: 0.1 },
      }, await getPersonalGeminiModel(req), { attemptsPerModel: 1 });
      const parsed = JSON.parse(String(response.text || '{}').replace(/```json|```/g, '').trim()) as Record<string, unknown>;
      if (parsed.hasIssue !== true || typeof parsed.message !== 'string') return criterion;
      const assetIds = Array.isArray(parsed.assetIds) ? parsed.assetIds.map(String) : [];
      const selected = texts.filter((entry) => assetIds.includes(entry.assetId));
      if (selected.length === 0) return criterion;
      const severity = parsed.severity === 'CRITICAL' ? 'CRITICAL' : 'ATTENTION';
      const finding: PcnApprovalReviewFinding = {
        id: `${criterion.id}:AI_SEMANTIC_REVIEW`,
        code: 'AI_SEMANTIC_REVIEW',
        message: String(parsed.message).slice(0, 1000),
        severity,
        confidence: 0.7,
        suggestedAction: 'Mở bằng chứng được nêu và đối chiếu với hồ sơ gốc.',
        evidence: selected.slice(0, 6).map((entry) => ({ assetId: entry.assetId, fileName: entry.fileName, ...(entry.page ? { page: entry.page } : {}), excerpt: entry.text.slice(0, 300), tab: 'documents' })),
      };
      criterion.findings = [...criterion.findings, finding];
      criterion.source = criterion.findings.length > 1 ? 'RULE_AND_AI' : 'AI';
      if (severity === 'CRITICAL' || criterion.status === 'PASS') {
        criterion.status = severity === 'CRITICAL' ? 'ERROR' : 'WARNING';
        criterion.severity = severity;
        criterion.summary = 'Lớp ngữ nghĩa AI phát hiện điểm cần người dùng đối chiếu với bằng chứng.';
      }
      return criterion;
    } catch {
      return criterion;
    }
  };

  const pruneApprovalAssistantRuns = () => {
    const now = Date.now();
    for (const [runId, run] of pcnApprovalReviewRuns) if (run.expiresAt <= now) pcnApprovalReviewRuns.delete(runId);
  };

  app.get('/api/pcn/approval-assistant/candidates', async (req, res) => {
    if (DATABASE_PROFILE !== 'pcn') { res.status(404).json({ error: 'Trợ lý kiểm duyệt PCN chỉ khả dụng trong profile PCN.' }); return; }
    if (!requirePcnSession(req, res)) return;
    try {
      const fieldCode = assertApprovalAssistantField(req.query.fieldCode);
      if (!canUseApprovalAssistant(req, fieldCode)) { res.status(403).json({ error: 'Tài khoản chưa được cấp quyền xem Lĩnh vực này.' }); return; }
      const [dossiers, proposals, requirements, documents] = await Promise.all([
        readApprovalAssistantRows('certificationDossiers'),
        readApprovalAssistantRows('certificationProposals'),
        readApprovalAssistantRows('pcnDocumentRequirements', `AND COALESCE((data->>'active')::boolean, false) = true`),
        readApprovalAssistantRows('dossierDocuments'),
      ]);
        res.json({ items: getPcnApprovalReviewCandidates({ fieldCode, dossiers: dossiers as CertificationDossier[], proposals: proposals as CertificationProposal[], requirements: normalizeApprovalAssistantRequirements(requirements), documents: documents as PcnDossierDocument[] }) });
    } catch (error: any) {
      const status = Number(error?.statusCode) || 500;
      res.status(status).json({ error: String(error?.message || error) });
    }
  });

  app.post('/api/pcn/approval-assistant/review', async (req, res) => {
    if (DATABASE_PROFILE !== 'pcn') { res.status(404).json({ error: 'Trợ lý kiểm duyệt PCN chỉ khả dụng trong profile PCN.' }); return; }
    if (!requirePcnSession(req, res)) return;
    let fieldCode: PcnCertificationFieldCode;
    try { fieldCode = assertApprovalAssistantField(req.body?.fieldCode); } catch (error: any) { res.status(Number(error?.statusCode) || 400).json({ error: String(error?.message || error) }); return; }
    const dossierId = String(req.body?.dossierId || '').trim();
    if (!dossierId || dossierId.length > 240 || /[\\/]/.test(dossierId)) { res.status(400).json({ error: 'Mã hồ sơ PCN không hợp lệ.' }); return; }
    if (!canUseApprovalAssistant(req, fieldCode)) { res.status(403).json({ error: 'Tài khoản chưa được cấp quyền xem Lĩnh vực này.' }); return; }
    try {
      const input = await loadApprovalAssistantInput(dossierId, fieldCode);
      if (input.dossier.historicalImport || !input.dossier.fieldCodes.includes(fieldCode) || !approvalAssistantDossierStatus.has(input.dossier.status)) { res.status(409).json({ error: 'Hồ sơ không thuộc danh sách đang cần trợ lý kiểm duyệt.' }); return; }
      const actor = getPcnSessionUser(req)!;
      const runId = randomUUID();
      const startedAt = new Date().toISOString();
      res.statusCode = 200;
      res.setHeader('Content-Type', 'application/x-ndjson; charset=utf-8');
      res.setHeader('Cache-Control', 'no-cache, no-transform');
      res.setHeader('Connection', 'keep-alive');
      res.flushHeaders?.();
      const writeEvent = (event: Record<string, unknown>) => { if (!res.writableEnded) res.write(`${JSON.stringify(event)}\n`); };
      writeEvent({ type: 'run_started', runId, dossierId, fieldCode, startedAt, message: 'Đã mở phiên đọc hồ sơ. Kết quả sẽ hiện lần lượt theo tiêu chí.' });
      const extracted = await extractApprovalAssistantTexts(req, input);
      const { documentTexts } = extracted;
      const baseReport = buildPcnApprovalReview({ ...input, documentTexts, unreadableFiles: extracted.unreadableFiles });
      const criteria: PcnApprovalCriterionResult[] = [];
      for (let index = 0; index < PCN_APPROVAL_REVIEW_CRITERIA.length; index += 1) {
        const criterion = baseReport.criteria[index];
        writeEvent({ type: 'criterion_started', index, total: baseReport.criteria.length, criterion: { id: criterion.id, title: criterion.title } });
        const reviewed = await semanticReviewCriterion(req, criterion, documentTexts);
        criteria.push(reviewed);
        writeEvent({ type: 'criterion_result', index, total: baseReport.criteria.length, criterion: reviewed });
        writeEvent({ type: 'criterion_completed', index, total: baseReport.criteria.length, criterionId: reviewed.id });
      }
      const summary = {
        pass: criteria.filter((criterion) => criterion.status === 'PASS').length,
        warning: criteria.filter((criterion) => criterion.status === 'WARNING').length,
        error: criteria.filter((criterion) => criterion.status === 'ERROR').length,
        notEvaluable: criteria.filter((criterion) => criterion.status === 'NOT_EVALUABLE').length,
        highestSeverity: criteria.some((criterion) => criterion.severity === 'CRITICAL') ? 'CRITICAL' : criteria.some((criterion) => criterion.severity === 'ATTENTION') ? 'ATTENTION' : 'INFO',
        conclusion: criteria.some((criterion) => criterion.status === 'NOT_EVALUABLE') ? 'CHƯA ĐỦ CĂN CỨ' : criteria.some((criterion) => criterion.status === 'ERROR' || criterion.status === 'WARNING') ? 'CẦN KIỂM TRA/BỔ SUNG' : 'KHÔNG PHÁT HIỆN BẤT THƯỜNG RÕ',
      } as ReturnType<typeof buildPcnApprovalReview>['summary'];
      const report = { criteria, summary };
      pcnApprovalReviewRuns.set(runId, { runId, username: actor.username, dossierId, dossierCode: input.dossier.dossierCode, fieldCode, report, expiresAt: Date.now() + PCN_APPROVAL_REVIEW_TTL_MS });
      pruneApprovalAssistantRuns();
      writeEvent({ type: 'run_completed', runId, finishedAt: new Date().toISOString(), summary, exportToken: runId, message: 'Đã hoàn tất phiên hỗ trợ. Kết quả không làm thay đổi hồ sơ.' });
      res.end();
    } catch (error: any) {
      const missingKey = error?.message === GEMINI_API_KEY_MISSING_MESSAGE;
      const message = missingKey
        ? GEMINI_API_KEY_MISSING_MESSAGE
        : error instanceof PcnPaddleOcrUnavailableError ? `Dừng phiên AI: ${error.message}` : String(error?.message || error);
      const status = missingKey || error instanceof PcnPaddleOcrUnavailableError ? 503 : Number(error?.statusCode) || 500;
      const code = missingKey ? 'GEMINI_API_KEY_MISSING' : error?.code || 'PCN_APPROVAL_ASSISTANT_FAILED';
      if (res.headersSent) { if (!res.writableEnded) { res.write(`${JSON.stringify({ type: 'run_error', code, message })}\n`); res.end(); } } else res.status(status).json({ code, error: message });
    }
  });

  app.post('/api/pcn/approval-assistant/export', async (req, res) => {
    if (DATABASE_PROFILE !== 'pcn') { res.status(404).json({ error: 'Trợ lý kiểm duyệt PCN chỉ khả dụng trong profile PCN.' }); return; }
    if (!requirePcnSession(req, res)) return;
    try {
      pruneApprovalAssistantRuns();
      const runId = String(req.body?.runId || req.body?.exportToken || '').trim();
      const format = String(req.body?.format || '').trim().toUpperCase();
      const run = pcnApprovalReviewRuns.get(runId);
      if (!run || run.expiresAt <= Date.now()) { res.status(404).json({ error: 'Phiên hỗ trợ đã hết hạn, hãy chạy lại hồ sơ.' }); return; }
      const actor = getPcnSessionUser(req)!;
      if (run.username.toLowerCase() !== actor.username.toLowerCase()) { res.status(403).json({ error: 'Bạn không có quyền tải báo cáo của phiên này.' }); return; }
      const dossierCode = run.dossierCode;
      const report = { dossierCode, fieldCode: run.fieldCode, generatedAt: new Date().toISOString(), ...run.report };
      if (format === 'DOCX') {
        const body = buildPcnApprovalReviewDocx(report);
        res.setHeader('Content-Type', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document');
        res.setHeader('Content-Disposition', buildPcnFileContentDisposition(`bao-cao-ho-tro-${dossierCode}.docx`, 'attachment'));
        res.send(body);
        return;
      }
      if (format === 'PDF') {
        const body = await buildPcnApprovalReviewPdf(report);
        res.setHeader('Content-Type', 'application/pdf');
        res.setHeader('Content-Disposition', buildPcnFileContentDisposition(`bao-cao-ho-tro-${dossierCode}.pdf`, 'attachment'));
        res.send(body);
        return;
      }
      res.status(400).json({ error: 'Định dạng báo cáo chỉ hỗ trợ PDF hoặc DOCX.' });
    } catch (error: any) {
      res.status(Number(error?.statusCode) || 500).json({ error: String(error?.message || error) });
    }
  });

  app.post('/api/pcn/ocr', async (req, res) => {
    if (DATABASE_PROFILE !== 'pcn') {
      res.status(404).json({ error: 'OCR PCN chỉ khả dụng trong profile PCN.' });
      return;
    }
    if (!requirePcnSession(req, res)) return;
    const context = req.body?.context === 'result' ? 'result' : req.body?.context === 'proposal' ? 'proposal' : '';
    const fileName = String(req.body?.fileName || '').trim().slice(0, 255);
    const mimeType = String(req.body?.mimeType || 'application/octet-stream').toLowerCase().trim();
    const base64Data = String(req.body?.base64Data || '').replace(/^data:[^;]+;base64,/i, '');
    if (!context || !fileName || !base64Data || !isPcnOcrFileSupported(mimeType, fileName)) {
      res.status(400).json({ error: 'OCR PCN cần context, tên file và file PDF/DOCX/PNG/JPG/JPEG hợp lệ.' });
      return;
    }
    const fileBuffer = Buffer.from(base64Data, 'base64');
    if (fileBuffer.length === 0 || fileBuffer.length > 25 * 1024 * 1024) {
      res.status(413).json({ error: 'File OCR PCN phải lớn hơn 0 và không quá 25 MB.' });
      return;
    }
    try {
      const settingsResult = await pool.query(
        `SELECT document_id, data FROM app_documents
         WHERE collection_name = 'systemConfig' AND document_id = $1
         LIMIT 1`,
        ['pcn-settings'],
      );
      const settings = normalizePcnSettings(settingsResult.rows[0] ? mapDocumentRow(settingsResult.rows[0]) : {});
      if (!settings.ocr.enabled || settings.ocr.provider === 'DISABLED') {
        res.status(409).json({ error: 'OCR PCN đang được tắt trong Cài đặt PCN.' });
        return;
      }

      const sourcePage = Math.max(1, Math.floor(Number(req.body?.pageNumber) || 1));
      const ocrResult = await runPaddleFirstWithGeminiFallback<ServerOcrCandidate>({
        confidenceThreshold: settings.ocr.confidenceThreshold,
        paddle: () => collectPaddleOcr(fileBuffer, fileName, mimeType, req.body?.pageNumber ? sourcePage : undefined),
        gemini: async () => {
          const ai = await getPersonalGeminiClient(req);
          const prompt = context === 'proposal'
            ? 'Đọc tài liệu Đề nghị chứng nhận PCN. Chỉ chép lại chữ nhìn thấy, không suy đoán. Trả JSON có trường text chứa toàn bộ nội dung đọc được theo dòng.'
            : 'Đọc báo cáo KQTN của PCN. Chỉ chép lại chữ nhìn thấy, không suy đoán. Trả JSON có trường text chứa toàn bộ nội dung đọc được theo dòng.';
          const response = await generateContentWithRetryAndFallback(ai, {
            contents: { parts: [{ inlineData: { mimeType: mimeType === 'application/octet-stream' ? 'application/pdf' : mimeType, data: base64Data } }, { text: prompt }] },
            config: { responseMimeType: 'application/json', responseSchema: { type: Type.OBJECT, properties: { text: { type: Type.STRING } } } },
          }, await getPersonalGeminiModel(req));
          const raw = String(response.text || '').replace(/```json|```/g, '').trim();
          return { text: String(JSON.parse(raw)?.text || ''), confidence: 0.78 };
        },
        isUsable: (candidate, threshold) => isUsableOcrCandidate(candidate, threshold),
      });
      const extractedText = ocrResult.value.text;
      const confidence = ocrResult.value.confidence;
      if (!extractedText.trim()) throw Object.assign(new Error('OCR không nhận diện được nội dung rõ ràng.'), { statusCode: 422 });
      res.json({ provider: ocrResult.provider, draft: buildPcnOcrDraftFromText(extractedText, context, fileName, sourcePage, confidence) });
    } catch (error: any) {
      console.error('PCN OCR error:', error?.message || String(error));
      const statusCode = getOcrErrorStatus(error);
      const missingKey = error?.message === GEMINI_API_KEY_MISSING_MESSAGE;
      res.status(statusCode).json({ code: missingKey ? 'GEMINI_API_KEY_MISSING' : statusCode === 503 ? 'PCN_OCR_UNAVAILABLE' : 'PCN_OCR_FAILED', error: missingKey ? GEMINI_API_KEY_MISSING_MESSAGE : statusCode === 503 ? 'Dịch vụ OCR PCN hiện không sẵn sàng.' : String(error?.message || error) });
    }
  });

  const proxyKqtnOcr = async (req: express.Request, res: express.Response, mode: "footer" | "page") => {
    const base64Data = String(req.body?.base64Data || "").replace(/^data:application\/pdf;base64,/i, "");
    const sourcePage = Math.max(1, Math.floor(Number(req.body?.pageNumber) || 1));
    if (!base64Data) {
      res.status(400).json({ error: "Missing PDF data." });
      return;
    }

    const ocrServiceUrl = getKqtnOcrServiceUrl();

    const pdfBuffer = Buffer.from(base64Data, "base64");
    if (pdfBuffer.length === 0 || pdfBuffer.subarray(0, 5).toString("ascii") !== "%PDF-") {
      res.status(415).json({ error: "Only valid PDF data is accepted." });
      return;
    }

    const ocrUrl = new URL(`${ocrServiceUrl}/ocr/pdf/${mode}`);
    ocrUrl.searchParams.set("page", "1");
    // Bulk identity OCR only needs the footer band or the first-page fields;
    // keep the rendered payload light enough for Docker Desktop/Cloudflare.
    ocrUrl.searchParams.set("dpi", mode === "footer" ? "120" : "150");
    if (mode === "footer") ocrUrl.searchParams.set("footer_ratio", "0.2");

    const formData = new FormData();
    formData.append("file", new Blob([new Uint8Array(pdfBuffer)], { type: "application/pdf" }), `kqtn-page-${sourcePage}.pdf`);
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), KQTN_OCR_TIMEOUT_MS);
    console.log(`KQTN PaddleOCR ${mode} request: sourcePage=${sourcePage}, payloadBytes=${pdfBuffer.length}`);

    try {
      const response = await fetch(ocrUrl, {
        method: "POST",
        body: formData,
        signal: controller.signal,
      });
      const payload = await response.json().catch(() => ({}));
      if (!response.ok) {
        res.status(response.status >= 500 ? 503 : response.status).json({
          code: "KQTN_OCR_UNAVAILABLE",
          error: payload.detail || payload.error || `PaddleOCR request failed (${response.status}).`,
        });
        return;
      }
      res.json({ ...payload, sourcePage, mode });
    } catch (error: any) {
      console.error(`KQTN PaddleOCR ${mode} error:`, error?.message || String(error));
      res.status(503).json({
        code: "KQTN_OCR_UNAVAILABLE",
        error: error?.name === "AbortError" ? "PaddleOCR request timed out." : "PaddleOCR service unavailable.",
      });
    } finally {
      clearTimeout(timeout);
    }
  };

  app.post("/api/kqtn/ocr/footer", (req, res) => proxyKqtnOcr(req, res, "footer"));
  app.post("/api/kqtn/ocr/page", (req, res) => proxyKqtnOcr(req, res, "page"));

  const expireKqtnFooterJob = (jobId: string) => {
    setTimeout(() => {
      kqtnFooterJobs.delete(jobId);
    }, KQTN_FOOTER_JOB_TTL_MS);
  };

  const runKqtnFooterJob = async (jobId: string, sourceBytes: Buffer) => {
    const job = kqtnFooterJobs.get(jobId);
    if (!job) return;

    job.status = "running";
    let sourceBuffer = sourceBytes;
    let footerWindows: KqtnFooterPdfWindow[] = [];
    let controller: AbortController | undefined;
    let timeout: ReturnType<typeof setTimeout> | undefined;
    try {
      const ocrServiceUrl = getKqtnOcrServiceUrl();

      const ocrUrl = new URL(ocrServiceUrl + "/ocr/pdf/footer-fast");
      ocrUrl.searchParams.set("thumbnail_dpi", "90");
      ocrUrl.searchParams.set("ocr_dpi", "150");
      ocrUrl.searchParams.set("chunk_size", "8");
      ocrUrl.searchParams.set("max_candidates", "32");
      footerWindows = await createKqtnFooterOnlyPdfWindows(sourceBuffer);
      if (footerWindows.length === 0) throw new Error("Không tạo được cửa sổ footer từ PDF nguồn.");
      controller = new AbortController();
      timeout = setTimeout(() => controller?.abort(), KQTN_FOOTER_JOB_TIMEOUT_MS);

      console.log("KQTN footer job running: jobId=" + jobId + ", payloadBytes=" + sourceBuffer.length + ", windows=" + footerWindows.length);
      job.strategy = "footer-batch";
      const pagesByNumber = new Map<number, KqtnFooterJobPage>();
      let processingSeconds = 0;
      for (const footerWindow of footerWindows) {
        const windowUrl = new URL(ocrUrl);
        const formData = new FormData();
        formData.append("file", new Blob([new Uint8Array(footerWindow.bytes)], { type: "application/pdf" }), `kqtn-combined-footer-${footerWindow.startPage}-${footerWindow.endPage}.pdf`);
        const response = await fetch(windowUrl, {
          method: "POST",
          body: formData,
          signal: controller.signal,
        });
        const payload = await response.json().catch(() => ({}));
        if (!response.ok) {
          throw new Error(payload.detail || payload.error || "PaddleOCR footer scan failed (" + response.status + ").");
        }
        processingSeconds += Number(payload.processing_time_s || 0);
        const rawPages = Array.isArray(payload.pages) ? payload.pages : [];
        for (const [index, page] of rawPages.entries()) {
          const localPageNumber = Math.max(1, Math.floor(Number(page?.page) || index + 1));
          const pageNumber = footerWindow.startPage + localPageNumber - 1;
          if (pageNumber > footerWindow.endPage) continue;
          const candidatePage = parseKqtnFooterJobPage(page, pageNumber);
          const existing = pagesByNumber.get(pageNumber);
          if (!existing || (candidatePage.footerKey && !existing.footerKey) || candidatePage.confidence > Number(existing.confidence || 0)) {
            pagesByNumber.set(pageNumber, candidatePage);
          }
        }
        job.processedPages = Math.min(job.totalPages || footerWindows.at(-1)?.endPage || footerWindow.endPage, footerWindow.endPage);
        job.pages = [...pagesByNumber.values()].sort((left, right) => left.pageNumber - right.pageNumber);
        console.log("KQTN footer window completed: jobId=" + jobId + ", range=" + footerWindow.startPage + "-" + footerWindow.endPage + ", candidates=" + rawPages.length);
      }
      job.totalPages = Math.max(job.totalPages, footerWindows.at(-1)?.endPage || 0);
      const boundaryProbePages = getKqtnFooterBoundaryProbePages([...pagesByNumber.values()], job.totalPages);
      if (boundaryProbePages.length > 0) {
        const boundaryProbeBytes = await createKqtnFooterOnlyPdfPages(sourceBuffer, boundaryProbePages);
        const boundaryUrl = new URL(ocrServiceUrl + "/ocr/pdf/footer-batch");
        boundaryUrl.searchParams.set("dpi", "150");
        boundaryUrl.searchParams.set("chunk_size", "4");
        const boundaryFormData = new FormData();
        boundaryFormData.append(
          "file",
          new Blob([new Uint8Array(boundaryProbeBytes)], { type: "application/pdf" }),
          "kqtn-combined-footer-boundary-probe.pdf",
        );
        const boundaryResponse = await fetch(boundaryUrl, {
          method: "POST",
          body: boundaryFormData,
          signal: controller.signal,
        });
        const boundaryPayload = await boundaryResponse.json().catch(() => ({}));
        if (!boundaryResponse.ok) {
          throw new Error(boundaryPayload.detail || boundaryPayload.error || "PaddleOCR footer boundary probe failed (" + boundaryResponse.status + ").");
        }
        processingSeconds += Number(boundaryPayload.processing_time_s || 0);
        const boundaryPages = Array.isArray(boundaryPayload.pages) ? boundaryPayload.pages : [];
        for (const [index, page] of boundaryPages.entries()) {
          const pageNumber = boundaryProbePages[index];
          if (!pageNumber) continue;
          const probePage = parseKqtnFooterJobPage(page, pageNumber);
          const existing = pagesByNumber.get(pageNumber);
          if (!existing || (probePage.footerKey && !existing.footerKey) || (probePage.footerKey && probePage.footerKey !== existing.footerKey) || probePage.confidence >= Number(existing.confidence || 0)) {
            pagesByNumber.set(pageNumber, probePage);
          }
        }
        job.pages = [...pagesByNumber.values()].sort((left, right) => left.pageNumber - right.pageNumber);
        console.log("KQTN footer boundary probe completed: jobId=" + jobId + ", pages=" + boundaryProbePages.length + ", candidates=" + boundaryPages.length);
      }
      job.processedPages = job.totalPages;
      job.pages = [...pagesByNumber.values()].sort((left, right) => left.pageNumber - right.pageNumber);
      if (job.pages.length === 0) {
        throw new Error("PaddleOCR không trả về trang ứng viên footer nào.");
      }
      job.status = "completed";
      console.log("KQTN footer job completed: jobId=" + jobId + ", strategy=" + job.strategy + ", candidates=" + job.pages.length + "/" + job.totalPages + ", elapsed=" + processingSeconds + "s");
    } catch (error: any) {
      job.status = "failed";
      job.pages = [];
      job.error = error?.name === "AbortError"
        ? "PaddleOCR footer scan timed out."
        : error?.message || String(error);
      console.error("KQTN footer job failed: jobId=" + jobId, job.error);
    } finally {
      if (timeout) clearTimeout(timeout);
      controller = undefined;
      sourceBuffer = Buffer.alloc(0);
      footerWindows = [];
      expireKqtnFooterJob(jobId);
    }
  };

  const handleKqtnFooterJobUpload = (req: express.Request, res: express.Response, next: express.NextFunction) => {
    kqtnBulkSourceUpload.single("file")(req, res, (error: any) => {
      if (!error) {
        next();
        return;
      }
      const status = error?.code === "LIMIT_FILE_SIZE" ? 413 : 400;
      res.status(status).json({ code: "KQTN_FOOTER_JOB_UPLOAD_FAILED", error: error?.message || "Không thể nhận PDF scan." });
    });
  };

  app.post("/api/kqtn/ocr/footer-jobs", handleKqtnFooterJobUpload, (req, res) => {
    const file = req.file;
    if (!file) {
      res.status(400).json({ error: "A combined PDF file is required." });
      return;
    }
    if (file.buffer.subarray(0, 5).toString("ascii") !== "%PDF-") {
      res.status(415).json({ error: "Only valid PDF files are accepted." });
      return;
    }
    const hasActiveFooterJob = [...kqtnFooterJobs.values()].some((job) => job.status === "queued" || job.status === "running");
    if (hasActiveFooterJob && KQTN_FOOTER_JOB_MAX_ACTIVE <= 1) {
      res.status(429).json({ code: "KQTN_FOOTER_JOB_BUSY", error: "Đang có một PDF scan được OCR; vui lòng chờ job hiện tại hoàn tất." });
      return;
    }

    const parsedTotalPages = Number(req.body?.totalPages);
    const totalPages = Number.isFinite(parsedTotalPages) ? Math.max(0, Math.floor(parsedTotalPages)) : 0;
    const jobId = "kqtn-footer-" + randomUUID();
    const job: KqtnFooterJobRecord = {
      jobId,
      status: "queued",
      totalPages,
      processedPages: 0,
      pages: [],
      createdAt: Date.now(),
    };
    kqtnFooterJobs.set(jobId, job);
    console.log("KQTN footer job accepted: jobId=" + jobId + ", pages=" + totalPages + ", payloadBytes=" + file.buffer.length);
    void runKqtnFooterJob(jobId, file.buffer);
    res.status(202).json({
      jobId,
      status: job.status,
      strategy: job.strategy,
      totalPages: job.totalPages,
      processedPages: job.processedPages,
      pages: job.pages,
    });
  });

  app.get("/api/kqtn/ocr/footer-jobs/:jobId", (req, res) => {
    const jobId = String(req.params.jobId || "").trim();
    const job = kqtnFooterJobs.get(jobId);
    if (!job) {
      res.status(404).json({ code: "KQTN_FOOTER_JOB_NOT_FOUND", error: "Footer OCR job không còn tồn tại hoặc đã hết hạn." });
      return;
    }
    res.json({
      jobId: job.jobId,
      status: job.status,
      strategy: job.strategy,
      totalPages: job.totalPages,
      processedPages: job.processedPages,
      pages: job.pages,
      ...(job.error ? { error: job.error } : {}),
    });
  });


  app.post("/api/kqtn/:recordId/pdf", kqtnPdfUpload.single("file"), async (req, res) => {
    const recordId = String(req.params.recordId || "").trim();
    const file = req.file;
    if (!recordId) {
      res.status(400).json({ error: "Missing KQTN record id." });
      return;
    }
    if (!file) {
      res.status(400).json({ error: "A PDF file is required." });
      return;
    }
    if (file.mimetype !== "application/pdf" || file.buffer.subarray(0, 5).toString("ascii") !== "%PDF-") {
      res.status(415).json({ error: "Only valid PDF files are accepted." });
      return;
    }

    const bucketName = getKqtnStorageBucket();
    const sha256 = createHash("sha256").update(file.buffer).digest("hex");
    const objectPath = "kqtnRecords/" + sanitizeKqtnPathSegment(recordId) + "/result-" + sha256 + ".pdf";
    const assetId = "kqtn-pdf-" + sanitizeKqtnPathSegment(recordId) + "-" + sha256.slice(0, 16);
    try {
      const storage = getKqtnStorageClient();
      const existing = await pool.query(
        "SELECT data FROM app_documents WHERE collection_name = $1 AND document_id = $2",
        ["kqtnRecords", recordId],
      );
      if (existing.rows.length === 0) {
        res.status(404).json({ error: "KQTN record not found." });
        return;
      }
      const oldPdf = getKqtnPdfMetadata(existing.rows[0].data);
      await storage.ensurePrivateBucket(bucketName, KQTN_PDF_MAX_BYTES);
      await storage.uploadObject({
        bucketName,
        objectPath,
        body: file.buffer,
        mimeType: "application/pdf",
      });

      const metadata = {
        assetId,
        bucketName,
        objectPath,
        originalName: String(file.originalname || "result.pdf").replace(/[\\"]/g, "_").slice(0, 255),
        mimeType: "application/pdf",
        byteSize: file.size,
        sha256,
        uploadedAt: new Date().toISOString(),
        uploadedBy: String(req.headers["x-user-name"] || "KTV"),
      };

      try {
        await withPgTransaction(async (client) => {
          const locked = await client.query(
            "SELECT data FROM app_documents WHERE collection_name = $1 AND document_id = $2 FOR UPDATE",
            ["kqtnRecords", recordId],
          );
          if (locked.rows.length === 0) throw new Error("KQTN record not found.");
          const currentData = locked.rows[0].data || {};
          const currentPdf = getKqtnPdfMetadata(currentData);
          const nextData = { ...currentData, resultPdf: metadata };
          await client.query(
            "UPDATE app_documents SET data = $1::jsonb, updated_at = CURRENT_TIMESTAMP WHERE collection_name = $2 AND document_id = $3",
            [JSON.stringify(getDocumentPayload({ ...nextData, id: recordId })), "kqtnRecords", recordId],
          );
          if (currentPdf?.assetId) {
            await client.query("DELETE FROM file_assets WHERE id = $1", [currentPdf.assetId]);
          }
          await client.query(
            "INSERT INTO file_assets (id, bucket_name, object_path, source_collection, source_document_id, source_json_path, mime_type, byte_size, sha256) VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9) ON CONFLICT (id) DO UPDATE SET bucket_name = EXCLUDED.bucket_name, object_path = EXCLUDED.object_path, byte_size = EXCLUDED.byte_size, sha256 = EXCLUDED.sha256, updated_at = CURRENT_TIMESTAMP",
            [assetId, bucketName, objectPath, "kqtnRecords", recordId, "resultPdf", "application/pdf", file.size, sha256],
          );
        });
      } catch (error) {
        await storage.deleteObject({ bucketName, objectPath }).catch(() => undefined);
        throw error;
      }

      if (oldPdf?.objectPath && oldPdf.objectPath !== objectPath) {
        await storage.deleteObject({ bucketName: oldPdf.bucketName || bucketName, objectPath: oldPdf.objectPath }).catch((error) => {
          console.warn("Unable to remove replaced KQTN PDF object:", error);
        });
      }
      res.status(201).json({ recordId, resultPdf: metadata });
    } catch (error: any) {
      console.error("KQTN PDF upload error:", error);
      const status = String(error?.message || "").includes("storage is not configured") ? 503 : 500;
      res.status(status).json({ error: error?.message || String(error) });
    }
  });

  app.get("/api/kqtn/:recordId/pdf", async (req, res) => {
    const recordId = String(req.params.recordId || "").trim();
    try {
      const result = await pool.query(
        "SELECT data FROM app_documents WHERE collection_name = $1 AND document_id = $2",
        ["kqtnRecords", recordId],
      );
      const recordData = result.rows[0]?.data;
      const pdf = getKqtnPdfMetadata(recordData);
      if (!pdf) {
        res.status(404).json({ error: "KQTN PDF not found." });
        return;
      }
      if (req.query.download) {
        const paymentConfirmed = recordData?.customerPaymentConfirmed === true;
        if (!paymentConfirmed) {
          const username = getKqtnSessionUsername(req);
          if (!username) {
            res.status(401).json({ error: "Phiên đăng nhập KQTN không hợp lệ hoặc đã hết hạn." });
            return;
          }
          const role = await getSystemUserRoleByUsername(username);
          if (role !== "admin") {
            res.status(403).json({ error: "Chưa mở khóa tải PDF KQTN; cần xác nhận thanh toán với khách hàng." });
            return;
          }
        }
      }
      const storage = getKqtnStorageClient();
      const downloaded = await storage.downloadObject({
        bucketName: pdf.bucketName || getKqtnStorageBucket(),
        objectPath: pdf.objectPath,
      });
      res.setHeader("Content-Type", "application/pdf");
      res.setHeader("Content-Length", downloaded.body.byteLength);
      res.setHeader(
        "Content-Disposition",
        buildKqtnPdfContentDisposition(pdf.originalName, req.query.download ? "attachment" : "inline"),
      );
      res.send(downloaded.body);
    } catch (error: any) {
      console.error("KQTN PDF download error:", error);
      const status = String(error?.message || "").includes("storage is not configured") ? 503 : 500;
      res.status(status).json({ error: error?.message || String(error) });
    }
  });

  app.delete("/api/kqtn/:recordId/pdf", async (req, res) => {
    const recordId = String(req.params.recordId || "").trim();
    try {
      const result = await pool.query(
        "SELECT data FROM app_documents WHERE collection_name = $1 AND document_id = $2",
        ["kqtnRecords", recordId],
      );
      const pdf = getKqtnPdfMetadata(result.rows[0]?.data);
      if (!pdf) {
        res.status(404).json({ error: "KQTN PDF not found." });
        return;
      }
      const storage = getKqtnStorageClient();
      await storage.deleteObject({
        bucketName: pdf.bucketName || getKqtnStorageBucket(),
        objectPath: pdf.objectPath,
      });
      await withPgTransaction(async (client) => {
        const locked = await client.query(
          "SELECT data FROM app_documents WHERE collection_name = $1 AND document_id = $2 FOR UPDATE",
          ["kqtnRecords", recordId],
        );
        if (locked.rows.length === 0) throw new Error("KQTN record not found.");
        const data = { ...(locked.rows[0].data || {}) };
        delete data.resultPdf;
        await client.query(
          "UPDATE app_documents SET data = $1::jsonb, updated_at = CURRENT_TIMESTAMP WHERE collection_name = $2 AND document_id = $3",
          [JSON.stringify(getDocumentPayload({ ...data, id: recordId })), "kqtnRecords", recordId],
        );
        if (pdf.assetId) await client.query("DELETE FROM file_assets WHERE id = $1", [pdf.assetId]);
      });
      res.json({ deleted: true, recordId });
    } catch (error: any) {
      console.error("KQTN PDF delete error:", error);
      const status = String(error?.message || "").includes("storage is not configured") ? 503 : 500;
      res.status(status).json({ error: error?.message || String(error) });
    }
  });

  const handlePcnFileUpload = (req: express.Request, res: express.Response, nextMiddleware: express.NextFunction) => {
    pcnFileUpload.single('file')(req, res, (error: any) => {
      if (!error) {
        nextMiddleware();
        return;
      }
      const status = error?.code === 'LIMIT_FILE_SIZE' ? 413 : 400;
      res.status(status).json({ error: error?.message || 'Không thể nhận tệp PCN.' });
    });
  };

  app.post("/api/pcn/files", requirePcnMutationMiddleware, handlePcnFileUpload, async (req, res) => {
    if (DATABASE_PROFILE !== 'pcn') {
      res.status(404).json({ error: 'PCN file boundary chỉ khả dụng trong profile PCN.' });
      return;
    }

    const file = req.file;
    const sourceCollection = String(req.body?.sourceCollection || '').trim();
    const sourceDocumentId = String(req.body?.sourceDocumentId || '').trim();
    const sourceJsonPath = String(req.body?.sourceJsonPath || '').trim();
    if (!file) {
      res.status(400).json({ error: 'Cần chọn tệp PCN.' });
      return;
    }
    if (!PCN_FILE_UPLOAD_SOURCE_COLLECTIONS.has(sourceCollection)) {
      res.status(400).json({ error: 'Nguồn tệp PCN không hợp lệ.' });
      return;
    }
    if (sourceCollection === 'pcnQualityDocuments' && !requirePcnAdmin(req, res)) return;
    if (!sourceDocumentId || sourceDocumentId.length > 200 || /[\\/]/.test(sourceDocumentId)) {
      res.status(400).json({ error: 'Thiếu hoặc sai mã hồ sơ nguồn của tệp PCN.' });
      return;
    }
    if (!isSafePcnSourceJsonPath(sourceJsonPath)) {
      res.status(400).json({ error: 'Đường dẫn metadata nguồn của tệp PCN không hợp lệ.' });
      return;
    }
    const mimeType = String(file.mimetype || 'application/octet-stream').toLowerCase();
    if (mimeType !== 'application/pdf'
      && mimeType !== 'application/octet-stream'
      && mimeType !== 'application/msword'
      && mimeType !== 'application/vnd.openxmlformats-officedocument.wordprocessingml.document'
      && mimeType !== 'application/vnd.ms-excel'
      && mimeType !== 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
      && !mimeType.startsWith('image/')) {
      res.status(415).json({ error: 'Loại tệp PCN chưa được cho phép.' });
      return;
    }

    try {
      const source = await pool.query(
        'SELECT document_id, data FROM app_documents WHERE collection_name = $1 AND document_id = $2 LIMIT 1',
        [sourceCollection, sourceDocumentId],
      );
      if (source.rows.length === 0) {
        res.status(404).json({ error: 'Không tìm thấy hồ sơ nguồn của tệp PCN.' });
        return;
      }
      const sourceData = source.rows[0]?.data || {};
      if (sourceCollection === 'dossierDocuments') {
        if (String(sourceData.requirementId || '').trim() !== sourceJsonPath
          || buildPcnDossierDocumentId(String(sourceData.dossierId || '').trim(), sourceJsonPath) !== sourceDocumentId) {
          res.status(400).json({ error: 'Provenance checklist của tệp PCN không khớp.' });
          return;
        }
      } else if (sourceJsonPath !== 'fileAssetId') {
        res.status(400).json({ error: 'Đường dẫn metadata nguồn của tệp PCN không khớp loại tài liệu.' });
        return;
      }

      const storage = getPcnStorageClient();
      const bucketName = getPcnStorageBucket();
      const sha256 = createHash('sha256').update(file.buffer).digest('hex');
      const assetId = `pcn-file-${sha256.slice(0, 16)}-${randomUUID().slice(0, 8)}`;
      const originalName = sanitizePcnPathSegment(String(file.originalname || 'pcn-file'));
      const objectPath = `pcnFiles/${sanitizePcnPathSegment(sourceCollection)}/${sanitizePcnPathSegment(sourceDocumentId)}/${sanitizePcnPathSegment(sourceJsonPath)}/${assetId}-${sha256}-${originalName}`;

      await storage.ensurePrivateBucket(bucketName, PCN_FILE_MAX_BYTES);
      await storage.uploadObject({ bucketName, objectPath, body: file.buffer, mimeType });
      try {
        await pool.query(
          'INSERT INTO file_assets (id, bucket_name, object_path, source_collection, source_document_id, source_json_path, mime_type, byte_size, sha256) VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9)',
          [assetId, bucketName, objectPath, sourceCollection, sourceDocumentId, sourceJsonPath, mimeType, file.size, sha256],
        );
      } catch (error) {
        await storage.deleteObject({ bucketName, objectPath }).catch(() => undefined);
        throw error;
      }

      res.status(201).json({
        asset: {
          id: assetId,
          bucketName,
          objectPath,
          sourceCollection,
          sourceDocumentId,
          sourceJsonPath,
          mimeType,
          byteSize: file.size,
          sha256,
          originalName: String(file.originalname || 'pcn-file').slice(0, 255),
          createdAt: new Date().toISOString(),
        },
      });
    } catch (error: any) {
      console.error('PCN file upload error:', error);
      const message = String(error?.message || error);
      const status = message.includes('storage is not configured') ? 503 : 500;
      res.status(status).json({ error: message });
    }
  });

  app.post('/api/pcn/templates/:templateId/file', handlePcnFileUpload, async (req, res) => {
    if (!requirePcnAdmin(req, res)) return;
    const templateId = decodeURIComponent(String(req.params.templateId || '')).trim();
    if (!templateId || templateId.length > 200 || /[\\/]/.test(templateId)) {
      res.status(400).json({ error: 'Mã template PCN không hợp lệ.' });
      return;
    }
    const file = req.file;
    if (!file) {
      res.status(400).json({ error: 'Cần chọn file DOCX mới cho template PCN.' });
      return;
    }
    const fileName = String(file.originalname || '').trim();
    const mimeType = String(file.mimetype || 'application/octet-stream').toLowerCase();
    if (!fileName.toLowerCase().endsWith('.docx')
      || !['application/vnd.openxmlformats-officedocument.wordprocessingml.document', 'application/octet-stream'].includes(mimeType)) {
      res.status(415).json({ error: 'Template PCN phải là file DOCX hợp lệ.' });
      return;
    }

    const uploadedObjects: Array<{ bucketName: string; objectPath: string }> = [];
    try {
      const actor = getPcnSessionUser(req)!;
      const storage = getPcnStorageClient();
      const bucketName = getPcnStorageBucket();
      await storage.ensurePrivateBucket(bucketName, PCN_FILE_MAX_BYTES);
      const sha256 = createHash('sha256').update(file.buffer).digest('hex');
      const result = await withPgTransaction(async (client) => {
        await client.query('SELECT pg_advisory_xact_lock(hashtext($1))', [`pcn-template-upload:${templateId}`]);
        const existingResult = await client.query(
          `SELECT document_id, data FROM app_documents
           WHERE collection_name = 'pcnTemplateDefinitions' AND document_id = $1
           LIMIT 1 FOR UPDATE`,
          [templateId],
        );
        if (existingResult.rows.length === 0) throw Object.assign(new Error('Không tìm thấy template PCN cần thay file.'), { statusCode: 404 });
        const current = { ...(existingResult.rows[0].data || {}), id: existingResult.rows[0].document_id } as PcnTemplateDefinition;
        if (current.format !== 'DOCX') throw Object.assign(new Error('Chỉ template DOCX mới được thay file từ trang quản lý.'), { statusCode: 409 });

        const inspection = inspectPcnTemplateSource({
          fileName: 'template.docx',
          sourceRelativePath: 'template.docx',
          bytes: file.buffer,
        });
        if (inspection.warnings.includes('DOCX_NOT_READABLE')) {
          throw Object.assign(new Error('File DOCX không đọc được hoặc bị hỏng.'), { statusCode: 400 });
        }

        const currentAssetId = String(current.fileAssetId || '').trim();
        const assetId = PCN_FILE_ASSET_ID_PATTERN.test(currentAssetId)
          ? currentAssetId
          : `pcn-template-${templateId.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 80) || sha256.slice(0, 32)}`;
        const safeFileName = sanitizePcnPathSegment(fileName);
        const objectPath = `pcnTemplates/${sanitizePcnPathSegment(current.fieldCode)}/${sanitizePcnPathSegment(current.id)}/${sha256}/${safeFileName}`;
        const previousAssetResult = currentAssetId
          ? await client.query('SELECT object_path FROM file_assets WHERE id = $1 LIMIT 1', [currentAssetId])
          : { rows: [] };
        const previousObjectPath = previousAssetResult.rows[0]?.object_path ? String(previousAssetResult.rows[0].object_path) : undefined;

        await storage.uploadObject({ bucketName, objectPath, body: file.buffer, mimeType: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document' });
        if (previousObjectPath !== objectPath) uploadedObjects.push({ bucketName, objectPath });

        const now = new Date().toISOString();
        const next = replacePcnTemplateFileDefinition(current, {
          assetId,
          byteSize: file.buffer.length,
          sha256,
          placeholderKeys: inspection.placeholderKeys,
          importedByUsername: actor.username,
          importedAt: now,
        });
        await client.query(
          `INSERT INTO file_assets (id, bucket_name, object_path, source_collection, source_document_id, source_json_path, mime_type, byte_size, sha256)
           VALUES ($1, $2, $3, 'pcnTemplateDefinitions', $4, 'fileAssetId', $5, $6, $7)
           ON CONFLICT (id) DO UPDATE SET bucket_name = EXCLUDED.bucket_name, object_path = EXCLUDED.object_path,
             source_collection = EXCLUDED.source_collection, source_document_id = EXCLUDED.source_document_id,
             source_json_path = EXCLUDED.source_json_path, mime_type = EXCLUDED.mime_type,
             byte_size = EXCLUDED.byte_size, sha256 = EXCLUDED.sha256, updated_at = CURRENT_TIMESTAMP`,
          [assetId, bucketName, objectPath, templateId, 'application/vnd.openxmlformats-officedocument.wordprocessingml.document', file.buffer.length, sha256],
        );
        await client.query(
          `UPDATE app_documents SET data = $2::jsonb, updated_at = CURRENT_TIMESTAMP
           WHERE collection_name = 'pcnTemplateDefinitions' AND document_id = $1`,
          [templateId, JSON.stringify(getDocumentPayload(next))],
        );

        const activityLog = buildActivityLog({
          id: stablePcnMutationId('activity-pcn-template-upload', `${templateId}:${sha256}`),
          action: 'UPDATED',
          entityType: 'PCN_TEMPLATE',
          entityId: templateId,
          entityLabel: current.displayName,
          actorUsername: actor.username,
          actorName: actor.name,
          actorRole: actor.systemRole || actor.role,
          summary: `Thay file template DOCX ${current.displayName}`,
          source: 'UI',
          changes: diffActivityFields(current, next, ['fileAssetId', 'sourceFingerprint', 'placeholderKeys', 'status', 'approvedAt', 'approvedByUsername', 'importedByUsername', 'importedAt', 'annotation', 'sourceOriginalFingerprint']),
          createdAt: now,
        });
        const validationError = validateActivityLogPayload(activityLog);
        if (validationError) throw new Error(validationError);
        await client.query(
          `INSERT INTO app_documents (collection_name, document_id, data, updated_at)
           VALUES ('activityLogs', $1, $2::jsonb, CURRENT_TIMESTAMP)
           ON CONFLICT (collection_name, document_id) DO NOTHING`,
          [activityLog.id, JSON.stringify(getDocumentPayload(activityLog))],
        );

        return {
          template: { ...toPcnTemplateRuntimeProjection(next), privateAssetVerified: true },
          asset: {
            id: assetId,
            bucketName,
            objectPath,
            sourceCollection: 'pcnTemplateDefinitions',
            sourceDocumentId: templateId,
            sourceJsonPath: 'fileAssetId',
            mimeType: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
            byteSize: file.buffer.length,
            sha256,
            originalName: fileName.slice(0, 255),
            createdAt: now,
          },
          activityLog,
          previousObjectPath,
        };
      });
      if (result.previousObjectPath && result.previousObjectPath !== result.asset.objectPath) {
        await storage.deleteObject({ bucketName, objectPath: result.previousObjectPath }).catch(() => undefined);
      }
      res.status(200).json({ template: result.template, asset: result.asset, activityLog: result.activityLog });
    } catch (error: any) {
      for (const uploaded of uploadedObjects.reverse()) {
        await getPcnStorageClient().deleteObject(uploaded).catch(() => undefined);
      }
      console.error('PCN template file replacement error:', error);
      const message = String(error?.message || error);
      res.status(Number(error?.statusCode) || (message.includes('storage is not configured') ? 503 : 500)).json({ error: message });
    }
  });

  app.post('/api/pcn/issuance/:issuanceId/file', requirePcnMutationMiddleware, async (req, res) => {
    if (DATABASE_PROFILE !== 'pcn') {
      res.status(404).json({ error: 'Gắn file phát hành PCN chỉ khả dụng trong profile PCN.' });
      return;
    }
    const issuanceId = String(req.params.issuanceId || '').trim();
    const assetId = String(req.body?.assetId || '').trim();
    const fileName = String(req.body?.fileName || '').trim();
    const idempotencyKey = String(req.body?.idempotencyKey || '').trim();
    if (!isSafePcnSampleKey(issuanceId) || !PCN_FILE_ASSET_ID_PATTERN.test(assetId) || !isSafePcnSampleKey(idempotencyKey)) {
      res.status(400).json({ error: 'Mã bộ phát hành, file asset hoặc idempotencyKey không hợp lệ.' });
      return;
    }
    if (fileName.length > 255 || /[\\/]/.test(fileName)) {
      res.status(400).json({ error: 'Tên file phát hành không hợp lệ.' });
      return;
    }
    const actor = getPcnSessionUser(req)!;
    try {
      const result = await withPgTransaction(async (client) => {
        await client.query('SELECT pg_advisory_xact_lock(hashtext($1))', [`pcn-issuance-file:${issuanceId}:${assetId}`]);
        const issuanceResult = await client.query(
          `SELECT document_id, data FROM app_documents
           WHERE collection_name = 'issuancePackages' AND document_id = $1
           LIMIT 1 FOR UPDATE`,
          [issuanceId],
        );
        if (!issuanceResult.rows[0]) throw Object.assign(new Error('Không tìm thấy bộ phát hành cần đính kèm file.'), { statusCode: 404 });
        const issuance = mapDocumentRow(issuanceResult.rows[0]) as IssuancePackage;
        const dossierResult = await client.query(
          `SELECT document_id, data FROM app_documents
           WHERE collection_name = 'certificationDossiers' AND document_id = $1
           LIMIT 1 FOR UPDATE`,
          [issuance.dossierId],
        );
        if (!dossierResult.rows[0]) throw Object.assign(new Error('Không tìm thấy hồ sơ của bộ phát hành.'), { statusCode: 404 });
        const dossier = mapDocumentRow(dossierResult.rows[0]) as CertificationDossier;
        const assetResult = await client.query(
          `SELECT id, source_collection, source_document_id, source_json_path
           FROM file_assets WHERE id = $1 LIMIT 1 FOR UPDATE`,
          [assetId],
        );
        const asset = assetResult.rows[0];
        if (!asset) throw Object.assign(new Error('Không tìm thấy file asset phát hành.'), { statusCode: 404 });
        if (String(asset.source_collection) !== 'issuancePackages'
          || String(asset.source_document_id) !== issuanceId
          || String(asset.source_json_path) !== 'fileAssetIds') {
          throw Object.assign(new Error('File asset không trỏ đúng tới bộ phát hành cần đính kèm.'), { statusCode: 409 });
        }
        if ((issuance.fileAssetIds || []).includes(assetId)) return { issuance, dossier, idempotent: true as const };
        const now = new Date().toISOString();
        const nextIssuance: IssuancePackage = {
          ...issuance,
          fileAssetIds: Array.from(new Set([...(issuance.fileAssetIds || []), assetId])),
          updatedAt: now,
        };
        const nextDossier: CertificationDossier = { ...dossier, updatedAt: now };
        await client.query(
          `UPDATE app_documents SET data = $2::jsonb, updated_at = CURRENT_TIMESTAMP
           WHERE collection_name = 'issuancePackages' AND document_id = $1`,
          [nextIssuance.id, JSON.stringify(getDocumentPayload(nextIssuance))],
        );
        await client.query(
          `UPDATE app_documents SET data = $2::jsonb, updated_at = CURRENT_TIMESTAMP
           WHERE collection_name = 'certificationDossiers' AND document_id = $1`,
          [nextDossier.id, JSON.stringify(getDocumentPayload(nextDossier))],
        );
        const activityLog = buildActivityLog({
          id: stablePcnMutationId('activity-pcn-issuance-file', `${issuanceId}:${assetId}`),
          action: 'UPDATED',
          entityType: 'PCN_ISSUANCE',
          entityId: issuanceId,
          entityLabel: issuance.issuanceNumber || issuance.dossierId,
          actorUsername: actor.username,
          actorName: actor.name,
          actorRole: actor.systemRole || actor.role,
          summary: `Gắn file ${fileName || assetId} vào bộ phát hành`,
          source: 'UI',
          groupId: dossier.id,
          changes: diffActivityFields(issuance, nextIssuance, ['fileAssetIds']),
          createdAt: now,
        });
        const validationError = validateActivityLogPayload(activityLog);
        if (validationError) throw new Error(validationError);
        await client.query(
          `INSERT INTO app_documents (collection_name, document_id, data, updated_at)
           VALUES ('activityLogs', $1, $2::jsonb, CURRENT_TIMESTAMP)
           ON CONFLICT (collection_name, document_id) DO NOTHING`,
          [activityLog.id, JSON.stringify(getDocumentPayload({ ...activityLog, idempotencyKey }))],
        );
        return { issuance: nextIssuance, dossier: nextDossier, activityLog, idempotent: false as const };
      });
      res.status(200).json(result);
    } catch (error: any) {
      console.error('PCN issuance file pointer error:', error);
      const message = String(error?.message || error);
      res.status(Number(error?.statusCode) || 500).json({ error: message });
    }
  });

  app.post('/api/pcn/results/:resultId/file', requirePcnMutationMiddleware, async (req, res) => {
    if (DATABASE_PROFILE !== 'pcn') {
      res.status(404).json({ error: 'Gắn file KQTN PCN chỉ khả dụng trong profile PCN.' });
      return;
    }
    const resultId = String(req.params.resultId || '').trim();
    const assetId = String(req.body?.assetId || '').trim();
    const fileName = String(req.body?.fileName || '').trim();
    if (!isSafePcnSampleKey(resultId) || !PCN_FILE_ASSET_ID_PATTERN.test(assetId)) {
      res.status(400).json({ error: 'Mã KQTN hoặc file asset không hợp lệ.' });
      return;
    }
    if (fileName.length > 255 || /[\\/]/.test(fileName)) {
      res.status(400).json({ error: 'Tên file KQTN không hợp lệ.' });
      return;
    }
    const actor = getPcnSessionUser(req)!;
    try {
      const result = await withPgTransaction(async (client) => {
        await client.query('SELECT pg_advisory_xact_lock(hashtext($1))', [`pcn-result-file:${resultId}:${assetId}`]);
        const resultQuery = await client.query(
          `SELECT document_id, data FROM app_documents
           WHERE collection_name = 'returnedResults' AND document_id = $1
           LIMIT 1 FOR UPDATE`,
          [resultId],
        );
        if (!resultQuery.rows[0]) throw Object.assign(new Error('Không tìm thấy KQTN cần đính kèm file.'), { statusCode: 404 });
        const currentResult = mapDocumentRow(resultQuery.rows[0]) as ReturnedTestResult;
        const dossierQuery = await client.query(
          `SELECT document_id, data FROM app_documents
           WHERE collection_name = 'certificationDossiers' AND document_id = $1
           LIMIT 1 FOR UPDATE`,
          [currentResult.dossierId],
        );
        if (!dossierQuery.rows[0]) throw Object.assign(new Error('Không tìm thấy hồ sơ của KQTN.'), { statusCode: 404 });
        const dossier = mapDocumentRow(dossierQuery.rows[0]) as CertificationDossier;
        if (isPcnDossierPostApprovalLocked(dossier.status)) {
          throw Object.assign(new Error('Hồ sơ đã duyệt/phát hành; phải thu hồi có lý do trước khi gắn file KQTN.'), { statusCode: 409 });
        }
        assertPcnDossierOperator(dossier, actor);
        if (currentResult.fileAssetId) {
          if (currentResult.fileAssetId === assetId) return { result: currentResult, idempotent: true as const };
          throw Object.assign(new Error('KQTN này đã có file đính kèm khác.'), { statusCode: 409 });
        }
        if (currentResult.ocrEvidence && fileName !== currentResult.ocrEvidence.sourceFileName) {
          throw Object.assign(new Error('Tên file scan phải khớp với file đã dùng để xác nhận OCR KQTN.'), { statusCode: 409 });
        }

        const assetQuery = await client.query(
          `SELECT id, source_collection, source_document_id, source_json_path
           FROM file_assets WHERE id = $1 LIMIT 1 FOR UPDATE`,
          [assetId],
        );
        const asset = assetQuery.rows[0];
        if (!asset) throw Object.assign(new Error('Không tìm thấy file asset KQTN.'), { statusCode: 404 });
        if (String(asset.source_collection) !== 'returnedResults'
          || String(asset.source_document_id) !== resultId
          || String(asset.source_json_path) !== 'fileAssetId') {
          throw Object.assign(new Error('File asset không trỏ đúng tới KQTN cần đính kèm.'), { statusCode: 409 });
        }

        const now = new Date().toISOString();
        const nextResult: ReturnedTestResult = { ...currentResult, fileAssetId: assetId, updatedAt: now };
        await client.query(
          `UPDATE app_documents SET data = $2::jsonb, updated_at = CURRENT_TIMESTAMP
           WHERE collection_name = 'returnedResults' AND document_id = $1`,
          [resultId, JSON.stringify(getDocumentPayload(nextResult))],
        );
        const activityLog = buildActivityLog({
          id: stablePcnMutationId('activity-pcn-result-file', `${resultId}:${assetId}`),
          action: 'UPDATED',
          entityType: 'PCN_RESULT',
          entityId: resultId,
          entityLabel: nextResult.reportNumber || resultId,
          actorUsername: actor.username,
          actorName: actor.name,
          actorRole: actor.systemRole || actor.role,
          summary: `Gắn file ${fileName || assetId} vào KQTN trả về`,
          source: 'UI',
          groupId: nextResult.dossierId,
          changes: diffActivityFields(currentResult, nextResult, ['fileAssetId']),
          createdAt: now,
        });
        const validationError = validateActivityLogPayload(activityLog);
        if (validationError) throw new Error(validationError);
        await client.query(
          `INSERT INTO app_documents (collection_name, document_id, data, updated_at)
           VALUES ('activityLogs', $1, $2::jsonb, CURRENT_TIMESTAMP)
           ON CONFLICT (collection_name, document_id) DO NOTHING`,
          [activityLog.id, JSON.stringify(getDocumentPayload(activityLog))],
        );
        return { result: nextResult, activityLog, idempotent: false as const };
      });
      res.status(200).json(result);
    } catch (error: any) {
      console.error('PCN returned result file pointer error:', error);
      const message = String(error?.message || error);
      const status = Number(error?.statusCode) || 500;
      res.status(status).json({ error: message });
    }
  });

  app.get("/api/pcn/files/:assetId", requirePcnSessionMiddleware, async (req, res) => {
    if (DATABASE_PROFILE !== 'pcn') {
      res.status(404).json({ error: 'PCN file boundary chỉ khả dụng trong profile PCN.' });
      return;
    }
    const assetId = String(req.params.assetId || '').trim();
    if (!PCN_FILE_ASSET_ID_PATTERN.test(assetId)) {
      res.status(400).json({ error: 'Mã file asset PCN không hợp lệ.' });
      return;
    }
    try {
      const result = await pool.query(
        'SELECT id, bucket_name, object_path, source_collection, source_document_id, source_json_path, mime_type, byte_size, sha256 FROM file_assets WHERE id = $1',
        [assetId],
      );
      const asset = result.rows[0];
      if (!asset || !PCN_FILE_SOURCE_COLLECTIONS.has(String(asset.source_collection))) {
        res.status(404).json({ error: 'Không tìm thấy file asset PCN.' });
        return;
      }
      const storage = getPcnStorageClient();
      const downloaded = await storage.downloadObject({ bucketName: asset.bucket_name, objectPath: asset.object_path });
      const fileName = String(asset.object_path).split('/').pop() || 'pcn-file';
      res.setHeader('Content-Type', asset.mime_type || downloaded.contentType || 'application/octet-stream');
      res.setHeader('Content-Length', downloaded.body.byteLength);
      res.setHeader('Content-Disposition', buildPcnFileContentDisposition(fileName, String(req.query.download || '') === '1' ? 'attachment' : 'inline'));
      res.send(downloaded.body);
    } catch (error: any) {
      console.error('PCN file download error:', error);
      const message = String(error?.message || error);
      const status = message.includes('storage is not configured') ? 503 : 500;
      res.status(status).json({ error: message });
    }
  });

